function knownLiveAgent(agentId) {
  return LIVE_AGENTS.some((agent) => agent.id === agentId);
}

function defaultLiveAgentForId(agentId) {
  return DEFAULT_LIVE_AGENTS.find((agent) => agent.id === agentId || agent.stage === agentId) || null;
}

function normalizeLiveAgentManifestItem(item, index = 0) {
  const raw = item && typeof item === "object" ? item : {};
  const id = String(raw.id || raw.agent_id || raw.module_id || "").trim().toLowerCase().replace(/[^a-z0-9_-]+/g, "_");
  if (!id) return null;
  const fallback = defaultLiveAgentForId(id) || {};
  const label = String(raw.label || fallback.label || id).trim() || id;
  const short = String(raw.short || fallback.short || label.replace(/[^A-Za-z0-9]+/g, "").slice(0, 3).toUpperCase() || "AGT").trim();
  const stage = String(raw.stage || raw.graph_stage || fallback.stage || id).trim() || id;
  const moduleId = String(raw.module_id || raw.moduleId || fallback.moduleId || id).trim();
  const iconPath = String(raw.iconPath || raw.icon_path || raw.icon || fallback.iconPath || "").trim();
  return {
    ...fallback,
    ...raw,
    id,
    label,
    short,
    stage,
    moduleId,
    module_id: moduleId,
    handler: String(raw.handler || fallback.handler || "").trim(),
    kind: String(raw.kind || fallback.kind || (id === "objective" ? "ui_only" : "agent")).trim(),
    category: String(raw.category || fallback.category || "runtime").trim(),
    enabled: raw.enabled === undefined ? true : Boolean(raw.enabled),
    executionCapability: String(raw.execution_capability || raw.executionCapability || fallback.executionCapability || "").trim(),
    graphNodeId: String(raw.graph_node_id || raw.graphNodeId || fallback.graphNodeId || "").trim(),
    graphNodeKind: String(raw.graph_node_kind || raw.graphNodeKind || fallback.graphNodeKind || "").trim(),
    icon: String(raw.icon || fallback.icon || short.slice(0, 1) || "A").trim(),
    iconPath,
    chat: raw.chat && typeof raw.chat === "object" ? raw.chat : {},
    renderer: raw.renderer && typeof raw.renderer === "object" ? raw.renderer : {},
    cards: Array.isArray(raw.cards) ? raw.cards : [],
    reportSections: Array.isArray(raw.report_sections) ? raw.report_sections : Array.isArray(raw.reportSections) ? raw.reportSections : [],
    bridgeRefs: Array.isArray(raw.bridge_refs) ? raw.bridge_refs : Array.isArray(raw.bridgeRefs) ? raw.bridgeRefs : [],
    tools: Array.isArray(raw.tools) ? raw.tools : [],
    outputContracts: Array.isArray(raw.output_contracts) ? raw.output_contracts : Array.isArray(raw.outputContracts) ? raw.outputContracts : [],
    ioContract: raw.io_contract && typeof raw.io_contract === "object" ? raw.io_contract : {},
    safety: raw.safety && typeof raw.safety === "object" ? raw.safety : {},
    manifestSource: String(raw.source || "backend_manifest"),
    order: Number.isFinite(Number(raw.order)) ? Number(raw.order) : index,
  };
}

function applyLiveAgentManifest(payload) {
  const agents = Array.isArray(payload?.agents) ? payload.agents : [];
  const normalized = agents
    .map((item, index) => normalizeLiveAgentManifestItem(item, index))
    .filter(Boolean)
    .sort((a, b) => (a.order || 0) - (b.order || 0));
  if (!normalized.length || !normalized.some((agent) => agent.id === "orchestrator")) return false;
  if (!normalized.some((agent) => agent.id === "objective")) {
    const objective = normalizeLiveAgentManifestItem(defaultLiveAgentForId("objective") || DEFAULT_LIVE_AGENTS[0], -1);
    if (objective) normalized.unshift(objective);
  }
  LIVE_AGENTS = normalized;
  liveAgentManifestStatus = { ok: true, source: "/api/runtime/agent-manifests", error: "", graphId: payload.graph_id || "" };
  if (!knownLiveAgent(liveSelectedAgent)) liveSelectedAgent = "orchestrator";
  return true;
}

async function refreshLiveAgentManifest(options = {}) {
  try {
    const res = await fetch("/api/runtime/agent-manifests", { headers: { "Accept": "application/json" } });
    if (!res.ok) throw new Error(`agent manifest HTTP ${res.status}`);
    const payload = await res.json();
    if (!payload || payload.ok === false || !applyLiveAgentManifest(payload)) {
      throw new Error((payload && payload.error) || "agent manifest payload invalid");
    }
    if (liveLastSession && !options.skipRender) renderLiveRuntime(liveLastSession);
    return payload;
  } catch (err) {
    liveAgentManifestStatus = { ok: false, source: "fallback", error: String(err) };
    if (!options.silent) setChatStatus("MANIFEST FALLBACK", "warning", String(err));
    return { ok: false, agents: LIVE_AGENTS, error: String(err), fallback: true };
  }
}

const LIVE_CHAT_TARGET_SPECIALS = new Set(["current_agent", "selected_agent"]);

function validLiveChatTarget(target) {
  const value = String(target || "");
  return LIVE_CHAT_TARGET_SPECIALS.has(value) || (knownLiveAgent(value) && value !== "objective");
}

function liveChatTargetForAgent(agentId) {
  return validLiveChatTarget(agentId) ? String(agentId) : "selected_agent";
}

function setLiveChatTargetMode(target = "selected_agent") {
  if (!liveChatTarget) return;
  liveChatTarget.value = validLiveChatTarget(target) ? target : "selected_agent";
}

function setLiveBottomCollapsed(collapsed, options = {}) {
  liveBottomCollapsed = Boolean(collapsed);
  const shell = document.querySelector(".planning-runtime-shell");
  if (shell) shell.classList.toggle("live-bottom-collapsed", liveBottomCollapsed);
  document.body.classList.toggle("live-bottom-collapsed", liveBottomCollapsed);
  if (btnLiveBottomCollapse) {
    btnLiveBottomCollapse.setAttribute("aria-expanded", liveBottomCollapsed ? "false" : "true");
    setCompactTextWithTitle(
      btnLiveBottomCollapse,
      liveBottomCollapsed ? "Show Dock" : "Hide Dock",
      liveBottomCollapsed ? "Expand bottom event and IO dock" : "Collapse bottom event and IO dock"
    );
  }
  if (options.persist !== false) persistLiveUiState();
}

function liveRequestFrame(callback) {
  if (typeof window.requestAnimationFrame === "function") return window.requestAnimationFrame(callback);
  return window.setTimeout(() => callback(Date.now()), 16);
}

function liveCancelFrame(handle) {
  if (!handle) return;
  if (typeof window.cancelAnimationFrame === "function") window.cancelAnimationFrame(handle);
  else window.clearTimeout(handle);
}

function liveScrollableAncestor(target) {
  let element = target && target.nodeType === 1 ? target : document.body;
  while (element && element !== document.body) {
    const style = window.getComputedStyle(element);
    const canScrollY = /(auto|scroll|overlay)/.test(style.overflowY || "") && element.scrollHeight > element.clientHeight + 1;
    const canScrollX = /(auto|scroll|overlay)/.test(style.overflowX || "") && element.scrollWidth > element.clientWidth + 1;
    if (canScrollY || canScrollX) return element;
    element = element.parentElement;
  }
  return document.body;
}

function markLiveScrollActive(target) {
  const element = target === document || target === window || target === document.documentElement ? document.body : target;
  if (!element || !element.classList) return;
  element.classList.add("is-scrolling");
  const previousTimer = liveScrollFadeTimers.get(element);
  if (previousTimer) window.clearTimeout(previousTimer);
  const timer = window.setTimeout(() => {
    element.classList.remove("is-scrolling");
    liveScrollFadeTimers.delete(element);
  }, 900);
  liveScrollFadeTimers.set(element, timer);
}

function setupLiveScrollbarFade() {
  document.addEventListener("scroll", (event) => {
    markLiveScrollActive(liveScrollableAncestor(event.target || document.body));
  }, true);
  window.addEventListener("wheel", (event) => {
    markLiveScrollActive(liveScrollableAncestor(event.target || document.body));
  }, { passive: true });
}

const LIVE_CHAT_PERSISTENT_MODES = new Set(["persistent", "always", "required"]);
const LIVE_CHAT_ON_DEMAND_MODES = new Set(["open_on_demand", "on_demand", "collapsible", "contextual"]);
const LIVE_CHAT_DISABLED_MODES = new Set(["disabled", "none", "off", "hidden"]);

function liveAgentChatMode(agentId = liveSelectedAgent) {
  const clean = String(agentId || "").toLowerCase();
  const agent = LIVE_AGENTS.find((item) => item.id === clean || item.stage === clean) || {};
  const chat = agent.chat && typeof agent.chat === "object" && !Array.isArray(agent.chat) ? agent.chat : {};
  const explicitMode = String(chat.mode || chat.policy || "").trim().toLowerCase();
  if (explicitMode) return explicitMode;
  if (new Set(["objective", "orchestrator"]).has(clean)) return "persistent";
  return "open_on_demand";
}

function liveAgentAllowsOnDemandChat(agentId = liveSelectedAgent) {
  const mode = liveAgentChatMode(agentId);
  return !LIVE_CHAT_DISABLED_MODES.has(mode);
}

function liveAgentNeedsChatPanel(agentId = liveSelectedAgent) {
  if (liveReportPage === "attention") return true;
  const mode = liveAgentChatMode(agentId);
  return LIVE_CHAT_PERSISTENT_MODES.has(mode);
}

function liveChatCanManualCollapse(agentId = liveSelectedAgent) {
  return liveAgentNeedsChatPanel(agentId);
}

function liveChatUnreadLabel(count = liveChatUnreadCount) {
  const value = Math.max(0, Number(count) || 0);
  if (!value) return "";
  return value > 99 ? "99+" : String(value);
}

function isLiveUnreadChatMessage(msg) {
  if (!isChatSurfaceMessage(msg)) return false;
  if (isOperatorPlanningMessage(msg) || isPlanningSystemMessage(msg)) return false;
  return Boolean(msg?.pendingReasoning || String(msg?.content || "").trim());
}

function liveUnreadChatMessages(messages = planningMessagesCache) {
  return (messages || []).filter(isLiveUnreadChatMessage);
}

function markLiveChatMessagesRead(messages = planningMessagesCache) {
  const chatMessages = liveUnreadChatMessages(messages);
  liveChatReadWatermarkCount = chatMessages.length;
  liveChatReadWatermarkKey = chatMessages.length ? planningMessageKey(chatMessages[chatMessages.length - 1], chatMessages.length - 1) : "";
  liveChatUnreadCount = 0;
  liveChatUnreadInitialized = true;
  syncLiveChatUnreadIndicators();
}

function updateLiveChatUnreadFromMessages(messages = planningMessagesCache) {
  const chatMessages = liveUnreadChatMessages(messages);
  if (!liveChatUnreadInitialized) {
    markLiveChatMessagesRead(messages);
    return;
  }
  if (!liveChatCollapsed) {
    markLiveChatMessagesRead(messages);
    return;
  }
  const keys = chatMessages.map((msg, index) => planningMessageKey(msg, index));
  const baselineIndex = liveChatReadWatermarkKey ? keys.lastIndexOf(liveChatReadWatermarkKey) : -1;
  liveChatUnreadCount = baselineIndex >= 0
    ? Math.max(0, chatMessages.length - baselineIndex - 1)
    : Math.max(0, chatMessages.length - liveChatReadWatermarkCount);
  syncLiveChatUnreadIndicators();
}

function syncLiveChatUnreadIndicators(root = document) {
  const countLabel = liveChatUnreadLabel();
  const hasUnread = Boolean(countLabel);
  const targets = [
    root && root.querySelector ? root.querySelector('.live-report-action[data-report-action="toggle_chat"]') : null,
    btnLiveChatCollapse,
    btnLiveChatRestore,
  ].filter(Boolean);
  targets.forEach((element) => {
    element.classList.toggle("has-chat-unread", hasUnread);
    element.classList.toggle("is-chat-collapsed", liveChatCollapsed);
    element.dataset.chatUnreadCount = countLabel;
    element.dataset.chatAlertState = hasUnread ? "unread" : liveChatCollapsed ? "collapsed" : "idle";
    const opensAgentChat = element.dataset.chatActionMode === "open_agent";
    const baseLabel = opensAgentChat
      ? `Open Runtime Chat for ${element.dataset.chatAgentLabel || liveAgentLabel(liveSelectedAgent)}`
      : element.dataset.reportAction === "toggle_chat" || element === btnLiveChatRestore
        ? (liveChatCollapsed ? "Show Runtime Chat" : "Hide Runtime Chat")
        : "Collapse chat panel";
    const label = hasUnread ? `${baseLabel} (${countLabel} unread)` : baseLabel;
    element.setAttribute("aria-label", label);
    element.dataset.liveTooltip = label;
  });
}

function setLiveChatCollapsed(collapsed, options = {}) {
  const nextCollapsed = Boolean(collapsed);
  const changed = nextCollapsed !== liveChatCollapsed;
  liveChatCollapsed = nextCollapsed;
  if (options.resetUnread !== false && (changed || !liveChatUnreadInitialized)) markLiveChatMessagesRead();
  applyLiveAgentLayoutMode();
  if (changed) scheduleLiveGraphScaleRefresh();
  renderLiveReportToolbar();
  renderLiveExperimentSetupPanel(liveLastSession);
  syncLiveChatUnreadIndicators();
  if (options.persist !== false) persistLiveUiState();
}

function applyLiveAgentLayoutMode() {
  const agentNeedsChat = liveAgentNeedsChatPanel(liveSelectedAgent);
  const automaticReportFocus = !agentNeedsChat;
  const manualChatCollapsed = liveChatCollapsed && liveChatCanManualCollapse(liveSelectedAgent);
  const reportFocus = automaticReportFocus || manualChatCollapsed;
  const shell = document.querySelector(".planning-runtime-shell");
  if (shell) {
    shell.classList.toggle("live-agent-report-focus", reportFocus);
    shell.classList.toggle("live-chat-collapsed", manualChatCollapsed);
    shell.dataset.liveChatVisible = reportFocus ? "false" : "true";
    shell.dataset.liveChatCollapseMode = manualChatCollapsed ? "manual" : automaticReportFocus ? "auto" : "open";
  }
  document.body.classList.toggle("live-agent-report-focus", reportFocus);
  document.body.classList.toggle("live-chat-collapsed", manualChatCollapsed);
  const chatPanel = document.querySelector(".live-chat-panel");
  if (chatPanel) {
    chatPanel.setAttribute("aria-hidden", automaticReportFocus && !manualChatCollapsed ? "true" : "false");
    chatPanel.setAttribute("aria-label", manualChatCollapsed ? "experimental setup panel" : "persistent runtime chat");
    const chatEyebrow = chatPanel.querySelector(".live-chat-header .eyebrow");
    const chatTitle = chatPanel.querySelector(".live-chat-header h2");
    if (chatEyebrow) chatEyebrow.textContent = manualChatCollapsed ? "Setup" : "Runtime";
    if (chatTitle) chatTitle.textContent = manualChatCollapsed ? "Experimental Setup" : "Chat";
    chatPanel
      .querySelectorAll(".live-chat-context-controls, .live-chat-context-strip, .live-quick-actions, .planning-chat-window, .planning-chat-log, .planning-composer")
      .forEach((element) => {
        if (manualChatCollapsed) {
          element.setAttribute("aria-hidden", "true");
          element.style.setProperty("display", "none", "important");
          element.style.setProperty("visibility", "hidden", "important");
          element.style.setProperty("pointer-events", "none", "important");
        } else {
          element.removeAttribute("aria-hidden");
          element.style.removeProperty("display");
          element.style.removeProperty("visibility");
          element.style.removeProperty("pointer-events");
        }
      });
  }
  if (btnLiveChatCollapse) {
    const canCollapse = liveChatCanManualCollapse(liveSelectedAgent);
    btnLiveChatCollapse.hidden = !canCollapse || manualChatCollapsed;
    btnLiveChatCollapse.setAttribute("aria-expanded", manualChatCollapsed ? "false" : "true");
    setCompactTextWithTitle(
      btnLiveChatCollapse,
      "Hide",
      canCollapse ? "Collapse chat panel and expand current view" : "Chat panel follows agent view"
    );
  }
  if (btnLiveChatRestore) {
    btnLiveChatRestore.hidden = true;
    btnLiveChatRestore.setAttribute("aria-hidden", "true");
    btnLiveChatRestore.setAttribute("aria-expanded", "false");
    setCompactTextWithTitle(btnLiveChatRestore, "", "Runtime chat is opened from the top toolbar.");
  }
  syncLiveChatUnreadIndicators();
}

function scheduleLiveGraphScaleRefresh() {
  if (liveCurrentView !== "graph" || !liveLastSession) return;
  liveGraphFocusPending = true;
  liveCenterRenderKeys.delete("graph");
  liveRequestFrame(() => {
    if (liveCurrentView !== "graph" || !liveLastSession) return;
    renderActiveLiveCenterPanel(liveLastSession, { force: true });
  });
}

function currentRuntimeAgent() {
  const state = (liveLastSession && liveLastSession.state) || (liveLastSnapshot && liveLastSnapshot.state) || {};
  return agentIdFromStage(state.stage || "") || liveSelectedAgent || "orchestrator";
}

function selectedRuntimeContextAgent() {
  const event = typeof selectedTimelineEvent === "function" ? selectedTimelineEvent() : null;
  const eventAgent = event ? agentIdFromEvent(event) : "";
  return knownLiveAgent(eventAgent) ? eventAgent : (knownLiveAgent(liveSelectedAgent) ? liveSelectedAgent : "orchestrator");
}

function resolveLiveChatTarget(target = liveChatTarget ? liveChatTarget.value : "selected_agent") {
  const value = String(target || "selected_agent");
  if (value === "current_agent") return currentRuntimeAgent();
  if (value === "selected_agent") return selectedRuntimeContextAgent();
  return knownLiveAgent(value) ? value : selectedRuntimeContextAgent();
}

function liveUiStatePayload() {
  return {
    selectedAgent: knownLiveAgent(liveSelectedAgent) ? liveSelectedAgent : "orchestrator",
    currentView: LIVE_VIEW_IDS.has(liveCurrentView) ? liveCurrentView : "report",
    reportPage: liveReportPage === "attention" ? "attention" : "agent",
    selectedGraphNodeId: String(liveSelectedGraphNodeId || ""),
    selectedEventKey: String(liveSelectedEventKey || ""),
    graphSelectionCleared: Boolean(liveGraphSelectionCleared),
    selectedReportSectionTitle: String(liveSelectedReportSectionTitle || ""),
    timelineFilter: LIVE_TIMELINE_FILTER_IDS.has(liveTimelineFilter) ? liveTimelineFilter : "all",
    chatTarget: liveChatTarget && validLiveChatTarget(liveChatTarget.value) ? String(liveChatTarget.value) : "selected_agent",
    chatMode: liveChatMode ? String(liveChatMode.value || "ask") : "ask",
    bottomCollapsed: Boolean(liveBottomCollapsed),
    chatCollapsed: Boolean(liveChatCollapsed),
    expandedChatGroups: Array.from(planningExpandedChatGroups).slice(-120),
    planningSessionId: planningSessionId || "",
    updatedAt: new Date().toISOString(),
  };
}

function persistLiveUiState() {
  const storage = liveSessionStorage();
  if (!storage) return;
  try {
    storage.setItem(LIVE_UI_STATE_KEY, JSON.stringify(liveUiStatePayload()));
  } catch (err) {
    // Runtime operation must continue even when browser storage is unavailable.
  }
}

function collectLiveBoxCache() {
  const boxes = {};
  let totalChars = 0;
  LIVE_BOX_CACHE_IDS.forEach((id) => {
    const element = document.getElementById(id);
    if (!element) return;
    const html = String(element.innerHTML || "");
    if (!html.trim() || html.length > LIVE_BOX_CACHE_MAX_ITEM_CHARS) return;
    if (totalChars + html.length > LIVE_BOX_CACHE_MAX_TOTAL_CHARS) return;
    totalChars += html.length;
    boxes[id] = {
      html,
      hidden: Boolean(element.hidden),
      scrollTop: Number(element.scrollTop || 0),
    };
  });
  return {
    version: 1,
    savedAt: new Date().toISOString(),
    currentView: LIVE_VIEW_IDS.has(liveCurrentView) ? liveCurrentView : "report",
    selectedAgent: knownLiveAgent(liveSelectedAgent) ? liveSelectedAgent : "orchestrator",
    expandedChatGroups: Array.from(planningExpandedChatGroups).slice(-120),
    boxes,
  };
}

function trimLiveBoxCache(boxCache) {
  if (!boxCache || typeof boxCache !== "object") return null;
  const boxes = boxCache.boxes && typeof boxCache.boxes === "object" ? boxCache.boxes : {};
  const orderedIds = [
    liveCurrentView === "report" ? "live-report-panel" : "",
    liveCurrentView === "backend" ? "live-backend-panel" : "",
    liveCurrentView === "graph" ? "live-graph-panel" : "",
    liveCurrentView === "artifacts" ? "live-artifact-panel" : "",
    liveCurrentView === "timeline" ? "live-timeline-detail-panel" : "",
    "live-agent-binder-list",
    "live-focus-strip",
    "live-timeline-strip",
    "live-device-strip",
  ].filter(Boolean);
  const kept = {};
  let totalChars = 0;
  orderedIds.forEach((id) => {
    const item = boxes[id];
    if (!item || typeof item.html !== "string") return;
    if (item.html.length > LIVE_BOX_CACHE_MAX_ITEM_CHARS) return;
    if (totalChars + item.html.length > Math.floor(LIVE_BOX_CACHE_MAX_TOTAL_CHARS / 2)) return;
    totalChars += item.html.length;
    kept[id] = item;
  });
  return { ...boxCache, boxes: kept };
}

function applyCachedExpandedChatGroups(saved = {}) {
  if (!Array.isArray(saved.expandedChatGroups)) return;
  planningExpandedChatGroups.clear();
  saved.expandedChatGroups.forEach((key) => {
    const clean = String(key || "").trim();
    if (clean) planningExpandedChatGroups.add(clean);
  });
}

function restoreLiveBoxCache(boxCache) {
  if (!boxCache || typeof boxCache !== "object") return false;
  const boxes = boxCache.boxes && typeof boxCache.boxes === "object" ? boxCache.boxes : {};
  let restored = false;
  applyCachedExpandedChatGroups(boxCache);
  Object.entries(boxes).forEach(([id, item]) => {
    const element = document.getElementById(id);
    if (!element || !item || typeof item.html !== "string") return;
    element.innerHTML = item.html;
    const scrollTop = Number(item.scrollTop || 0);
    if (Number.isFinite(scrollTop) && scrollTop > 0) {
      liveRequestFrame(() => { element.scrollTop = scrollTop; });
    }
    restored = true;
  });
  if (LIVE_VIEW_IDS.has(boxCache.currentView)) liveCurrentView = boxCache.currentView;
  if (knownLiveAgent(boxCache.selectedAgent)) liveSelectedAgent = boxCache.selectedAgent;
  liveReportPage = boxCache.reportPage === "attention" ? "attention" : "agent";
  setLiveView(liveCurrentView, { render: false });
  syncLiveTooltipAttributes(document);
  return restored;
}

function planningSessionCacheKey(sessionId = "") {
  const clean = String(sessionId || planningSessionId || "").trim();
  return clean ? `${LIVE_SESSION_CACHE_KEY_PREFIX}${clean}` : "";
}

function compactPlanningStateForStorage(state = {}) {
  if (!state || typeof state !== "object") return {};
  const metadata = state.run_metadata && typeof state.run_metadata === "object" ? state.run_metadata : {};
  const compactMetadata = {};
  [
    "pending_specimen_input",
    "latest_orchestrator_followup",
    "latest_orchestrator_decision",
    "latest_orchestrator_handoff",
    "planning_cycle_contract",
    "safety_budget",
    "latest_mission_contract",
    "latest_orchestration_plan",
    "design_report",
    "design_candidate",
    "fabrication_report",
    "specimen_result",
    "vision_report",
    "vision_signal",
    "manipulation_report",
    "robot_task_result",
    "equipment_report",
    "equipment_result",
    "utm_data_ready",
    "equipment_handoff",
    "bo_agent",
    "bo_recommended_constraints",
    "knowledge",
    "guardian",
    "latest_guardian_decision",
  ].forEach((key) => {
    if (metadata[key] !== undefined) compactMetadata[key] = metadata[key];
  });
  return {
    run_id: state.run_id || "",
    experiment_id: state.experiment_id || "",
    mode: state.mode || "",
    stage: state.stage || "",
    active_goal: state.active_goal || "",
    current_experiment_spec: state.current_experiment_spec || {},
    current_experiment_objective: state.current_experiment_objective || {},
    is_paused: Boolean(state.is_paused),
    stop_requested: Boolean(state.stop_requested),
    safe_stop_requested: Boolean(state.safe_stop_requested),
    emergency_stop_requested: Boolean(state.emergency_stop_requested),
    loop_count: Number(state.loop_count || 0),
    run_metadata: compactMetadata,
  };
}

function compactPlanningSessionForStorage(session = {}) {
  const source = session && typeof session === "object" ? session : {};
  return {
    planning_session_id: source.planning_session_id || planningSessionId || "",
    message_total: Number(source.message_total || 0),
    messages_loaded: Number(source.messages_loaded || 0),
    message_limit: Number(source.message_limit || 0),
    has_more_messages: Boolean(source.has_more_messages),
    next_before: source.next_before ?? null,
    transcript_path: source.transcript_path || "",
    is_running: Boolean(source.is_running),
    is_planning_busy: Boolean(source.is_planning_busy),
    messages: Array.isArray(source.messages) ? source.messages.slice(-PLANNING_PERSIST_CACHE_MESSAGE_LIMIT) : [],
    state: compactPlanningStateForStorage(source.state || {}),
    runtime: source.runtime && typeof source.runtime === "object" ? { backend: source.runtime.backend, mode: source.runtime.mode, active_models: source.runtime.active_models } : {},
  };
}

function persistLivePlanningCache(session = liveLastSession) {
  const storage = liveSessionStorage();
  if (!storage) return;
  const sessionId = (session && session.planning_session_id) || planningSessionId || "";
  const key = planningSessionCacheKey(sessionId);
  if (!key) return;
  const cachedSession = compactPlanningSessionForStorage(session);
  const payload = {
    savedAt: new Date().toISOString(),
    planningSessionId: sessionId,
    session: cachedSession,
    snapshot: {
      state: cachedSession.state || {},
      runtime: cachedSession.runtime || {},
    },
    guardianStatus: typeof liveGuardianStatusPayload === "function" ? liveGuardianStatusPayload() : liveGuardianStatus,
    recentEvents: Array.isArray(liveRecentEvents) ? liveRecentEvents.slice(-30) : [],
    graph: null,
    boxes: collectLiveBoxCache(),
    ui: liveUiStatePayload(),
  };
  try {
    let serialized = JSON.stringify(payload);
    if (serialized.length > PLANNING_STORAGE_CACHE_MAX_CHARS) {
      payload.boxes = trimLiveBoxCache(payload.boxes);
      serialized = JSON.stringify(payload);
    }
    if (serialized.length > PLANNING_STORAGE_CACHE_MAX_CHARS) {
      payload.session.messages = payload.session.messages.slice(-20);
      payload.snapshot = { state: compactPlanningStateForStorage(payload.session.state || {}), runtime: payload.session.runtime || {} };
      payload.recentEvents = [];
      payload.boxes = trimLiveBoxCache(payload.boxes);
      serialized = JSON.stringify(payload);
    }
    storage.setItem(key, serialized);
  } catch (err) {
    try {
      payload.recentEvents = [];
      payload.graph = null;
      storage.setItem(key, JSON.stringify(payload));
    } catch (fallbackErr) {
      // Cache is opportunistic; never block Live GUI operation on storage quota.
    }
  }
}

function restoreCachedPlanningState() {
  const params = new URLSearchParams(window.location.search);
  if (params.get("fresh") === "1") return false;
  const storage = liveSessionStorage();
  const key = planningSessionCacheKey(ensurePlanningSessionId());
  if (!storage || !key) return false;
  try {
    const raw = storage.getItem(key) || "";
    if (!raw) return false;
    if (raw.length > PLANNING_STORAGE_CACHE_MAX_CHARS) {
      storage.removeItem(key);
      return false;
    }
    const payload = JSON.parse(raw);
    if (!payload || typeof payload !== "object" || !payload.session) return false;
    liveBrowserCacheRestoredRunId = String(
      (payload.session && payload.session.state && payload.session.state.run_id)
      || (payload.snapshot && payload.snapshot.state && payload.snapshot.state.run_id)
      || ""
    );
    liveLastSnapshot = payload.snapshot || liveLastSnapshot || {};
    liveGuardianStatus = normalizeGuardianStatusPayload(payload.guardianStatus) || liveGuardianStatus;
    liveRecentEvents = Array.isArray(payload.recentEvents) ? payload.recentEvents : liveRecentEvents;
    liveGraphPayload = payload.graph || liveGraphPayload;
    applyCachedExpandedChatGroups(payload.ui || {});
    applyPlanningSession(payload.session || {});
    const restoredBoxes = restoreLiveBoxCache(payload.boxes || null);
    if (restoredBoxes) persistLivePlanningCache(liveLastSession);
    setChatStatus("RESTORED", "idle", "Last browser-cached Live GUI state restored; server sync is running.");
    return true;
  } catch (err) {
    return false;
  }
}

function resetLiveRunScopedStateForAuthoritativeSession(serverSession = {}) {
  const serverRunId = String((serverSession.state && serverSession.state.run_id) || "");
  if (!serverRunId) return false;
  const previousRunId = String(
    liveAppliedAuthoritativeRunId
    || liveBrowserCacheRestoredRunId
    || (liveLastSession && liveLastSession.state && liveLastSession.state.run_id)
    || (liveLastSnapshot && liveLastSnapshot.state && liveLastSnapshot.state.run_id)
    || ""
  );
  liveAppliedAuthoritativeRunId = serverRunId;
  if (!previousRunId || previousRunId === serverRunId) {
    liveBrowserCacheRestoredRunId = serverRunId;
    return false;
  }

  const storage = liveSessionStorage();
  const key = planningSessionCacheKey(planningSessionId);
  if (storage && key) {
    try {
      storage.removeItem(key);
    } catch (err) {
      // Browser storage cleanup is best-effort; server state remains authoritative.
    }
  }

  liveRunEvents = [];
  liveRecentEvents = [];
  liveRunArtifacts = [];
  liveApprovals = { approvals: [], pending: [], resolved: [] };
  liveResolvedApprovalIds = new Set();
  liveReadQuestionKeys = {};
  liveReadFaultKeys = {};
  liveReadMarkers = {};
  liveReviewedAgents = {};
  livePinnedFindings = [];
  liveOperatorReportStateRunId = "";
  liveSelectedEventKey = "";
  liveGraphActionStatus = null;
  liveGuardianStatus = null;
  liveVisionSpecimenRetryCheckpoints.clear();
  liveRuntimeStartedAt = Date.now();
  resetPlanningMessageDisplayState();
  liveLastSnapshot = {
    state: serverSession.state || {},
    runtime: serverSession.runtime || {},
  };
  liveBrowserCacheRestoredRunId = serverRunId;
  clearLiveBoVisualization();
  if (planningChatLog) planningChatLog.innerHTML = "";
  return true;
}

function restoreLiveUiState() {
  const params = new URLSearchParams(window.location.search);
  const storage = liveSessionStorage();
  if (!storage) return;
  try {
    if (params.get("fresh") === "1") {
      storage.removeItem(LIVE_UI_STATE_KEY);
      return;
    }
    const saved = JSON.parse(storage.getItem(LIVE_UI_STATE_KEY) || "{}");
    if (knownLiveAgent(saved.selectedAgent)) liveSelectedAgent = saved.selectedAgent;
    if (LIVE_VIEW_IDS.has(saved.currentView)) liveCurrentView = saved.currentView;
    liveReportPage = saved.reportPage === "attention" ? "attention" : "agent";
    if (LIVE_TIMELINE_FILTER_IDS.has(saved.timelineFilter)) liveTimelineFilter = saved.timelineFilter;
    liveSelectedGraphNodeId = String(saved.selectedGraphNodeId || "");
    liveSelectedEventKey = String(saved.selectedEventKey || "");
    liveGraphSelectionCleared = Boolean(saved.graphSelectionCleared);
    liveSelectedReportSectionTitle = String(saved.selectedReportSectionTitle || liveSelectedReportSectionTitle || "Overview / Summary");
    applyCachedExpandedChatGroups(saved);
    if (liveChatMode && saved.chatMode) liveChatMode.value = String(saved.chatMode);
    if (liveChatTarget && validLiveChatTarget(saved.chatTarget)) liveChatTarget.value = saved.chatTarget;
    setLiveBottomCollapsed(Boolean(saved.bottomCollapsed), { persist: false });
    setLiveChatCollapsed(Boolean(saved.chatCollapsed), { persist: false, resetUnread: false });
    setLiveView(liveCurrentView);
  } catch (err) {
    // Ignore malformed or stale UI state.
  }
}

const LIVE_TOOLTIP_SELECTOR = [
  ".live-quick-action",
  ".live-report-action",
  ".live-chat-collapse",
  ".live-chat-restore",
  ".live-view-tab",
  ".live-selected-event-action",
  ".live-selected-node-action",
  ".live-question-action",
  ".live-fault-action",
  ".live-device-card",
  ".live-timeline-filter",
  ".live-timeline-item",
  ".binder-tab",
  ".runtime-chip",
  ".runtime-chip[title]",
  ".live-runtime-metrics span[title]",
  ".live-runtime-metrics span",
  ".planning-composer-actions .btn",
  ".planning-trigger-hint",
].join(", ");

function liveTooltipTarget(target) {
  if (!target || !target.closest || !document.body.classList.contains("planning-live-body")) return null;
  return target.closest(LIVE_TOOLTIP_SELECTOR);
}

function liveTooltipText(element) {
  if (!element) return "";
  return String(element.dataset.liveTooltip || element.getAttribute("aria-label") || element.getAttribute("title") || "").trim();
}

function syncLiveTooltipAttributes(root = document) {
  if (!root || !root.querySelectorAll) return;
  for (const element of root.querySelectorAll(LIVE_TOOLTIP_SELECTOR)) {
    if (!(element instanceof Element)) continue;
    const title = String(element.getAttribute("title") || "").trim();
    if (!title) continue;
    if (!element.dataset.liveTooltip) element.dataset.liveTooltip = title;
  }
}

function showLiveHoverTooltip(target) {
  if (!liveHoverTooltip) return;
  const element = liveTooltipTarget(target);
  const text = liveTooltipText(element);
  if (!element || !text) {
    hideLiveHoverTooltip();
    return;
  }
  liveHoverTooltip.textContent = text;
  liveHoverTooltip.hidden = false;
  const rect = element.getBoundingClientRect();
  const tipRect = liveHoverTooltip.getBoundingClientRect();
  const gap = 10;
  const maxLeft = Math.max(8, window.innerWidth - tipRect.width - 8);
  let left = rect.left + rect.width / 2 - tipRect.width / 2;
  let top = rect.bottom + gap;
  left = Math.min(maxLeft, Math.max(8, left));
  if (top + tipRect.height + 8 > window.innerHeight) {
    top = Math.max(8, rect.top - tipRect.height - gap);
  }
  liveHoverTooltip.style.left = `${Math.round(left)}px`;
  liveHoverTooltip.style.top = `${Math.round(top)}px`;
}

function hideLiveHoverTooltip() {
  if (!liveHoverTooltip) return;
  liveHoverTooltip.hidden = true;
  liveHoverTooltip.textContent = "";
}

const liveTooltipMutationObserver = new MutationObserver((mutations) => {
  for (const mutation of mutations) {
    for (const node of mutation.addedNodes || []) {
      if (!(node instanceof Element)) continue;
      syncLiveTooltipAttributes(node);
      for (const element of node.querySelectorAll ? node.querySelectorAll(LIVE_TOOLTIP_SELECTOR) : []) {
        if (element instanceof Element) syncLiveTooltipAttributes(element);
      }
    }
    if (mutation.target instanceof Element) syncLiveTooltipAttributes(mutation.target);
  }
});

function isLiveEditableTarget(target) {
  if (!target || !target.closest) return false;
  return Boolean(target.closest("input, textarea, select, [contenteditable='true']"));
}

function toggleLiveShortcutOverlay(force) {
  if (!liveShortcutOverlay) return false;
  const shouldShow = typeof force === "boolean" ? force : liveShortcutOverlay.hidden;
  liveShortcutOverlay.hidden = !shouldShow;
  if (shouldShow) hideLiveHoverTooltip();
  return shouldShow;
}

function liveShortcutKey(event) {
  return String(event.key || "").toLowerCase();
}

function runLiveKeyboardShortcut(event) {
  const key = liveShortcutKey(event);
  const editable = isLiveEditableTarget(event.target);
  if (key === "escape") {
    hideLiveHoverTooltip();
    toggleLiveShortcutOverlay(false);
    closeBinderContextMenu();
    return false;
  }
  if (!editable && key === "?" && !event.altKey && !event.ctrlKey && !event.metaKey) {
    event.preventDefault();
    toggleLiveShortcutOverlay();
    return true;
  }
  const modified = event.altKey && event.shiftKey && !event.ctrlKey && !event.metaKey;
  if (!modified) return false;
  const safetyShortcut = key === "x";
  if (editable && !safetyShortcut) return false;
  const viewByKey = { r: "report", b: "backend", g: "graph", a: "artifacts", t: "timeline" };
  const actionByKey = { d: "dry_run", n: "run_node_test", p: "pause_run", o: "resume_run", x: "safe_stop" };
  if (viewByKey[key]) {
    event.preventDefault();
    setLiveView(viewByKey[key]);
    renderLiveRuntime(liveLastSession);
    setChatStatus(String(viewByKey[key]).toUpperCase(), "idle");
    return true;
  }
  if (key === "u") {
    event.preventDefault();
    refreshPlanningState();
    setChatStatus("REFRESH", "running");
    return true;
  }
  const action = actionByKey[key];
  if (action) {
    event.preventDefault();
    const useBusyLock = LIVE_BUSY_QUICK_ACTIONS.has(action);
    if (liveQuickActionBusy && action !== "safe_stop") return true;
    if (useBusyLock) setLiveQuickActionBusy(true);
    runLiveQuickAction(action).catch((err) => {
      setChatStatus("SHORTCUT ERROR", "warning");
      renderPlanningMessages([...planningMessagesCache, { role: "system", content: `Shortcut action failed: ${err}` }]);
    }).finally(() => {
      if (useBusyLock) setLiveQuickActionBusy(false);
    });
    return true;
  }
  return false;
}

function persistPlanningSessionId(sessionId) {
  const clean = String(sessionId || "").trim();
  if (!clean) return planningSessionId;
  planningSessionId = clean;
  const storage = liveSessionStorage();
  if (storage) {
    try {
      storage.setItem("autonomousLivePlanningSessionId", clean);
    } catch (err) {
      // Keep the in-memory id when storage is unavailable.
    }
  }
  return clean;
}

function ensurePlanningSessionId() {
  const key = "autonomousLivePlanningSessionId";
  const params = new URLSearchParams(window.location.search);
  const storage = liveSessionStorage();
  try {
    if (params.get("fresh") === "1" && !planningFreshSessionInitialized) {
      if (storage) storage.removeItem(key);
      planningFreshSessionInitialized = true;
    }
    let existing = storage ? storage.getItem(key) : "";
    if (!existing) {
      existing = planningSessionId || `live-${Date.now()}-${Math.random().toString(16).slice(2)}`;
      if (storage) storage.setItem(key, existing);
    }
    planningSessionId = existing;
    return existing;
  } catch (err) {
    if (!planningSessionId) {
      planningSessionId = `live-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    }
    return planningSessionId;
  }
}

function applyQueryGoal() {
  const params = new URLSearchParams(window.location.search);
  queryGoal = params.get("goal") || queryGoal;
  queryBackend = params.get("backend") || queryBackend;
  if (planningGoalInput) {
    planningGoalInput.value = queryGoal;
  }
  if (planningMaterialInput && params.get("material")) {
    planningMaterialInput.value = params.get("material");
  }
  if (planningSizeInput && params.get("size")) {
    planningSizeInput.value = params.get("size");
  }
  if (planningTimeInput && params.get("max_print_time_min")) {
    planningTimeInput.value = params.get("max_print_time_min");
  }
}

function setPlanningDot(isRunning) {
  if (!planningStateDot) return;
  planningStateDot.className = "status-dot";
  planningStateDot.classList.add(isRunning ? "busy" : "idle");
}

function renderSpecSummary(state) {
  if (!planningSpecSummary) return;
  const spec = state.current_experiment_spec || {};
  if (!Object.keys(spec).length) {
    planningSpecSummary.innerHTML = "";
    return;
  }
  planningSpecSummary.innerHTML = `
    <div class="log-entry">
      <small>current_experiment_spec</small>
      <pre>${escapeHtml(JSON.stringify(spec, null, 2))}</pre>
    </div>
  `;
}

function parseSize(value, fallback = [30, 30, 30]) {
  const parts = String(value || "")
    .split(/[,xX×\s]+/)
    .map((item) => Number(item.trim()))
    .filter((item) => Number.isFinite(item));
  return parts.length === 3 ? parts : fallback;
}

function collectOptionalConstraints() {
  const selectedEvent = typeof selectedTimelineEvent === "function" ? selectedTimelineEvent() : null;
  const selectedPayload = selectedEvent ? eventPayload(selectedEvent) : {};
  const session = liveLastSession || {};
  const snapshot = liveLastSnapshot || {};
  const state = session.state || snapshot.state || {};
  const chatTargetMode = liveChatTarget && validLiveChatTarget(liveChatTarget.value) ? liveChatTarget.value : "selected_agent";
  const chatTargetResolved = resolveLiveChatTarget(chatTargetMode);
  const constraints = {
    require_operator_approval: true,
    runtime_contract: "existing_stage_enum_only",
    live_run_id: state.run_id || "",
    live_mode: state.mode || "",
    live_stage: state.stage || "",
    live_is_running: liveRunningFlag(session, snapshot, state),
    live_active_goal: state.active_goal || "",
    live_chat_target: chatTargetResolved,
    live_chat_target_mode: chatTargetMode,
    live_chat_target_resolved: chatTargetResolved,
    live_chat_mode: liveChatMode ? liveChatMode.value : "ask",
    live_selected_agent: liveSelectedAgent,
    live_selected_view: liveCurrentView,
    live_selected_graph_node_id: liveSelectedGraphNodeId,
    live_selected_event_key: liveSelectedEventKey,
    live_selected_event_id: selectedEvent ? (selectedEvent.event_id || selectedEvent.id || selectedPayload.event_id || "") : "",
    live_selected_trace_id: selectedEvent ? (selectedEvent.trace_id || selectedPayload.trace_id || "") : "",
    live_selected_node_id: selectedEvent ? (selectedEvent.node_id || selectedPayload.node_id || "") : "",
    live_selected_event_type: selectedEvent ? (selectedEvent.event_type || selectedEvent.type || "") : "",
    live_selected_report_section: selectedReportSectionLabel(),
    live_selected_report_section_text: selectedReportSectionText(),
    live_timeline_filter: liveTimelineFilter,
    live_pinned_findings: livePinnedFindings.slice(0, 5),
  };
  if (planningMaterialInput && planningMaterialInput.value.trim()) {
    constraints.material = planningMaterialInput.value.trim();
  }
  if (planningSizeInput && planningSizeInput.value.trim()) {
    const size = parseSize(planningSizeInput.value, null);
    if (size) {
      constraints.max_specimen_size_mm = size;
      constraints.specimen_size_mm = size;
    }
  }
  if (planningTimeInput && planningTimeInput.value.trim()) {
    constraints.max_print_time_min = Number(planningTimeInput.value);
  }
  return constraints;
}

function collectPlanningPayload(message, options = {}) {
  const constraints = collectOptionalConstraints();
  if (options.runtimeFollowupQueueOnly) {
    constraints.live_runtime_followup_queue_only = true;
    constraints.live_followup_source = "live_gui_busy_chat";
  }
  return {
    message,
    goal: planningGoalInput ? planningGoalInput.value : queryGoal,
    backend: queryBackend,
    session_id: ensurePlanningSessionId(),
    constraints,
  };
}

function setLiveOrchestratorReady(isReady) {
  if (!isReady || liveOrchestratorReady) return;
  liveOrchestratorReady = true;
  document.body?.classList.add("live-orchestrator-ready");
  liveRuntimeTitle?.classList.add("orchestrator-ready");
}

function liveTopbarStatusText(label) {
  const normalized = String(label || "").trim().toUpperCase();
  if (!normalized) return "Ready";
  if (normalized.includes("ERROR") || normalized.includes("ISSUE")) return "Issue";
  if (normalized.includes("APPROVAL")) return "Approval";
  if (normalized === "WAITING_USER") return "WAITING_USER";
  if (normalized.includes("SAFE STOP") || normalized.includes("EMERGENCY")) return "Stop";
  if (normalized === "BUSY") return "BUSY";
  if (normalized.includes("REASONING") || normalized.includes("SENDING") || normalized.includes("QUEUING")) return "Working";
  if (normalized === "READY" || normalized === "RESTORED" || normalized === "GRAPH OK") return "Ready";
  if (normalized.startsWith("SECTION:")) return "Section";
  return compactText(liveHumanizeStatus(label, "Ready"), 16);
}

function setChatStatus(label, cls = "idle", title = null) {
  if (!planningChatStatus) return;
  planningChatStatus.textContent = liveTopbarStatusText(label);
  planningChatStatus.className = `badge ${cls}`;
  planningChatStatus.title = title || label;
  const normalizedLabel = String(label || "").trim().toUpperCase();
  if (normalizedLabel === "READY" && cls !== "warning" && cls !== "error") {
    setLiveOrchestratorReady(true);
  }
}

function relativeTimeLabel(value) {
  const date = value instanceof Date ? value : new Date(value || "");
  const ms = date.getTime();
  if (!Number.isFinite(ms)) return "-";
  const diff = Math.max(0, Math.round((Date.now() - ms) / 1000));
  if (diff < 2) return "now";
  if (diff < 60) return `${diff}s ago`;
  const minutes = Math.floor(diff / 60);
  if (minutes < 60) return `${minutes}m ago`;
  return `${Math.floor(minutes / 60)}h ago`;
}

function setRuntimeChip(chip, label, cls, title) {
  if (!chip) return;
  chip.textContent = label;
  chip.className = `runtime-chip ${cls || "idle"}`;
  if (title) chip.title = title;
}

function updateLiveConnectionChips() {
  const streamClass = liveStreamState === "live" ? "ok" : liveStreamState === "error" ? "warning" : "idle";
  const streamLabel = liveStreamState === "live"
    ? "SSE Live"
    : liveStreamState === "error"
      ? "SSE Issue"
      : liveStreamState === "connecting"
        ? "SSE Connecting"
        : "SSE Idle";
  const streamTitle = liveLastEventAt
    ? `Runtime event stream: ${liveStreamState}. Last event ${new Date(liveLastEventAt).toLocaleString()}`
    : `Runtime event stream: ${liveStreamState}. Waiting for first event.`;
  setRuntimeChip(liveStreamChip, streamLabel, streamClass, streamTitle);

  const syncTimestamp = liveLastSyncAt ? new Date(liveLastSyncAt).getTime() : NaN;
  const syncAgeMs = Number.isFinite(syncTimestamp) ? Date.now() - syncTimestamp : Infinity;
  let displayedSyncState = liveSyncState;
  if (liveSyncState !== "refreshing" && liveSyncState !== "error") {
    if (!Number.isFinite(syncTimestamp)) displayedSyncState = "idle";
    else if (syncAgeMs > LIVE_SYNC_ERROR_MS) displayedSyncState = "error";
    else if (syncAgeMs > LIVE_SYNC_STALE_MS) displayedSyncState = "stale";
    else displayedSyncState = "ok";
  }
  const syncAge = liveLastSyncAt ? relativeTimeLabel(liveLastSyncAt) : "-";
  const syncClass = displayedSyncState === "ok" ? "ok" : displayedSyncState === "refreshing" ? "running" : displayedSyncState === "stale" ? "warning" : displayedSyncState === "error" ? "error" : "idle";
  const failureText = liveSyncFailureCount ? ` Failures: ${liveSyncFailureCount}.` : "";
  const syncTitle = liveLastSyncAt
    ? `Last state sync ${new Date(liveLastSyncAt).toLocaleString()}. State: ${displayedSyncState}.${failureText}`
    : `No state sync completed yet. State: ${displayedSyncState}.${failureText}`;
  const syncLabel = displayedSyncState === "refreshing"
    ? "Syncing"
    : displayedSyncState === "ok"
      ? `Sync ${syncAge}`
      : displayedSyncState === "stale"
        ? `Sync stale ${syncAge}`
      : displayedSyncState === "error"
          ? "Sync issue"
          : "Sync waiting";
  setRuntimeChip(liveSyncChip, syncLabel, syncClass, syncTitle);
}

function markLiveSyncRefreshStart() {
  liveSyncState = "refreshing";
  updateLiveConnectionChips();
}

function markLiveSyncComplete() {
  liveSyncState = "ok";
  liveSyncFailureCount = 0;
  liveLastSyncAt = new Date().toISOString();
  updateLiveConnectionChips();
}

function markLiveSyncError(err) {
  liveSyncState = "error";
  liveSyncFailureCount += 1;
  if (err && liveSyncChip) liveSyncChip.dataset.lastError = String(err);
  updateLiveConnectionChips();
}

function liveSyncIsStale() {
  if (!liveLastSyncAt) return true;
  const last = new Date(liveLastSyncAt).getTime();
  return !Number.isFinite(last) || Date.now() - last > LIVE_AUTO_REFRESH_MS;
}

function markLiveStreamState(state, eventTs = null) {
  liveStreamState = state || liveStreamState;
  if (eventTs) liveLastEventAt = eventTs;
  updateLiveConnectionChips();
}

function updatePlanningControls() {
  const runtimeBusy = planningThinkingCount > 0 || liveQuickActionBusy || liveBackendPlanningBusy;
  if (btnPlanningSend) {
    btnPlanningSend.disabled = planningMessageSubmitInFlight || runtimeBusy;
    btnPlanningSend.title = runtimeBusy
      ? "Backend orchestrator is still reasoning in this session"
      : "Send message (Ctrl+Enter)";
  }
  if (btnPlanningGenerate) {
    btnPlanningGenerate.disabled = runtimeBusy;
    btnPlanningGenerate.title = runtimeBusy ? "Backend orchestrator is still reasoning in this session" : "Draft Plan";
  }
}

function setLiveBackendPlanningBusy(isBusy) {
  liveBackendPlanningBusy = Boolean(isBusy);
  if (planningChatStatus) {
    planningChatStatus.dataset.backendBusy = liveBackendPlanningBusy ? "1" : "0";
  }
  if (liveBackendPlanningBusy && planningThinkingCount === 0) {
    setChatStatus("BUSY", "running");
  } else if (!liveBackendPlanningBusy && planningChatStatus && planningChatStatus.textContent === "BUSY") {
    setChatStatus("READY", "idle");
  }
  updatePlanningControls();
}

function setLiveQuickActionBusy(isBusy) {
  liveQuickActionBusy = Boolean(isBusy);
  liveQuickActionButtons.forEach((button) => {
    const isSafeStop = button.dataset.quickAction === "safe_stop";
    button.disabled = liveQuickActionBusy && !isSafeStop;
    button.classList.toggle("is-busy", liveQuickActionBusy && !isSafeStop);
  });
  updatePlanningControls();
}

function resetLiveSafeStopArm() {
  liveSafeStopArmedUntil = 0;
  if (liveSafeStopArmTimer) {
    window.clearTimeout(liveSafeStopArmTimer);
    liveSafeStopArmTimer = null;
  }
  liveQuickActionButtons.forEach((button) => {
    if (button.dataset.quickAction === "safe_stop") {
      button.classList.remove("is-armed");
      button.title = "Safe Stop (Alt+Shift+X)";
      button.setAttribute("aria-label", "Safe Stop");
    }
  });
}

function armLiveSafeStop() {
  liveSafeStopArmedUntil = Date.now() + 6000;
  if (liveSafeStopArmTimer) window.clearTimeout(liveSafeStopArmTimer);
  liveSafeStopArmTimer = window.setTimeout(resetLiveSafeStopArm, 6000);
  liveQuickActionButtons.forEach((button) => {
    if (button.dataset.quickAction === "safe_stop") {
      button.classList.add("is-armed");
      button.title = "Safe Stop armed. Click again within 6 seconds to request safe stop.";
      button.setAttribute("aria-label", "Confirm Safe Stop");
    }
  });
  setChatStatus("SAFE STOP?", "warning");
}

async function fetchJsonOrThrow(url, options = {}) {
  const res = await fetch(url, options);
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.ok === false) {
    throw new Error(data.detail || data.message || `HTTP ${res.status}`);
  }
  return data;
}

async function fetchJsonOrThrowWithTimeout(url, options = {}, timeoutMs = 3000) {
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetchJsonOrThrow(url, { ...options, signal: controller.signal });
  } finally {
    window.clearTimeout(timer);
  }
}

function pushPlanningThinking() {
  planningThinkingCount += 1;
  updatePlanningControls();
}

function popPlanningThinking() {
  planningThinkingCount = Math.max(0, planningThinkingCount - 1);
  updatePlanningControls();
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function normalizeDisplayText(value) {
  return String(value || "")
    .replace(/\$\\leftrightarrow\$/g, "<->")
    .replace(/\$\\Leftarrow\$/g, "<=")
    .replace(/\$\\leftarrow\$/g, "<-")
    .replace(/\$\\Rightarrow\$/g, "=>")
    .replace(/\$\\rightarrow\$/g, "->")
    .replace(/\$\\to\$/g, "->")
    .replace(/\$\\dashrightarrow\$/g, "->")
    .replace(/\\leftrightarrow/g, "<->")
    .replace(/\\Leftarrow/g, "<=")
    .replace(/\\leftarrow/g, "<-")
    .replace(/\\Rightarrow/g, "=>")
    .replace(/\\rightarrow/g, "->")
    .replace(/\\to/g, "->")
    .replace(/\\dashrightarrow/g, "->");
}

function safeUrl(value) {
  const url = String(value || "");
  return url.startsWith("/api/planning/artifacts/") ? url : "";
}

function roleLabel(role) {
  const labels = {
    orchestrator: "Orchestrator",
    operator: "Operator",
    design_ai: "Design Agent",
    specimen_ai: "Specimen Making Agent",
    printer_ai: "Specimen Making Agent",
    vision_ai: "Vision Agent",
    manipulation_ai: "Manipulation Agent",
    equipment_ai: "Lab Equipment Agent",
    analysis_ai: "Analysis Agent",
    knowledge_ai: "Knowledge Agent",
    bo_ai: "BO Agent",
    guardian: "Guardian Agent",
    system: "System",
  };
  return labels[role] || role || "Orchestrator";
}

function messageSurfaces(msg) {
  const value = msg && (msg.surface || msg.surfaces);
  if (Array.isArray(value)) return value.map((item) => String(item || "").toLowerCase()).filter(Boolean);
  if (typeof value === "string") return value.split(/[\s,]+/).map((item) => item.toLowerCase()).filter(Boolean);
  return [];
}

function parsePlanningSystemEvent(content) {
  const text = String(content || "").trim();
  if (!text.startsWith("SYSTEM_EVENT:")) return null;
  const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  const name = lines.length ? lines[0].split(":").slice(1).join(":").trim() : "SYSTEM_EVENT";
  const fields = {};
  for (const line of lines.slice(1)) {
    const index = line.indexOf("=");
    if (index < 0) continue;
    const key = line.slice(0, index).trim().replace(/[^a-zA-Z0-9_]+/g, "_").replace(/^_+|_+$/g, "").toLowerCase();
    if (key) fields[key] = line.slice(index + 1).trim();
  }
  return { name: name || "SYSTEM_EVENT", fields };
}

function isPlanningSystemMessage(msg) {
  return Boolean(parsePlanningSystemEvent(msg && msg.content));
}

function isChatSurfaceMessage(msg) {
  if (!msg || typeof msg !== "object") return false;
  if (msg.pendingReasoning) return true;
  if (isPlanningSystemMessage(msg)) return true;
  const role = String(msg.role || "").toLowerCase();
  const messageClass = String(msg.message_class || "").toLowerCase();
  const surfaces = messageSurfaces(msg);
  if (surfaces.length) return surfaces.includes("chat");
  if (role === "system" && !isPlanningSystemMessage(msg)) return false;
  if (["system_event", "handoff_event", "tool_event", "artifact_event"].includes(messageClass)) return false;
  return Boolean(String(msg.content || "").trim()) || role === "operator";
}

function isOperatorPlanningMessage(msg) {
  const role = String(msg?.role || "").toLowerCase();
  return ["operator", "user", "human", "client"].includes(role);
}

function planningMessageEventFields(msg) {
  if (!msg || typeof msg !== "object") return {};
  if (msg.event_fields && typeof msg.event_fields === "object") return msg.event_fields;
  const parsed = parsePlanningSystemEvent(msg.content || "");
  return parsed && parsed.fields ? parsed.fields : {};
}

function planningMessageCycleIndex(msg) {
  if (!msg || typeof msg !== "object") return 0;
  const direct = Number(msg.cycle_index || msg.cycle || 0);
  if (Number.isFinite(direct) && direct > 0) return Math.floor(direct);
  const fields = planningMessageEventFields(msg);
  const fieldCycle = Number(fields.cycle_index || fields.cycle || 0);
  if (Number.isFinite(fieldCycle) && fieldCycle > 0) return Math.floor(fieldCycle);
  const text = String(msg.content || "");
  const match = text.match(/\bcycle\s*[=:]?\s*(\d+)\s*(?:\/\s*(\d+))?/i);
  if (match) {
    const value = Number(match[1]);
    if (Number.isFinite(value) && value > 0) return Math.floor(value);
  }
  return 0;
}

function planningMessageTotalCycles(msg) {
  if (!msg || typeof msg !== "object") return 0;
  const direct = Number(msg.total_cycles || 0);
  if (Number.isFinite(direct) && direct > 0) return Math.floor(direct);
  const fields = planningMessageEventFields(msg);
  const fieldTotal = Number(fields.total_cycles || fields.total || 0);
  if (Number.isFinite(fieldTotal) && fieldTotal > 0) return Math.floor(fieldTotal);
  const text = String(msg.content || "");
  const match = text.match(/\bcycle\s*[=:]?\s*\d+\s*\/\s*(\d+)/i);
  if (match) {
    const value = Number(match[1]);
    if (Number.isFinite(value) && value > 0) return Math.floor(value);
  }
  return 0;
}

function planningLoopOrdinal(cycle) {
  const value = Math.max(1, Math.floor(Number(cycle || 1)));
  const mod100 = value % 100;
  if (mod100 >= 11 && mod100 <= 13) return `${value}th`;
  const mod10 = value % 10;
  if (mod10 === 1) return `${value}st`;
  if (mod10 === 2) return `${value}nd`;
  if (mod10 === 3) return `${value}rd`;
  return `${value}th`;
}

function annotatePlanningChatCycles(chatMessages, cycleStartIndex = 0) {
  let currentCycle = 0;
  let latestCycle = 0;
  let totalCycles = 0;
  const startIndex = Math.max(0, Number(cycleStartIndex || 0));
  const annotated = (chatMessages || []).map((msg, index) => {
    if (index < startIndex) return { msg, index, cycle: 0, totalCycles: 0 };
    const explicitCycle = planningMessageCycleIndex(msg);
    if (explicitCycle > 0) currentCycle = explicitCycle;
    const explicitTotal = planningMessageTotalCycles(msg);
    if (explicitTotal > 0) totalCycles = Math.max(totalCycles, explicitTotal);
    const cycle = explicitCycle || currentCycle || 0;
    if (cycle > 0) latestCycle = Math.max(latestCycle, cycle);
    return { msg, index, cycle, totalCycles: explicitTotal || totalCycles || 0 };
  });
  return { annotated, latestCycle, totalCycles, cycleStartIndex: startIndex };
}

function planningWorkflowCompleteAfter(chatMessages, cycleStartIndex = 0) {
  const startIndex = Math.max(0, Number(cycleStartIndex || 0));
  return (chatMessages || []).some((msg, index) => {
    if (index < startIndex) return false;
    const parsed = parsePlanningSystemEvent(msg && msg.content);
    if (!parsed) return false;
    const eventName = String(parsed.name || "").trim().toUpperCase();
    return eventName === "WORKFLOW_COMPLETE";
  });
}

function planningLoopSummaryAgentNames(messages) {
  const seen = new Set();
  (messages || []).forEach((msg) => {
    const agent = agentIdFromMessage(msg);
    if (agent && agent !== "objective") seen.add(liveAgentShort(agent));
  });
  return Array.from(seen).filter(Boolean).slice(0, 6).join(" -> ");
}

function shouldShowChatReportHint(msg) {
  if (!isChatSurfaceMessage(msg)) return false;
  const surfaces = messageSurfaces(msg);
  return surfaces.includes("report") || surfaces.includes("artifacts") || surfaces.includes("io");
}

function renderChatReportHint(msg) {
  if (!shouldShowChatReportHint(msg)) return "";
  const parts = [];
  const surfaces = messageSurfaces(msg);
  if (surfaces.includes("report")) parts.push("Report");
  if (surfaces.includes("artifacts")) parts.push("Artifacts");
  if (surfaces.includes("io")) parts.push("IO");
  const text = parts.length ? `상세 내용은 ${parts.join(", ")} 영역에 정리됩니다.` : "상세 내용은 Report 영역에 정리됩니다.";
  return `<p class="planning-chat-route-hint">${escapeHtml(text)}</p>`;
}

function chatGroupKeyForMessage(msg) {
  if (!msg || typeof msg !== "object") return "orchestrator";
  const role = String(msg.role || "orchestrator").toLowerCase();
  if (role === "specimen_ai" || role === "printer_ai") return "specimen_ai";
  if (isPlanningSystemMessage(msg)) return "system";
  return role || "orchestrator";
}

function groupPlanningChatMessages(messages) {
  const groups = [];
  let current = null;
  for (const msg of messages || []) {
    const baseKey = chatGroupKeyForMessage(msg);
    if (!current || current.baseKey !== baseKey) {
      current = {
        key: makePlanningChatGroupKey(baseKey, msg, groups.length),
        baseKey,
        role: msg.role || baseKey,
        messages: [],
      };
      groups.push(current);
    }
    current.messages.push(msg);
    if (!current.latest || Number(msg.transcript_index || 0) >= Number(current.latest.transcript_index || 0)) {
      current.latest = msg;
      current.role = msg.role || current.role;
    }
  }
  return groups;
}

function planningStableTextHash(value) {
  const text = String(value || "");
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function planningMessageStableToken(msg, fallbackIndex = 0) {
  if (!msg || typeof msg !== "object") return `fallback:${fallbackIndex}`;
  if (msg?.message_id) return `message:${msg.message_id}`;
  if (msg?.transcript_index !== undefined && msg?.transcript_index !== null) return `idx:${msg.transcript_index}`;
  if (msg?.id) return `id:${msg.id}`;
  if (msg?.event_id) return `event:${msg.event_id}`;
  if (msg?.trace_id) return `trace:${msg.trace_id}`;
  if (msg?.timestamp) return `ts:${msg.timestamp}`;
  const content = String(msg.content || msg.message || "").trim();
  if (content) return `content:${planningStableTextHash(`${msg.role || ""}:${msg.model || ""}:${content}`)}`;
  return `fallback:${fallbackIndex}`;
}

function makePlanningChatGroupKey(baseKey, msg, fallbackIndex) {
  const stablePart = planningMessageStableToken(msg, fallbackIndex);
  const safeBase = String(baseKey || "agent").replace(/[^a-zA-Z0-9_-]+/g, "_").slice(0, 32) || "agent";
  const safeStable = String(stablePart ?? fallbackIndex).replace(/[^a-zA-Z0-9_-]+/g, "_").slice(0, 48) || String(fallbackIndex);
  return `${safeBase}:${safeStable}`;
}

function buildPlanningChatItems(chatMessages) {
  const sourceMessages = Array.isArray(chatMessages) ? chatMessages : [];
  const latestOperatorIndex = sourceMessages.reduce((latest, msg, index) => (
    isOperatorPlanningMessage(msg) ? index : latest
  ), -1);
  const cycleStartIndex = latestOperatorIndex >= 0 ? latestOperatorIndex + 1 : 0;
  const items = [];
  let currentGroup = null;
  const loopGroups = new Map();
  const { annotated, latestCycle, totalCycles } = annotatePlanningChatCycles(sourceMessages, cycleStartIndex);
  const workflowComplete = planningWorkflowCompleteAfter(sourceMessages, cycleStartIndex);
  const flushGroup = () => {
    if (currentGroup) {
      items.push({ type: "group", group: currentGroup });
      currentGroup = null;
    }
  };

  const appendLoopSummary = (entry) => {
    flushGroup();
    const cycle = Math.max(1, Number(entry.cycle || 1));
    let group = loopGroups.get(cycle);
    if (!group) {
      group = {
        key: `loop:${cycle}:${planningMessageStableToken(entry.msg, entry.index)}`,
        baseKey: "loop_summary",
        role: "loop_summary",
        kind: "loop_summary",
        loopCycle: cycle,
        totalCycles: entry.totalCycles || totalCycles || 0,
        messages: [],
      };
      loopGroups.set(cycle, group);
      items.push({ type: "group", group });
    }
    group.messages.push(entry.msg);
    group.totalCycles = Math.max(Number(group.totalCycles || 0), Number(entry.totalCycles || totalCycles || 0));
    if (!group.latest || Number(entry.msg.transcript_index || 0) >= Number(group.latest.transcript_index || 0)) {
      group.latest = entry.msg;
    }
  };

  annotated.forEach((entry) => {
    const msg = entry.msg;
    if (isOperatorPlanningMessage(msg)) {
      flushGroup();
      items.push({ type: "operator", msg, index: entry.index });
      return;
    }

    // A Live run starts after the latest operator message. While running, the
    // latest loop stays detailed. Once WORKFLOW_COMPLETE is emitted, the final
    // loop is also archived as an expandable Loop Complete bubble.
    const completedLoop = entry.cycle > 0 && latestCycle > 0 && (
      entry.cycle < latestCycle || (workflowComplete && entry.cycle <= latestCycle)
    );
    if (entry.index >= cycleStartIndex && completedLoop) {
      appendLoopSummary(entry);
      return;
    }

    const baseKey = chatGroupKeyForMessage(msg);
    if (!currentGroup || currentGroup.baseKey !== baseKey) {
      flushGroup();
      currentGroup = {
        key: makePlanningChatGroupKey(baseKey, msg, entry.index),
        baseKey,
        role: msg.role || baseKey,
        messages: [],
      };
    }
    currentGroup.messages.push(msg);
    if (!currentGroup.latest || Number(msg.transcript_index || 0) >= Number(currentGroup.latest.transcript_index || 0)) {
      currentGroup.latest = msg;
      currentGroup.role = msg.role || currentGroup.role;
    }
  });
  flushGroup();
  return items;
}
function planningChatItemRevealKey(item) {
  if (!item || typeof item !== "object") return "item:unknown";
  if (item.type === "operator") return `operator:${planningMessageKey(item.msg, item.index)}`;
  const group = item.group || {};
  return `group:${group.key || group.baseKey || group.role || "agent"}`;
}

function flattenPlanningChatItems(items) {
  const out = [];
  (items || []).forEach((item) => {
    if (!item || typeof item !== "object") return;
    if (item.type === "operator") {
      if (item.msg) out.push(item.msg);
      return;
    }
    const messages = item.group && Array.isArray(item.group.messages) ? item.group.messages : [];
    out.push(...messages);
  });
  return out;
}

function syncPlanningDisplayedMessageKeys(messages = planningDisplayedMessages) {
  planningDisplayedMessageKeys.clear();
  (messages || []).forEach((msg, index) => planningDisplayedMessageKeys.add(planningMessageKey(msg, index)));
}


function chatMessageSummaryLine(msg) {
  if (!msg) return "대기 중";
  if (msg.pendingReasoning) return "응답을 준비하고 있습니다.";
  const parsedSystem = parsePlanningSystemEvent(msg.content);
  if (parsedSystem) {
    const fields = parsedSystem.fields || {};
    const name = String(parsedSystem.name || "event").toLowerCase().replace(/_/g, " ");
    const route = fields.from && fields.to ? `${fields.from} -> ${fields.to}` : (fields.to || fields.from || "");
    return [name, route, fields.status].filter(Boolean).join(" / ");
  }
  const text = normalizeDisplayText(msg.content || "").replace(/\s+/g, " ").trim();
  if (text) return compactText(text, 52);
  const surfaces = messageSurfaces(msg);
  if (surfaces.includes("report") || surfaces.includes("artifacts")) return "상세 결과가 Report 영역에 정리되었습니다.";
  return "새 메시지가 있습니다.";
}

function chatGroupProgress(group) {
  if (!group || !Array.isArray(group.messages) || !group.messages.length) return null;
  if (group.kind === "loop_summary" || group.baseKey === "loop_summary") {
    return { percent: 100, status: `${planningLoopOrdinal(group.loopCycle)} loop archived` };
  }
  const latest = group.latest || group.messages[group.messages.length - 1] || {};
  const totals = group.messages.map((msg) => Number(msg.total_cycles || 0)).filter((value) => Number.isFinite(value) && value > 0);
  const cycles = group.messages.map((msg) => Number(msg.cycle_index || 0)).filter((value) => Number.isFinite(value) && value > 0);
  const total = totals.length ? Math.max(...totals) : 0;
  const cycle = cycles.length ? Math.max(...cycles) : 0;
  const hasPending = group.messages.some((msg) => msg.pendingReasoning);
  const hasStages = total > 0 || group.messages.length > 1 || hasPending;
  if (!hasStages) return null;
  let percent = 0;
  if (total > 0) {
    percent = Math.max(0, Math.min(100, (Math.max(cycle, hasPending ? 1 : 0) / total) * 100));
  } else {
    percent = hasPending ? 55 : 100;
  }
  const status = hasPending
    ? "응답을 준비하고 있습니다."
    : compactText(normalizeDisplayText(latest.message_type || latest.event_type || latest.content || "상태 갱신").replace(/\s+/g, " "), 44);
  return { percent, status };
}

function renderChatGroupProgress(group) {
  const progress = chatGroupProgress(group);
  if (!progress) return "";
  const percent = Number.isFinite(progress.percent) ? Math.max(0, Math.min(100, progress.percent)) : 0;
  return `
    <div class="planning-agent-chat-progress" aria-label="${escapeHtml(progress.status)}">
      <div class="planning-agent-chat-progress-head">
        <small>${escapeHtml(progress.status)}</small>
      </div>
      <div class="planning-agent-chat-progress-track" aria-hidden="true"><span style="width:${percent.toFixed(1)}%"></span></div>
    </div>
  `;
}

function chatGroupAgentDescriptor(group, role) {
  const cleanRole = String(role || group?.role || group?.key || "orchestrator").toLowerCase();
  const roleToAgent = {
    operator: "objective",
    orchestrator: "orchestrator",
    design_ai: "design",
    specimen_ai: "specimen",
    printer_ai: "specimen",
    vision_ai: "vision",
    manipulation_ai: "manipulation",
    equipment_ai: "equipment",
    analysis_ai: "analysis",
    knowledge_ai: "knowledge",
    bo_ai: "bo",
    loop_summary: "guardian",
    guardian: "guardian",
    guardian_ai: "guardian",
  };
  const agentId = roleToAgent[cleanRole] || group?.baseKey || group?.key || "orchestrator";
  return LIVE_AGENTS.find((agent) => agent.id === agentId || agent.stage === agentId) || {
    id: agentId,
    label: roleLabel(cleanRole),
    short: String(roleLabel(cleanRole) || "AGT").slice(0, 3).toUpperCase(),
    icon: "A",
    iconPath: "",
  };
}

function renderChatGroupIcon(agent) {
  const fallback = escapeHtml(agent.short || agent.icon || "AGT");
  if (!agent.iconPath) return `<span>${fallback}</span>`;
  return `<img src="${escapeHtml(agent.iconPath)}" alt="" aria-hidden="true" loading="lazy" onerror="this.replaceWith(document.createTextNode('${fallback}'))">`;
}

function renderPlanningChatMessageDetail(msg, messageIndex) {
  const role = msg.role || "orchestrator";
  const model = msg.model ? ` / ${msg.model}` : "";
  const content = msg.content
    ? escapeHtml(normalizeDisplayText(msg.content)).replaceAll("\n", "<br />")
    : msg.pendingReasoning
      ? "응답을 준비하고 있습니다."
      : "";
  return `
    <div class="planning-agent-chat-message ${escapeHtml(role)}" data-message-index="${escapeHtml(String(messageIndex))}">
      <small>${escapeHtml(formatTime(msg.timestamp))} / ${escapeHtml(roleLabel(role))}${escapeHtml(model)}</small>
      ${renderReasoningBlock(msg)}
      ${content ? `<div class="message-content">${content}</div>` : ""}
      ${renderChatReportHint(msg)}
      ${renderFemContourCard(msg)}
      ${renderBoResultCard(msg, `chat-${messageIndex}`)}
    </div>
  `;
}

function isLoopArchiveAgentMessage(msg) {
  if (!msg || typeof msg !== "object") return false;
  const role = String(msg.role || "").toLowerCase();
  if (!role || role === "system" || role === "operator" || role === "user" || role === "human") return false;
  return Boolean(String(msg.content || "").trim() || msg.pendingReasoning);
}

function isLoopArchiveVisibleMessage(msg) {
  if (!msg || typeof msg !== "object") return false;
  if (isLoopArchiveAgentMessage(msg)) return true;
  if (isPlanningSystemMessage(msg)) return true;
  return Boolean(String(msg.content || "").trim()) && String(msg.visibility || "").toLowerCase() !== "internal";
}

function renderPlanningLoopArchiveMessageDetail(msg, messageIndex) {
  const parsed = parsePlanningSystemEvent(msg && msg.content);
  if (parsed && !isLoopArchiveAgentMessage(msg)) {
    const fields = parsed.fields || {};
    const route = fields.from && fields.to ? `${fields.from} -> ${fields.to}` : (fields.to || fields.from || "");
    const bits = [parsed.name || "SYSTEM_EVENT", route, fields.status || fields.decision || fields.reason || ""].filter(Boolean);
    return `
      <div class="planning-agent-chat-message system loop-archive-system" data-message-index="${escapeHtml(String(messageIndex))}">
        <small>${escapeHtml(formatTime(msg.timestamp))} / System</small>
        <div class="message-content">${escapeHtml(bits.join(" / "))}</div>
      </div>
    `;
  }
  return renderPlanningChatMessageDetail(msg, messageIndex);
}

function renderOperatorPlanningMessage(msg, messageIndex) {
  const content = msg.content
    ? escapeHtml(normalizeDisplayText(msg.content)).replaceAll("\n", "<br />")
    : "";
  return `
    <article class="planning-chat-item operator planning-chat-operator-direct" data-chat-item-type="operator" data-message-index="${escapeHtml(String(messageIndex))}">
      <div class="planning-chat-operator-cell">
        <small>${escapeHtml(formatTime(msg.timestamp))} / Operator</small>
        ${content ? `<div class="message-content">${content}</div>` : ""}
      </div>
    </article>
  `;
}

function renderPlanningChatGroup(group, groupIndex) {
  const latest = group.latest || group.messages[group.messages.length - 1] || {};
  const role = group.role || latest.role || group.key || "orchestrator";
  const baseKey = group.baseKey || group.key;
  const isSystem = baseKey === "system" || String(role || "").toLowerCase() === "system";
  const isLoopSummary = group.kind === "loop_summary" || baseKey === "loop_summary";
  const expanded = !isSystem && planningExpandedChatGroups.has(group.key);
  const loopLabel = isLoopSummary ? `${planningLoopOrdinal(group.loopCycle)} Loop Complete` : "";
  const loopAgents = isLoopSummary ? planningLoopSummaryAgentNames(group.messages) : "";
  const summary = isLoopSummary
    ? `${loopLabel} · ${group.messages.length} updates${loopAgents ? ` · ${loopAgents}` : ""}`
    : chatMessageSummaryLine(latest);
  const agent = isLoopSummary
    ? { label: loopLabel, short: "LOOP", icon: "L", iconPath: "" }
    : chatGroupAgentDescriptor(group, role);
  const time = formatTime(latest.timestamp);
  const detailMessages = isLoopSummary
    ? group.messages.filter(isLoopArchiveVisibleMessage)
    : group.messages;
  const messageHtml = detailMessages.length
    ? detailMessages.map((msg, index) => (
        isLoopSummary ? renderPlanningLoopArchiveMessageDetail(msg, index) : renderPlanningChatMessageDetail(msg, index)
      )).join("")
    : `<div class="planning-agent-chat-message loop-summary-note"><small>Loop archive</small><div class="message-content">시스템 이벤트는 Backend/Event 영역에 보관되었습니다.</div></div>`;
  return `
    <article class="planning-chat-item planning-agent-chat-group ${escapeHtml(role)} ${isLoopSummary ? "loop-summary" : ""} ${expanded ? "is-expanded" : "is-collapsed"}" data-chat-group-key="${escapeHtml(group.key)}" data-chat-group-index="${escapeHtml(String(groupIndex))}">
      <button class="planning-agent-chat-collapsed planning-agent-chat-open" type="button" data-chat-group-key="${escapeHtml(group.key)}" ${isSystem ? "disabled" : ""}>
        <span class="planning-agent-chat-icon">${renderChatGroupIcon(agent)}</span>
        <span class="planning-agent-chat-time">${escapeHtml(time)}</span>
        <span class="planning-agent-chat-title">${escapeHtml(agent.label || roleLabel(role))}</span>
        <span class="planning-agent-chat-summary">${escapeHtml(summary)}</span>
        <span class="planning-agent-chat-state">${isSystem ? "event" : (expanded ? "hide" : "show")}</span>
        ${renderChatGroupProgress(group)}
      </button>
      <div class="planning-agent-chat-body">
        <div class="planning-agent-chat-expanded-tools">
          <button class="planning-agent-chat-hide" type="button" data-chat-group-key="${escapeHtml(group.key)}">hide</button>
        </div>
        ${messageHtml}
      </div>
    </article>
  `;
}


function syncPlanningChatBubbleHeights() {
  if (!planningChatLog) return;
  // Chat bubbles must stay in normal document flow. Do not pin measured heights:
  // long operator messages, expanded agent groups, images, and tables can resize after render.
  planningChatLog.querySelectorAll(".planning-chat-item").forEach((bubble) => {
    bubble.style.removeProperty("--planning-bubble-height");
    bubble.style.removeProperty("height");
    bubble.style.removeProperty("min-height");
  });
}

function schedulePlanningChatLayoutSync({ scrollToBottom = false } = {}) {
  if (!planningChatLog) return;
  liveRequestFrame(() => {
    syncPlanningChatBubbleHeights();
    liveRequestFrame(() => {
      syncPlanningChatBubbleHeights();
      if (scrollToBottom) scrollPlanningChatToBottom();
    });
  });
}

function bindPlanningChatHeightTriggers() {
  if (!planningChatLog) return;
  planningChatLog.querySelectorAll("details.reasoning-block").forEach((details) => {
    details.addEventListener("toggle", () => schedulePlanningChatLayoutSync({ scrollToBottom: false }));
  });
  planningChatLog.querySelectorAll("img, svg, canvas, table").forEach((node) => {
    node.addEventListener?.("load", () => schedulePlanningChatLayoutSync({ scrollToBottom: false }), { once: true });
  });
}

function bindPlanningChatGroupToggles() {
  if (!planningChatLog) return;
  planningChatLog.querySelectorAll(".planning-agent-chat-open[data-chat-group-key]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      const key = button.dataset.chatGroupKey || "";
      if (!key || button.disabled) return;
      // Accordion behavior: opening one chat/loop bubble closes the others.
      planningExpandedChatGroups.clear();
      planningExpandedChatGroups.add(key);
      renderPlanningMessages(planningMessagesCache, { scrollToBottom: false });
      persistLiveUiState();
      persistLivePlanningCache(liveLastSession);
    });
  });
  planningChatLog.querySelectorAll(".planning-agent-chat-hide[data-chat-group-key]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const key = button.dataset.chatGroupKey || "";
      if (!key) return;
      planningExpandedChatGroups.delete(key);
      renderPlanningMessages(planningMessagesCache, { scrollToBottom: false });
      persistLiveUiState();
      persistLivePlanningCache(liveLastSession);
    });
  });
}


function planningMessageToEvent(msg) {
  if (!msg || typeof msg !== "object") return null;
  const surfaces = messageSurfaces(msg);
  const messageClass = String(msg.message_class || "").toLowerCase();
  const parsed = parsePlanningSystemEvent(msg.content);
  const shouldRoute = parsed || surfaces.includes("timeline") || surfaces.includes("backend") || ["system_event", "handoff_event", "tool_event", "error_event"].includes(messageClass);
  if (!shouldRoute) return null;
  const fields = (msg.event_fields && typeof msg.event_fields === "object") ? msg.event_fields : (parsed ? parsed.fields : {});
  const name = String(msg.event_type || (parsed ? `planning.${parsed.name.toLowerCase().replace(/[^a-zA-Z0-9_.:-]+/g, "_")}` : messageClass || "planning.message"));
  const from = fields.from || fields.source || "";
  const to = fields.to || fields.target || "";
  const status = fields.status || msg.status || "";
  const agentText = to || from || msg.agent_id || msg.role || "system";
  const summary = parsed
    ? [parsed.name, from && `from=${from}`, to && `to=${to}`, status && `status=${status}`].filter(Boolean).join(" ")
    : compactText(msg.content || name, 180);
  return {
    event_id: `planning-message-${msg.message_id || msg.transcript_index || summary}`,
    event_type: name,
    type: name,
    level: msg.severity || (messageClass === "error_event" ? "ERROR" : "INFO"),
    severity: msg.severity || "info",
    ts: msg.timestamp,
    timestamp: msg.timestamp,
    node_id: agentText,
    agent_id: msg.agent_id || agentText,
    message: summary,
    payload: {
      source: "planning_transcript",
      message_class: msg.message_class || "",
      surface: messageSurfaces(msg),
      event_fields: fields,
      planning_message: msg,
    },
  };
}

function planningDerivedEvents() {
  const seen = new Set();
  const events = [];
  for (const msg of planningMessagesCache || []) {
    const event = planningMessageToEvent(msg);
    if (!event) continue;
    const key = eventStableKey(event);
    if (seen.has(key)) continue;
    seen.add(key);
    events.push(event);
  }
  return events;
}

function liveEventSources() {
  const base = currentRunEventSources();
  const combined = [...base, ...planningDerivedEvents()];
  const seen = new Set();
  return combined.filter((event) => {
    const key = eventStableKey(event);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function renderSingleArtifactCard(artifacts, spec, label = "", options = {}) {
  const previewUrl = safeUrl(artifacts.preview_url);
  const stlUrl = safeUrl(artifacts.stl_url);
  const specUrl = safeUrl(artifacts.experiment_spec_url);
  if (!previewUrl && !stlUrl && !specUrl) return "";
  const showStlViewer = options.showStlViewer !== false;
  const showStlLink = options.showStlLink !== false;

  const specimenId = escapeHtml(spec.specimen_id || "specimen");
  const geometry = escapeHtml(spec.geometry_type || "geometry");
  const size = escapeHtml(JSON.stringify(spec.specimen_size_mm || []));

  return `
    <div class="artifact-card">
      ${previewUrl ? `<img class="artifact-preview" src="${escapeHtml(previewUrl)}" alt="STL preview for ${specimenId}" />` : ""}
      <div class="artifact-meta">
        ${label ? `<em>${escapeHtml(label)}</em>` : ""}
        <strong>${specimenId}</strong>
        <span>${geometry} / size=${size}</span>
        <div class="artifact-links">
          ${stlUrl && showStlLink ? `<a href="${escapeHtml(stlUrl)}" target="_blank" rel="noreferrer">Open STL</a>` : ""}
          ${specUrl ? `<a href="${escapeHtml(specUrl)}" target="_blank" rel="noreferrer">experiment_spec.json</a>` : ""}
        </div>
      </div>
      ${stlUrl && showStlViewer ? `
        <div class="stl-viewer-wrap">
          <canvas class="stl-viewer" data-stl-url="${escapeHtml(stlUrl)}" width="720" height="420"></canvas>
          <div class="stl-viewer-hint">drag to rotate / wheel to zoom</div>
        </div>
      ` : ""}
    </div>
  `;
}

function renderArtifactCard(msg) {
  if (msg.render_artifacts === false || msg.role === "printer_ai") return "";
  if (msg.role === "analysis_ai" && msg.fem_artifacts) return "";
  const artifactOptions = { showStlViewer: msg.role !== "design_ai", showStlLink: msg.role !== "design_ai" };
  const pair = msg.artifact_pair || {};
  if (pair.previous || pair.next) {
    const previous = pair.previous || {};
    const next = pair.next || {};
    const previousCard = renderSingleArtifactCard(
      previous.artifacts || {},
      previous.experiment_spec || {},
      previous.label || "Previous shape",
      artifactOptions
    );
    const nextCard = renderSingleArtifactCard(
      next.artifacts || {},
      next.experiment_spec || msg.experiment_spec || {},
      next.label || "Next shape",
      artifactOptions
    );
    return `<div class="artifact-pair">${previousCard}${nextCard}</div>`;
  }
  return renderSingleArtifactCard(msg.artifacts || {}, msg.experiment_spec || {}, "", artifactOptions);
}

function renderFemContourCard(msg) {
  const fem = msg.fem_artifacts || {};
  const contourUrl = safeUrl(fem.contour_url);
  const reportUrl = safeUrl(fem.report_url);
  if (!contourUrl && !reportUrl) return "";
  return `
    <div class="fem-contour-card">
      <div class="fem-contour-head">
        <strong>FEM / CAE Contour</strong>
        ${reportUrl ? `<a href="${escapeHtml(reportUrl)}" target="_blank" rel="noreferrer">CAE report</a>` : ""}
      </div>
      ${contourUrl ? `<img class="fem-contour-preview" src="${escapeHtml(contourUrl)}" alt="FEM contour visualization" />` : ""}
    </div>
  `;
}

function numberText(value, digits = 4) {
  const num = Number(value);
  if (!Number.isFinite(num)) return "n/a";
  return String(Number(num.toFixed(digits)));
}

function finiteRange(values, fallback = [0, 1]) {
  const nums = values.map(Number).filter(Number.isFinite);
  if (!nums.length) return fallback;
  let min = Math.min(...nums);
  let max = Math.max(...nums);
  if (Math.abs(max - min) < 1e-9) {
    min -= 0.5;
    max += 0.5;
  }
  return [min, max];
}

function scaleLinear(value, domain, range) {
  const v = Number(value);
  if (!Number.isFinite(v)) return range[0];
  const t = (v - domain[0]) / Math.max(1e-9, domain[1] - domain[0]);
  return range[0] + Math.max(0, Math.min(1, t)) * (range[1] - range[0]);
}

function polyline(points) {
  return points.map(([x, y]) => `${numberText(x, 2)},${numberText(y, 2)}`).join(" ");
}

function compactBoParamValue(value) {
  const num = Number(value);
  if (Number.isFinite(num)) return numberText(num, 4);
  if (value === null || value === undefined || value === "") return "n/a";
  return String(value);
}

function compactBoParams(params) {
  const p = params || {};
  const keys = ["geometry_type", "relative_density", "wall_thickness_mm", "cell_size_mm", "tpms_thickness", "orientation_deg", "anisotropy_ratio"];
  return keys
    .filter((key) => p[key] !== undefined && p[key] !== null)
    .map((key) => `${key}=${compactBoParamValue(p[key])}`)
    .join(", ");
}

function boStrategyFromBenchmark(benchmark) {
  const strategies = benchmark && benchmark.strategies ? benchmark.strategies : {};
  if (strategies.bo) return strategies.bo;
  const firstKey = Object.keys(strategies)[0];
  return firstKey ? strategies[firstKey] : null;
}

function renderBoTraceSvg(trace) {
  const candidates = Array.isArray(trace.candidates) ? trace.candidates : [];
  if (!candidates.length) {
    return `<div class="bo-plot-empty">BO candidate landscape가 없습니다.</div>`;
  }

  const width = 840;
  const height = 320;
  const pad = { left: 52, right: 24, top: 28, bottom: 48 };
  const plotW = width - pad.left - pad.right;
  const plotH = height - pad.top - pad.bottom;
  const xDomain = finiteRange(candidates.map((item) => item.x), [1, candidates.length || 1]);
  const meanValues = candidates.flatMap((item) => [
    Number(item.surrogate_mean) - Number(item.uncertainty || 0) * 0.12,
    Number(item.surrogate_mean),
    Number(item.surrogate_mean) + Number(item.uncertainty || 0) * 0.12,
  ]);
  const acqValues = candidates.map((item) => item.acquisition_value);
  const scoreValues = (trace.evaluated_points || []).map((item) => item.score);
  const meanDomain = finiteRange(meanValues, [0, 1]);
  const acqDomain = finiteRange(acqValues, [0, 1]);
  const scoreDomain = finiteRange(scoreValues.length ? scoreValues : meanValues, meanDomain);
  const xScale = (value) => pad.left + scaleLinear(value, xDomain, [0, plotW]);
  const yMean = (value) => pad.top + scaleLinear(value, meanDomain, [plotH, 0]);
  const yAcq = (value) => pad.top + scaleLinear(value, acqDomain, [plotH, 0]);
  const yScore = (value) => pad.top + scaleLinear(value, scoreDomain, [plotH, 0]);
  const meanLine = candidates.map((item) => [xScale(item.x), yMean(item.surrogate_mean)]);
  const acqLine = candidates.map((item) => [xScale(item.x), yAcq(item.acquisition_value)]);
  const upper = candidates.map((item) => [xScale(item.x), yMean(Number(item.surrogate_mean) + Number(item.uncertainty || 0) * 0.12)]);
  const lower = candidates
    .slice()
    .reverse()
    .map((item) => [xScale(item.x), yMean(Number(item.surrogate_mean) - Number(item.uncertainty || 0) * 0.12)]);
  const selected = trace.selected || {};
  const selectedX = Number(selected.x);
  const selectedY = yAcq(selected.acquisition_value);
  const observed = Array.isArray(trace.evaluated_points) ? trace.evaluated_points.filter((item) => Number.isFinite(Number(item.x))) : [];
  const candidateCount = Number(trace.candidate_count || candidates.length);
  const xTicks = [1, Math.max(1, Math.round(candidateCount / 2)), candidateCount].filter((v, i, arr) => arr.indexOf(v) === i);
  const yTicks = [0, 0.5, 1];

  return `
    <svg class="bo-trace-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="BO surrogate and acquisition trace step ${escapeHtml(trace.step)}">
      <rect x="0" y="0" width="${width}" height="${height}" rx="18" class="bo-svg-bg"></rect>
      <line x1="${pad.left}" y1="${pad.top + plotH}" x2="${pad.left + plotW}" y2="${pad.top + plotH}" class="bo-axis"></line>
      <line x1="${pad.left}" y1="${pad.top}" x2="${pad.left}" y2="${pad.top + plotH}" class="bo-axis"></line>
      ${xTicks.map((tick) => `
        <g>
          <line x1="${xScale(tick)}" y1="${pad.top}" x2="${xScale(tick)}" y2="${pad.top + plotH}" class="bo-grid"></line>
          <text x="${xScale(tick)}" y="${height - 18}" text-anchor="middle" class="bo-axis-label">${tick}</text>
        </g>
      `).join("")}
      ${yTicks.map((tick) => `
        <g>
          <line x1="${pad.left}" y1="${pad.top + plotH * (1 - tick)}" x2="${pad.left + plotW}" y2="${pad.top + plotH * (1 - tick)}" class="bo-grid"></line>
          <text x="${pad.left - 12}" y="${pad.top + plotH * (1 - tick) + 4}" text-anchor="end" class="bo-axis-label">${tick}</text>
        </g>
      `).join("")}
      <polygon points="${polyline([...upper, ...lower])}" class="bo-uncertainty-band"></polygon>
      <polyline points="${polyline(meanLine)}" class="bo-mean-line"></polyline>
      <polyline points="${polyline(acqLine)}" class="bo-acq-line"></polyline>
      ${observed.map((point) => `
        <circle cx="${xScale(point.x)}" cy="${yScore(point.score)}" r="5.8" class="bo-observed-point">
          <title>${escapeHtml(point.candidate_id || point.source || "observed")} score=${escapeHtml(numberText(point.score, 5))} ${escapeHtml(compactBoParams(point.parameters))}</title>
        </circle>
      `).join("")}
      ${Number.isFinite(selectedX) ? `
        <line x1="${xScale(selectedX)}" y1="${pad.top}" x2="${xScale(selectedX)}" y2="${pad.top + plotH}" class="bo-selected-line"></line>
        <circle cx="${xScale(selectedX)}" cy="${selectedY}" r="8" class="bo-selected-point">
          <title>${escapeHtml(selected.candidate_id || "selected")} acquisition=${escapeHtml(numberText(selected.acquisition_value, 5))} ${escapeHtml(compactBoParams(selected.parameters))}</title>
        </circle>
      ` : ""}
      <text x="${pad.left}" y="20" class="bo-svg-title">step ${escapeHtml(trace.step)} · ${escapeHtml(trace.acquisition || "acquisition")} · candidate pool index</text>
      <g class="bo-legend">
        <line x1="${width - 330}" y1="20" x2="${width - 300}" y2="20" class="bo-mean-line"></line>
        <text x="${width - 294}" y="24">surrogate mean</text>
        <line x1="${width - 190}" y1="20" x2="${width - 160}" y2="20" class="bo-acq-line"></line>
        <text x="${width - 154}" y="24">acquisition</text>
      </g>
    </svg>
  `;
}

function boCardKey(msg, index = "") {
  const boResult = msg.bo_result && typeof msg.bo_result === "object" ? msg.bo_result : {};
  const benchmark = boResult.benchmark || {};
  const strategyPayload = boStrategyFromBenchmark(benchmark);
  const trace = strategyPayload && Array.isArray(strategyPayload.surrogate_trace) ? strategyPayload.surrogate_trace : [];
  const recommendation = boResult.recommendation && typeof boResult.recommendation === "object" ? boResult.recommendation : {};
  const parts = [
    index,
    msg.created_at || msg.timestamp || msg.run_id || "",
    boResult.strategy || "",
    boResult.acquisition || "",
    recommendation.candidate_id || "",
    trace.length,
  ];
  return parts.map((item) => String(item || "").replace(/[^a-zA-Z0-9_.:-]+/g, "-")).join("::");
}

function renderBoExpandedBody(trace, visualization) {
  const renderer = window.BOVisualization;
  const latestTrace = trace.length ? trace[trace.length - 1] : {};
  const latestVisualization = renderer && renderer.isValid(visualization)
    ? visualization
    : (renderer && renderer.isValid(latestTrace.visualization) ? latestTrace.visualization : null);
  const selectedRows = trace
    .map((item) => {
      const selected = item.selected || {};
      return `
        <div class="bo-selected-row">
          <strong>#${escapeHtml(item.step || "")}</strong>
          <span>${escapeHtml(selected.candidate_id || "candidate")}</span>
          <code>${escapeHtml(compactBoParams(selected.parameters))}</code>
          <em>score=${escapeHtml(numberText(selected.score, 5))} · acq=${escapeHtml(numberText(selected.acquisition_value, 5))}</em>
        </div>
      `;
    })
    .join("");

  return `
    <div class="bo-plot-stack">
      ${latestVisualization
        ? `<article class="bo-trace-card bo-trace-card-shared">${BOVisualization.renderPlot(latestVisualization, { mode: "parameter_slice", parameter: latestVisualization.view?.selected_parameter || "" })}</article>`
        : `<div class="bo-plot-empty">BO posterior/acquisition 산출물이 아직 없습니다.</div>`}
    </div>
    ${selectedRows ? `<div class="bo-selected-points">${selectedRows}</div>` : ""}
  `;
}

function renderBoCollapsedBody(trace, latestSelected) {
  return `
    <div class="bo-plot-collapsed">
      <strong>그래프 접힘</strong>
      <span>BO surrogate/acquisition 그래프 ${escapeHtml(trace.length || 0)}개는 메모리 절약을 위해 아직 렌더링하지 않았습니다.</span>
      ${latestSelected && latestSelected.candidate_id ? `<code>latest=${escapeHtml(latestSelected.candidate_id)} · ${escapeHtml(compactBoParams(latestSelected.parameters))}</code>` : ""}
    </div>
  `;
}

function renderBoResultCard(msg, index = "") {
  const boResult = msg.bo_result && typeof msg.bo_result === "object" ? msg.bo_result : {};
  if (msg.role !== "bo_ai" || !Object.keys(boResult).length) return "";
  const benchmark = boResult.benchmark || {};
  const strategyPayload = boStrategyFromBenchmark(benchmark);
  const trace = strategyPayload && Array.isArray(strategyPayload.surrogate_trace) ? strategyPayload.surrogate_trace : [];
  const recommendation = boResult.recommendation && typeof boResult.recommendation === "object" ? boResult.recommendation : {};
  const latestTrace = trace.length ? trace[trace.length - 1] : {};
  const latestSelected = latestTrace.selected || {};
  const cardKey = boCardKey(msg, index);
  const expanded = liveExpandedBoCards.has(cardKey);
  const initialDesignPhase = boOptimizationPhase(boResult) === "initial_design";
  const initial = boInitialDesignStatus(boResult);
  const summaryRows = initialDesignPhase
    ? [
      ["phase", "Latin Hypercube Initial Design"],
      ["sampler", initial.sampler],
      ["progress", `${initial.completed}/${initial.target}`],
      ["next_lhs_point", `${initial.nextIndex}/${initial.target}`],
      ["candidate", recommendation.candidate_id],
      ["selection_method", recommendation.selection_method || "latin_hypercube"],
      ["acquisition", "acquisition inactive"],
      ["parameters", recommendation.parameters || {}],
    ]
    : [
      ["strategy", `${boResult.strategy || "-"} / benchmark=${boResult.benchmark_strategy || "-"}`],
      ["acquisition", boResult.acquisition],
      ["budget", boResult.budget],
      ["trace_steps", trace.length],
      ["latest_candidate", latestSelected.candidate_id],
      ["recommended_candidate", recommendation.candidate_id],
      ["combined_score", recommendation.combined_score],
      ["recommended_score", recommendation.objective_score],
      ["reasoning", boResult.reasoning && boResult.reasoning.operator_summary ? boResult.reasoning.operator_summary : "-"],
    ];

  return `
    <div class="bo-live-card" data-bo-card-key="${escapeHtml(cardKey)}">
      <div class="runtime-card-section bo-card-summary">
        <div class="bo-card-head">
          <h4>${initialDesignPhase ? "Latin Hypercube Initial Design" : "BO Surrogate / Acquisition Trace"}</h4>
          <button class="btn small bo-graph-toggle" type="button" data-bo-card-key="${escapeHtml(cardKey)}" aria-expanded="${expanded ? "true" : "false"}">${expanded ? "그래프 접기" : "그래프 보기"}</button>
        </div>
        ${runtimeRows(summaryRows)}
        ${Array.isArray(boResult.candidate_ranking) && boResult.candidate_ranking.length ? `<div class="bo-candidate-mini-list">${boResult.candidate_ranking.slice(0, 5).map((item) => `<div><strong>${escapeHtml(item.candidate_id || "candidate")}</strong><span>score=${escapeHtml(numberText(item.combined_score, 5))}</span><code>${escapeHtml(compactBoParams(item.parameters || {}))}</code></div>`).join("")}</div>` : ""}
      </div>
      <div class="bo-graph-body">
        ${initialDesignPhase
          ? `<div class="bo-plot-collapsed"><strong>LHS ${escapeHtml(`${initial.completed}/${initial.target}`)}</strong><span>GP posterior and Expected Improvement activate after the initial design is complete.</span><code>${escapeHtml(compactBoParams(recommendation.parameters || {}))}</code></div>`
          : (expanded ? renderBoExpandedBody(trace, boResult.visualization || latestTrace.visualization) : renderBoCollapsedBody(trace, latestSelected))}
      </div>
    </div>
  `;
}

function renderRuntimeValue(value, fallback = "n/a") {
  if (value === null || value === undefined || value === "") return fallback;
  if (Array.isArray(value) || typeof value === "object") return JSON.stringify(value);
  return String(value);
}

function renderCompactMemoryGb(value, fallback = "n/a") {
  if (value === null || value === undefined || value === "") return fallback;
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  const absValue = Math.abs(numeric);
  if (absValue >= 10) return String(Math.round(numeric));
  return String(Math.round(numeric * 10) / 10);
}

function runtimeRows(rows) {
  return rows
    .filter((row) => row && row.length >= 2)
    .map(([label, value]) => `
      <div class="runtime-row">
        <span>${escapeHtml(label)}</span>
        <strong>${escapeHtml(renderRuntimeValue(value))}</strong>
      </div>
    `)
    .join("");
}

function renderStepTrace(trace) {
  if (!Array.isArray(trace) || !trace.length) return "";
  return `
    <ol class="runtime-steps">
      ${trace.map((step) => {
        const detail = step && step.detail ? ` · ${step.detail}` : "";
        return `<li><span>${escapeHtml(renderRuntimeValue(step.step, "STEP"))}</span><strong>${escapeHtml(renderRuntimeValue(step.status, "unknown"))}${escapeHtml(detail)}</strong></li>`;
      }).join("")}
    </ol>
  `;
}

function renderEquipmentRuntimeCard(msg) {
  if (msg.role !== "equipment_ai" && msg.model !== "equipment_agent") return "";
  const event = msg.equipment_runtime_event || {};
  const macro = msg.macro_command || {};
  const visual = msg.visual_assertion || {};
  const physical = msg.physical_cross_check || {};
  const data = msg.data_acquisition || {};
  const recovery = msg.recovery || {};
  const hasCard = Object.keys(event).length || Object.keys(macro).length || Object.keys(visual).length || Object.keys(physical).length || Object.keys(data).length || Object.keys(recovery).length || msg.command_id || msg.data_file_ref;
  if (!hasCard) return "";
  return `
    <div class="printer-runtime-card equipment-runtime-card">
      <div class="runtime-card-section">
        <h4>Lab Equipment Runtime Event</h4>
        ${runtimeRows([
          ["message_type", msg.message_type],
          ["tool", msg.tool || event.tool],
          ["command_id", msg.command_id || event.sequence_id],
          ["program_id", msg.program_id || event.program_id],
          ["windows_host", msg.windows_host || event.bridge_host || event.host],
          ["step", event.step],
          ["status", event.status],
        ])}
      </div>
      ${Object.keys(macro).length ? `
        <div class="runtime-card-section">
          <h4>Macro Command</h4>
          ${runtimeRows([
            ["command_id", macro.command_id || msg.command_id],
            ["program_id", macro.program_id || msg.program_id || event.program_id],
            ["target_ui", macro.target_ui],
            ["step", macro.step],
            ["status", macro.status],
            ["detail", macro.detail],
          ])}
        </div>` : ""}
      ${Object.keys(visual).length ? `
        <div class="runtime-card-section">
          <h4>Visual Assertion</h4>
          ${runtimeRows([
            ["checkpoint", visual.checkpoint],
            ["status", visual.status],
            ["ok", visual.ok],
            ["target_ui", visual.target_ui],
            ["confidence", visual.confidence],
            ["screenshot_artifact", visual.screenshot_artifact],
            ["detail", visual.detail],
          ])}
        </div>` : ""}
      ${Object.keys(physical).length ? `
        <div class="runtime-card-section">
          <h4>Physical Cross-Check</h4>
          ${runtimeRows([
            ["status", physical.status],
            ["ok", physical.ok],
            ["check_id", physical.check_id],
            ["target_ui", physical.target_ui],
            ["detail", physical.detail],
          ])}
        </div>` : ""}
      ${Object.keys(data).length || msg.data_file_ref ? `
        <div class="runtime-card-section">
          <h4>Data Acquisition</h4>
          ${runtimeRows([
            ["status", data.status],
            ["artifact_or_path", data.artifact_or_path || msg.data_file_ref],
            ["windows_path", data.windows_path],
            ["linux_path", data.linux_path],
            ["sha256", data.sha256],
            ["row_count_probe", data.row_count_probe],
            ["save_method", data.save_method],
            ["artifact_pull_status", data.artifact_pull_status],
            ["parse_probe", data.parse_probe],
            ["detail", data.detail],
          ])}
        </div>` : ""}
      ${Object.keys(recovery).length ? `
        <div class="runtime-card-section runtime-card-wide">
          <h4>Recovery</h4>
          ${runtimeRows([
            ["status", recovery.status],
            ["failure_step", recovery.failure_step],
            ["failure_code", recovery.failure_code],
            ["failure_detail", recovery.failure_detail],
            ["recommended_action", recovery.recommended_action],
          ])}
        </div>` : ""}
    </div>
  `;
}

function renderSpecimenRuntimeCard(msg) {
  if (msg.role !== "printer_ai" && msg.role !== "specimen_ai") return "";
  const specimen = msg.specimen || {};
  const fabricationReport = specimen.fabrication_report || {};
  const fabricationIntent = fabricationReport.fabrication_intent || {};
  const digitalThread = fabricationReport.digital_thread || {};
  const processPlan = fabricationReport.process_plan || {};
  const printerRuntime = fabricationReport.printer_runtime || {};
  const fabricationOutcome = fabricationReport.fabrication_outcome || {};
  const qualityGates = Array.isArray(fabricationReport.quality_gates) ? fabricationReport.quality_gates : [];
  const toolResult = specimen.tool_result || {};
  const settings = specimen.slicer_settings || toolResult.slicer_settings || {};
  const prusalink = specimen.prusalink || toolResult.prusalink || {};
  const printer = specimen.printer || toolResult.printer || {};
  const selectedPrinter = specimen.selected_printer || toolResult.selected_printer || printerRuntime.selected_printer || {};
  const deviceScreen = specimen.device_screen || toolResult.device_screen || printerRuntime.device_screen || {};
  const deviceConnection = deviceScreen.connection || {};
  const deviceActions = deviceScreen.actions || {};
  const preprintGate = specimen.preprint_gate || toolResult.preprint_gate || toolResult.start_gate || printerRuntime.preprint_gate || {};
  const readinessLevels = Array.isArray(specimen.readiness_levels)
    ? specimen.readiness_levels
    : Array.isArray(toolResult.readiness_levels)
      ? toolResult.readiness_levels
      : Array.isArray(printerRuntime.readiness_levels)
        ? printerRuntime.readiness_levels
        : [];
  const operatorActions = Array.isArray(specimen.operator_actions)
    ? specimen.operator_actions
    : Array.isArray(toolResult.operator_actions)
      ? toolResult.operator_actions
      : Array.isArray(printerRuntime.operator_actions)
        ? printerRuntime.operator_actions
        : [];
  const autoejection = specimen.autoejection || toolResult.autoejection || toolResult.autoejection_gate || printerRuntime.autoejection || {};
  const autoejectionHandoff = specimen.autoejection_handoff || toolResult.autoejection_handoff || toolResult.handoff || autoejection.handoff || printerRuntime.autoejection_handoff || {};
  const slicerResult = specimen.slicer_result || toolResult.slicer_result || {};
  const gcodeValidation = specimen.gcode_validation || toolResult.gcode_validation || {};
  const printResult = specimen.print_result || toolResult.print_result || {};
  const setReady = printResult.set_ready || specimen.set_ready || toolResult.set_ready || {};
  const uploadResult = printResult.upload || {};
  const transferWait = printResult.transfer_wait || {};
  const startResult = printResult.start || {};
  const ejectionResult = specimen.ejection_result || toolResult.ejection_result || {};
  const trace = specimen.step_trace || toolResult.step_trace || [];
  if (!Object.keys(settings).length && !trace.length && !Object.keys(fabricationReport).length) return "";

  const command = Array.isArray(settings.resolved_command) ? settings.resolved_command.join(" ") : "";
  const gateSummary = qualityGates.length
    ? `${qualityGates.filter((gate) => gate.status === "pass").length}/${qualityGates.length} pass · blocked=${qualityGates.filter((gate) => gate.status === "blocked").length} · fail=${qualityGates.filter((gate) => gate.status === "fail").length}`
    : "-";
  const gateItems = qualityGates.slice(0, 9).map((gate) => `<li>${escapeHtml(gate.gate || "gate")} · <strong>${escapeHtml(gate.status || "unknown")}</strong>${gate.repair ? ` · ${escapeHtml(renderRuntimeValue(gate.repair))}` : ""}</li>`).join("");
  const readinessItems = readinessLevels.slice(0, 8).map((item) => `<li>${escapeHtml(item.level_id || item.id || item.name || "readiness")} · <strong>${escapeHtml(item.status || "unknown")}</strong>${item.reason || item.summary || item.detail ? ` · ${escapeHtml(compactText(item.reason || item.summary || item.detail, 90))}` : ""}</li>`).join("");
  const operatorActionItems = operatorActions.slice(0, 6).map((item) => `<li>${escapeHtml(item.action_id || item.id || "operator_action")} · <strong>${escapeHtml(item.status || "required")}</strong>${item.label || item.summary ? ` · ${escapeHtml(compactText(item.label || item.summary, 90))}` : ""}</li>`).join("");
  return `
    <div class="printer-runtime-card">
      <div class="runtime-card-section runtime-card-wide">
        <h4>Fabrication Digital Thread</h4>
        ${runtimeRows([
          ["fabrication_schema", fabricationReport.schema],
          ["intent", `${fabricationIntent.mode || "-"} / ${fabricationIntent.printer_path || specimen.printer_path || "-"}`],
          ["physical_intent", fabricationIntent.physical_intent],
          ["specimen_id", digitalThread.specimen_id || specimen.specimen_id],
          ["design_hash", digitalThread.design_hash],
          ["geometry_hash", digitalThread.geometry_hash || specimen.geometry_hash],
          ["stl_path", digitalThread.stl_path || specimen.stl_path],
          ["gcode_path", digitalThread.gcode_path || specimen.sliced_path],
          ["handoff_package", digitalThread.handoff_package_path || specimen.handoff_package_path],
          ["outcome", fabricationOutcome.status],
          ["location", fabricationOutcome.location],
          ["quality_gates", gateSummary],
        ])}
        ${gateItems ? `<ul class="report-list compact">${gateItems}</ul>` : ""}
      </div>
      <div class="runtime-card-section">
        <h4>Slicer / Artifact Settings</h4>
        ${runtimeRows([
          ["printer_profile", settings.printer_profile],
          ["material", settings.material],
          ["slicer_profile_hint", settings.slicer_profile_hint],
          ["layer_height_mm", settings.layer_height_mm],
          ["first_layer_height_mm", settings.first_layer_height_mm],
          ["nozzle_diameter_mm", settings.nozzle_diameter_mm],
          ["bed_temperature_c", settings.bed_temperature_c],
          ["first_layer_bed_temperature_c", settings.first_layer_bed_temperature_c],
          ["slow_first_layer_enabled", settings.slow_first_layer_enabled],
          ["first_layer_speed_mm_s", settings.first_layer_speed_mm_s],
          ["wall_thickness_mm", settings.wall_thickness_mm],
          ["cell_size_mm", settings.cell_size_mm],
          ["relative_density", settings.relative_density],
          ["skirt_enabled", settings.skirt_enabled],
          ["bottom_cap_enabled", settings.bottom_cap_enabled],
          ["top_cap_enabled", settings.top_cap_enabled],
          ["top_bottom_cap", settings.top_bottom_cap],
          ["skin_thickness_mm", settings.skin_thickness_mm],
          ["expected_mass_g", settings.expected_mass_g || specimen.expected_mass_g],
          ["input_model_path", settings.input_model_path],
          ["output_gcode_path", settings.output_gcode_path],
          ["simulated", settings.simulated],
        ])}
        ${command ? `<pre class="runtime-command">${escapeHtml(command)}</pre>` : ""}
      </div>
      <div class="runtime-card-section">
        <h4>Printer Bridge / SPC Readiness</h4>
        ${runtimeRows([
          ["provider", printer.provider || toolResult.provider || selectedPrinter.provider || digitalThread.printer_provider],
          ["selected_printer", selectedPrinter.label || selectedPrinter.profile_id || selectedPrinter.model],
          ["device_mqtt", deviceConnection.mqtt],
          ["device_transfer", deviceConnection.transfer],
          ["device_video", deviceConnection.video],
          ["can_upload", deviceActions.can_upload],
          ["can_start_print", deviceActions.can_start_print],
          ["preprint_state", preprintGate.state],
          ["technical_ready_for_start", preprintGate.technical_ready_for_start],
          ["approval_ready_for_start", preprintGate.approval_ready_for_start],
          ["ready_for_live_print", preprintGate.ready_for_live_print],
          ["preprint_blockers", preprintGate.blockers],
          ["autoejection_status", autoejection.status],
          ["autoejection_blockers", autoejection.blockers],
          ["autoejection_handoff", autoejectionHandoff.schema || autoejectionHandoff.status],
          ["recommended_consumer_agent", autoejectionHandoff.recommended_consumer_agent || autoejectionHandoff.next_owner],
          ["next_tool", autoejectionHandoff.next_tool],
          ["requires_guardian_approval", autoejectionHandoff.requires_guardian_approval],
          ["requires_operator_confirmation", autoejectionHandoff.requires_operator_confirmation],
          ["motion_started", autoejectionHandoff.motion_started],
          ["prepare_status", specimen.printer_prepare_status],
          ["printer_mode", specimen.printer_mode],
          ["printer_path", specimen.printer_path],
          ["printer_state", printer.state],
          ["transport", prusalink.transport],
          ["storage", prusalink.storage],
          ["storage_status", summarizeStorage(printer.storage, prusalink.storage)],
          ["set_ready", setReady.status || setReady.failure_code || (setReady.ok ? "ok" : "")],
          ["set_ready_job_id", setReady.job && setReady.job.job_id],
          ["set_ready_job_progress", setReady.job && setReady.job.progress],
          ["upload_endpoint", prusalink.upload_endpoint],
          ["upload_status", uploadResult.status || uploadResult.failure_code],
          ["upload_http_status", uploadResult.status_code],
          ["upload_elapsed_sec", uploadResult.elapsed_sec],
          ["upload_timeout_sec", uploadResult.timeout_sec],
          ["upload_bytes", uploadResult.bytes],
          ["transfer_wait_status", transferWait.status || transferWait.failure_code || (transferWait.ok ? "ok" : "")],
          ["transfer_wait_attempts", transferWait.attempts],
          ["transfer_last", transferWait.last_transfer],
          ["start_status", startResult.status || startResult.failure_code || (startResult.ok ? "ok" : "")],
          ["start_http_status", startResult.status_code],
          ["start_attempts", startResult.attempts],
          ["start_retry_history", startResult.retry_history],
          ["slicer_result", slicerResult.failure_code || (slicerResult.ok ? "ok" : "")],
          ["gcode_validation", gcodeValidation.failure_code || (gcodeValidation.ok ? "ok" : "")],
          ["print_result", printResult.status],
          ["ejection_result", ejectionResult.status],
          ["ejection_head_x_mm", ejectionResult.resolved && ejectionResult.resolved.head_x_mm],
          ["ejection_head_x_source", ejectionResult.resolved && ejectionResult.resolved.head_x_source],
          ["ejection_object_center_x_mm", ejectionResult.object_bounds && ejectionResult.object_bounds.center_x_mm],
        ])}
        ${readinessItems ? `<h5>SPC Readiness Levels</h5><ul class="report-list compact">${readinessItems}</ul>` : ""}
        ${operatorActionItems ? `<h5>Operator Actions</h5><ul class="report-list compact">${operatorActionItems}</ul>` : ""}
      </div>
      <div class="runtime-card-section runtime-card-wide">
        <h4>Step Trace</h4>
        ${renderStepTrace(trace)}
      </div>
    </div>
  `;
}

function summarizeStorage(storageResult, selectedStorage = "usb") {
  const selected = String(selectedStorage || "usb");
  if (!storageResult || typeof storageResult !== "object") return selected;
  if (storageResult.ok === false) return `${selected} (${storageResult.failure_code || "status_failed"})`;
  const payload = storageResult.payload && typeof storageResult.payload === "object" ? storageResult.payload : storageResult;
  const entries = Array.isArray(payload.storage_list) ? payload.storage_list : [];
  const item = entries.find((entry) => {
    if (!entry || typeof entry !== "object") return false;
    return String(entry.name || entry.path || "").replaceAll("/", "") === selected;
  });
  if (!item) return selected;
  return `${selected} available=${renderRuntimeValue(item.available)} read_only=${renderRuntimeValue(item.read_only)}`;
}

function renderReasoningBlock(msg) {
  if (msg.pendingReasoning) {
    return `
      <div class="reasoning-block reasoning-pending" aria-live="polite">
        <span class="reasoning-spinner" aria-hidden="true"></span>
        <span>reasoning</span>
      </div>
    `;
  }

  const reasoning = normalizeDisplayText(msg.reasoning).trim();
  if (!reasoning) return "";
  return `
    <details class="reasoning-block">
      <summary>
        <span class="reasoning-dot" aria-hidden="true"></span>
        <span>reasoning 보기 / 닫기</span>
      </summary>
      <pre>${escapeHtml(reasoning)}</pre>
    </details>
  `;
}

function scrollPlanningChatToBottom() {
  if (!planningChatLog) return;
  planningChatLog.scrollTop = planningChatLog.scrollHeight;
  liveRequestFrame(() => {
    if (!planningChatLog) return;
    planningChatLog.scrollTop = planningChatLog.scrollHeight;
  });
}

function isPlanningChatNearBottom(threshold = 160) {
  if (!planningChatLog) return true;
  const distance = planningChatLog.scrollHeight - planningChatLog.scrollTop - planningChatLog.clientHeight;
  return distance <= threshold;
}

function planningMessageKey(msg, fallbackIndex = 0) {
  if (!msg || typeof msg !== "object") return `fallback:${fallbackIndex}`;
  if (msg.message_id) return `id:${msg.message_id}`;
  if (msg.transcript_index !== undefined && msg.transcript_index !== null) return `idx:${msg.transcript_index}`;
  const role = String(msg.role || "");
  const timestamp = String(msg.timestamp || "");
  const model = String(msg.model || msg.agent || "");
  const content = String(msg.content || "").slice(0, 128);
  if (timestamp || model || content) return `fallback:${role}:${timestamp}:${model}:${content}`;
  return `fallback:${fallbackIndex}:${role}`;
}

function limitPlanningMessageCache(messages, limit = PLANNING_RENDER_CACHE_LIMIT) {
  if (!Array.isArray(messages) || messages.length <= limit) return Array.isArray(messages) ? messages : [];
  return messages.slice(messages.length - limit);
}

function mergePlanningMessages(...messageLists) {
  const merged = new Map();
  for (const list of messageLists) {
    if (!Array.isArray(list)) continue;
    list.forEach((msg, index) => {
      if (!msg || typeof msg !== "object") return;
      merged.set(planningMessageKey(msg, index), msg);
    });
  }
  const sorted = [...merged.values()].sort((a, b) => {
    const ai = Number(a.transcript_index);
    const bi = Number(b.transcript_index);
    if (Number.isFinite(ai) && Number.isFinite(bi)) return ai - bi;
    return String(a.timestamp || "").localeCompare(String(b.timestamp || ""));
  });
  return limitPlanningMessageCache(sorted);
}

async function loadOlderPlanningMessages() {
  if (planningHistoryLoading || !planningHistoryHasMore || !planningChatLog) return;
  const firstIndexed = planningMessagesCache.find((msg) => Number.isFinite(Number(msg.transcript_index)));
  const before = firstIndexed ? Number(firstIndexed.transcript_index) : Number.NaN;
  if (!Number.isFinite(before) || before <= 0) return;
  planningHistoryLoading = true;
  const previousHeight = planningChatLog.scrollHeight;
  const previousTop = planningChatLog.scrollTop;
  try {
    const sessionId = encodeURIComponent(ensurePlanningSessionId());
    const res = await fetch(`/api/planning/messages?session_id=${sessionId}&before=${before}&limit=80`);
    if (!res.ok) throw new Error(`history HTTP ${res.status}`);
    const payload = await res.json();
    const older = Array.isArray(payload.messages) ? payload.messages : [];
    planningHistoryHasMore = Boolean(payload.has_more_messages);
    planningHistoryTotal = Number(payload.message_total || planningHistoryTotal || 0);
    renderPlanningMessages(mergePlanningMessages(older, planningMessagesCache), { scrollToBottom: false });
    const heightDelta = planningChatLog.scrollHeight - previousHeight;
    planningChatLog.scrollTop = previousTop + heightDelta;
  } catch (err) {
    renderPlanningMessages([
      ...planningMessagesCache,
      { role: "system", content: `이전 대화 로딩 실패: ${err.message || err}` },
    ]);
  } finally {
    planningHistoryLoading = false;
  }
}

function resetPlanningMessageDisplayState() {
  planningMessagesCache = [];
  planningDisplayedMessages = [];
  planningDisplayedMessageKeys.clear();
  planningDisplayedChatItemKeys.clear();
  planningMessageRevealQueue = [];
  planningDisplayInitialized = false;
  if (planningMessageRevealTimer) {
    window.clearTimeout(planningMessageRevealTimer);
    planningMessageRevealTimer = null;
  }
}

function renderPlanningMessageDom(messages, options = {}) {
  if (!planningChatLog) return;
  const shouldScrollToBottom = options.scrollToBottom === true;
  const chatMessages = (Array.isArray(messages) ? messages : []).filter(isChatSurfaceMessage);
  if (!chatMessages.length) {
    planningChatLog.innerHTML = `
      <article class="planning-chat-item planning-agent-chat-group orchestrator is-collapsed">
        <button class="planning-agent-chat-collapsed" type="button" disabled>
          <span class="planning-agent-chat-icon"><img src="/static/live_gui_icons/orchestrator.svg" alt="" aria-hidden="true" loading="lazy"></span>
          <span class="planning-agent-chat-time">-</span>
          <span class="planning-agent-chat-title">Orchestrator</span>
          <span class="planning-agent-chat-summary">실험 조건을 입력하면 필요한 값 확인부터 실행까지 진행합니다.</span>
          <span class="planning-agent-chat-state">ready</span>
        </button>
      </article>
    `;
    schedulePlanningChatLayoutSync({ scrollToBottom: shouldScrollToBottom });
    return;
  }

  const chatItems = buildPlanningChatItems(chatMessages).map((item, index) => {
    if (item.type === "operator") return renderOperatorPlanningMessage(item.msg, item.index);
    return renderPlanningChatGroup(item.group, index);
  }).join("");

  planningChatLog.innerHTML = chatItems;
  bindPlanningChatGroupToggles();
  bindPlanningChatHeightTriggers();
  schedulePlanningChatLayoutSync({ scrollToBottom: shouldScrollToBottom });
}

function schedulePlanningMessageReveal() {
  if (planningMessageRevealTimer || !planningMessageRevealQueue.length) return;
  const first = planningMessageRevealQueue[0];
  const firstMessage = first && Array.isArray(first.messages) ? first.messages[0] : null;
  const delay = isOperatorPlanningMessage(firstMessage) && !planningDisplayedMessages.length ? 0 : PLANNING_MESSAGE_REVEAL_DELAY_MS;
  planningMessageRevealTimer = window.setTimeout(() => {
    planningMessageRevealTimer = null;
    const next = planningMessageRevealQueue.shift();
    if (next && Array.isArray(next.messages)) {
      planningDisplayedChatItemKeys.add(next.key);
      planningDisplayedMessages = limitPlanningMessageCache([...planningDisplayedMessages, ...next.messages]);
      syncPlanningDisplayedMessageKeys();
      renderPlanningMessageDom(planningDisplayedMessages, { scrollToBottom: true });
    }
    schedulePlanningMessageReveal();
  }, delay);
}

function flushPlanningRevealEntries(entries) {
  if (!Array.isArray(entries) || !entries.length) return;
  const appended = [];
  entries.forEach((entry) => {
    if (!entry || !Array.isArray(entry.messages)) return;
    if (entry.key) planningDisplayedChatItemKeys.add(entry.key);
    appended.push(...entry.messages);
  });
  if (appended.length) {
    planningDisplayedMessages = limitPlanningMessageCache([...planningDisplayedMessages, ...appended]);
    syncPlanningDisplayedMessageKeys();
  }
}

function compactPlanningRevealBacklog(unseenItems) {
  let nextItems = Array.isArray(unseenItems) ? unseenItems : [];
  const queued = Array.isArray(planningMessageRevealQueue) ? planningMessageRevealQueue : [];
  const totalBacklog = queued.length + nextItems.length;
  if (totalBacklog <= PLANNING_MESSAGE_REVEAL_MAX_QUEUE) return nextItems;

  const keepCount = Math.max(1, PLANNING_MESSAGE_REVEAL_TAIL_COUNT);
  const merged = [
    ...queued,
    ...nextItems.map((item) => ({
      key: planningChatItemRevealKey(item),
      messages: flattenPlanningChatItems([item]),
    })),
  ];
  const immediate = merged.slice(0, Math.max(0, merged.length - keepCount));
  const tail = merged.slice(Math.max(0, merged.length - keepCount));
  planningMessageRevealQueue = tail;
  flushPlanningRevealEntries(immediate);
  return [];
}

function updatePlanningDisplayedMessages(messages, options = {}) {
  const canonical = limitPlanningMessageCache(Array.isArray(messages) ? messages : []);
  const canonicalItems = buildPlanningChatItems(canonical);
  const canonicalItemKeys = new Set(canonicalItems.map(planningChatItemRevealKey));
  const initialTranscriptHydration = planningDisplayInitialized
    && canonicalItemKeys.size > 0
    && planningDisplayedChatItemKeys.size === 0;
  const replacesVisibleTranscript = planningDisplayInitialized
    && canonicalItemKeys.size > 0
    && planningDisplayedChatItemKeys.size > 0
    && !Array.from(canonicalItemKeys).some((key) => planningDisplayedChatItemKeys.has(key));
  // Session restore/page refresh should hydrate the existing transcript immediately.
  // Only messages that arrive after the chat surface is initialized use the reveal queue.
  // Browser audits and session switches can replace the whole transcript; those must not
  // wait behind the live-message reveal queue.
  const immediate = Boolean(options.immediate || options.scrollToBottom === false || planningHistoryLoading || !planningDisplayInitialized || initialTranscriptHydration || replacesVisibleTranscript);
  if (immediate) {
    planningDisplayedMessages = canonical;
    syncPlanningDisplayedMessageKeys(canonical);
    planningDisplayedChatItemKeys.clear();
    canonicalItems.forEach((item) => planningDisplayedChatItemKeys.add(planningChatItemRevealKey(item)));
    planningMessageRevealQueue = [];
    if (planningMessageRevealTimer) {
      window.clearTimeout(planningMessageRevealTimer);
      planningMessageRevealTimer = null;
    }
    planningDisplayInitialized = true;
    return planningDisplayedMessages;
  }

  for (const key of Array.from(planningDisplayedChatItemKeys)) {
    if (!canonicalItemKeys.has(key)) planningDisplayedChatItemKeys.delete(key);
  }
  planningMessageRevealQueue = planningMessageRevealQueue.filter((entry) => canonicalItemKeys.has(entry.key));
  for (const key of Array.from(planningExpandedChatGroups)) {
    if (!canonicalItemKeys.has(key)) planningExpandedChatGroups.delete(key);
  }

  // Refresh already visible bubbles from the newest canonical transcript. This lets
  // an active agent append step details inside the same bubble without creating a backlog.
  let displayedItems = canonicalItems.filter((item) => planningDisplayedChatItemKeys.has(planningChatItemRevealKey(item)));
  const completedLoopItems = canonicalItems.filter((item) => item?.group?.kind === "loop_summary");
  if (completedLoopItems.length) {
    const mergedByKey = new Map(displayedItems.map((item) => [planningChatItemRevealKey(item), item]));
    completedLoopItems.forEach((item) => mergedByKey.set(planningChatItemRevealKey(item), item));
    displayedItems = canonicalItems.filter((item) => mergedByKey.has(planningChatItemRevealKey(item)));
    completedLoopItems.forEach((item) => planningDisplayedChatItemKeys.add(planningChatItemRevealKey(item)));
    planningMessageRevealQueue = planningMessageRevealQueue.filter((entry) => !mergedByKey.has(entry.key));
  }
  planningDisplayedMessages = limitPlanningMessageCache(flattenPlanningChatItems(displayedItems));
  syncPlanningDisplayedMessageKeys();

  const queuedKeys = new Set(planningMessageRevealQueue.map((entry) => entry.key));
  let unseenItems = canonicalItems.filter((item) => {
    const key = planningChatItemRevealKey(item);
    return !planningDisplayedChatItemKeys.has(key) && !queuedKeys.has(key);
  });
  unseenItems = compactPlanningRevealBacklog(unseenItems);
  unseenItems.forEach((item) => {
    const key = planningChatItemRevealKey(item);
    if (planningDisplayedChatItemKeys.has(key) || queuedKeys.has(key)) return;
    planningMessageRevealQueue.push({ key, messages: flattenPlanningChatItems([item]) });
    queuedKeys.add(key);
  });
  planningDisplayInitialized = true;
  schedulePlanningMessageReveal();
  return planningDisplayedMessages;
}

function renderPlanningMessages(messages, options = {}) {
  if (!planningChatLog) return;
  const wasNearBottom = isPlanningChatNearBottom();
  const previousTail = planningDisplayedMessages.length
    ? planningMessageKey(planningDisplayedMessages[planningDisplayedMessages.length - 1], planningDisplayedMessages.length - 1)
    : "";
  planningMessagesCache = limitPlanningMessageCache(Array.isArray(messages) ? messages : []);
  const chatMessages = planningMessagesCache.filter(isChatSurfaceMessage);
  updateLiveChatUnreadFromMessages(planningMessagesCache);
  const displayMessages = updatePlanningDisplayedMessages(chatMessages, options);
  const nextTail = displayMessages.length
    ? planningMessageKey(displayMessages[displayMessages.length - 1], displayMessages.length - 1)
    : "";
  const hasNewTail = Boolean(nextTail && nextTail !== previousTail);
  const shouldScrollToBottom = options.scrollToBottom === true
    || (options.scrollToBottom !== false && hasNewTail && wasNearBottom);
  renderPlanningMessageDom(displayMessages, { scrollToBottom: shouldScrollToBottom });
}

const planningChatAutoScrollObserver = new MutationObserver(() => {
  // Rendering/layout recalculation alone must not pull the operator back to the bottom.
  // Explicit scroll decisions are handled by renderPlanningMessages/schedulePlanningMessageReveal.
});

function parseAsciiStlVertices(text) {
  const vertices = [];
  const pattern = /vertex\s+([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s+([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s+([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)/g;
  let match = pattern.exec(text);
  while (match) {
    vertices.push(Number(match[1]), Number(match[2]), Number(match[3]));
    match = pattern.exec(text);
  }
  return vertices;
}

function parseBinaryStlVertices(buffer) {
  const view = new DataView(buffer);
  if (view.byteLength < 84) return [];
  const triangleCount = view.getUint32(80, true);
  if (view.byteLength < 84 + triangleCount * 50) return [];
  const vertices = [];
  let offset = 84;
  for (let i = 0; i < triangleCount; i += 1) {
    offset += 12;
    for (let vertex = 0; vertex < 3; vertex += 1) {
      vertices.push(
        view.getFloat32(offset, true),
        view.getFloat32(offset + 4, true),
        view.getFloat32(offset + 8, true),
      );
      offset += 12;
    }
    offset += 2;
  }
  return vertices;
}

function parseStlVertices(buffer) {
  if (buffer.byteLength >= 84) {
    const view = new DataView(buffer);
    const triangleCount = view.getUint32(80, true);
    if (84 + triangleCount * 50 === buffer.byteLength) {
      return parseBinaryStlVertices(buffer);
    }
  }
  const text = new TextDecoder("utf-8").decode(buffer);
  return parseAsciiStlVertices(text);
}

function normalizeMesh(vertices) {
  const min = [Infinity, Infinity, Infinity];
  const max = [-Infinity, -Infinity, -Infinity];
  for (let i = 0; i < vertices.length; i += 3) {
    min[0] = Math.min(min[0], vertices[i]);
    min[1] = Math.min(min[1], vertices[i + 1]);
    min[2] = Math.min(min[2], vertices[i + 2]);
    max[0] = Math.max(max[0], vertices[i]);
    max[1] = Math.max(max[1], vertices[i + 1]);
    max[2] = Math.max(max[2], vertices[i + 2]);
  }
  const center = [(min[0] + max[0]) / 2, (min[1] + max[1]) / 2, (min[2] + max[2]) / 2];
  const scale = Math.max(max[0] - min[0], max[1] - min[1], max[2] - min[2], 1);
  return vertices.map((value, idx) => (value - center[idx % 3]) / scale * 2.2);
}

function computeNormals(vertices) {
  const faceNormals = [];
  const smoothSums = new Map();
  const smoothFaces = new Set();

  function keyAt(index) {
    return `${vertices[index].toFixed(5)},${vertices[index + 1].toFixed(5)},${vertices[index + 2].toFixed(5)}`;
  }

  const normals = new Array(vertices.length).fill(0);
  for (let i = 0; i < vertices.length; i += 9) {
    const ax = vertices[i];
    const ay = vertices[i + 1];
    const az = vertices[i + 2];
    const bx = vertices[i + 3];
    const by = vertices[i + 4];
    const bz = vertices[i + 5];
    const cx = vertices[i + 6];
    const cy = vertices[i + 7];
    const cz = vertices[i + 8];
    const ux = bx - ax;
    const uy = by - ay;
    const uz = bz - az;
    const vx = cx - ax;
    const vy = cy - ay;
    const vz = cz - az;
    let nx = uy * vz - uz * vy;
    let ny = uz * vx - ux * vz;
    let nz = ux * vy - uy * vx;
    const length = Math.hypot(nx, ny, nz) || 1;
    nx /= length;
    ny /= length;
    nz /= length;
    faceNormals.push([nx, ny, nz]);
    const absNormal = [Math.abs(nx), Math.abs(ny), Math.abs(nz)];
    const axisCount = absNormal.filter((value) => value > 1e-4).length;
    const axisAligned = Math.max(...absNormal) > 0.999 && axisCount === 1;
    if (!axisAligned) {
      smoothFaces.add(i);
      for (let j = 0; j < 3; j += 1) {
        const offset = i + j * 3;
        const key = keyAt(offset);
        const sum = smoothSums.get(key) || [0, 0, 0];
        sum[0] += nx;
        sum[1] += ny;
        sum[2] += nz;
        smoothSums.set(key, sum);
      }
    }
  }

  for (let i = 0; i < vertices.length; i += 9) {
    const faceNormal = faceNormals[i / 9] || [0, 0, 1];
    for (let j = 0; j < 3; j += 1) {
      const offset = i + j * 3;
      let normal = faceNormal;
      if (smoothFaces.has(i)) {
        const sum = smoothSums.get(keyAt(offset));
        if (sum) {
          const length = Math.hypot(sum[0], sum[1], sum[2]) || 1;
          normal = [sum[0] / length, sum[1] / length, sum[2] / length];
        }
      }
      normals[offset] = normal[0];
      normals[offset + 1] = normal[1];
      normals[offset + 2] = normal[2];
    }
  }
  return normals;
}

function compileShader(gl, type, source) {
  const shader = gl.createShader(type);
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    throw new Error(gl.getShaderInfoLog(shader) || "shader compile failed");
  }
  return shader;
}

function createProgram(gl) {
  const vertexSource = `
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    uniform float uRotX;
    uniform float uRotY;
    uniform float uZoom;
    varying float vLight;

    vec3 rotateX(vec3 p, float a) {
      float s = sin(a);
      float c = cos(a);
      return vec3(p.x, p.y * c - p.z * s, p.y * s + p.z * c);
    }

    vec3 rotateY(vec3 p, float a) {
      float s = sin(a);
      float c = cos(a);
      return vec3(p.x * c + p.z * s, p.y, -p.x * s + p.z * c);
    }

    void main() {
      vec3 p = rotateY(rotateX(aPosition, uRotX), uRotY);
      vec3 n = normalize(rotateY(rotateX(aNormal, uRotX), uRotY));
      float light = max(dot(n, normalize(vec3(0.35, 0.55, 0.9))), 0.0);
      vLight = 0.34 + 0.66 * light;
      float depth = p.z + 4.2 / uZoom;
      gl_Position = vec4(p.x * 1.65 / depth, p.y * 1.65 / depth, (depth - 2.0) / 5.0, 1.0);
    }
  `;
  const fragmentSource = `
    precision mediump float;
    varying float vLight;
    void main() {
      vec3 base = vec3(0.08, 0.29, 0.86);
      vec3 edge = vec3(0.70, 0.84, 1.0);
      gl_FragColor = vec4(mix(edge, base, vLight), 1.0);
    }
  `;
  const program = gl.createProgram();
  gl.attachShader(program, compileShader(gl, gl.VERTEX_SHADER, vertexSource));
  gl.attachShader(program, compileShader(gl, gl.FRAGMENT_SHADER, fragmentSource));
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    throw new Error(gl.getProgramInfoLog(program) || "shader link failed");
  }
  return program;
}

function setViewerHint(canvas, text) {
  const hint = canvas.parentElement ? canvas.parentElement.querySelector(".stl-viewer-hint") : null;
  if (hint) hint.textContent = text;
}

function initWebglStlViewer(canvas, vertices) {
  const gl = canvas.getContext("webgl", { antialias: true }) || canvas.getContext("experimental-webgl");
  if (!gl) {
    setViewerHint(canvas, "WebGL unavailable");
    return;
  }
  const positions = new Float32Array(normalizeMesh(vertices));
  const normals = new Float32Array(computeNormals(Array.from(positions)));
  const program = createProgram(gl);
  const posBuffer = gl.createBuffer();
  const normalBuffer = gl.createBuffer();
  const aPosition = gl.getAttribLocation(program, "aPosition");
  const aNormal = gl.getAttribLocation(program, "aNormal");
  const uRotX = gl.getUniformLocation(program, "uRotX");
  const uRotY = gl.getUniformLocation(program, "uRotY");
  const uZoom = gl.getUniformLocation(program, "uZoom");
  let rotX = -0.55;
  let rotY = 0.72;
  let zoom = 1.0;
  let dragging = false;
  let lastX = 0;
  let lastY = 0;

  function resize() {
    const ratio = window.devicePixelRatio || 1;
    const width = Math.max(320, Math.floor(canvas.clientWidth * ratio));
    const height = Math.max(220, Math.floor(canvas.clientHeight * ratio));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    gl.viewport(0, 0, canvas.width, canvas.height);
  }

  function render() {
    resize();
    gl.clearColor(0.965, 0.98, 1.0, 1.0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST);
    gl.useProgram(program);
    gl.uniform1f(uRotX, rotX);
    gl.uniform1f(uRotY, rotY);
    gl.uniform1f(uZoom, zoom);
    gl.bindBuffer(gl.ARRAY_BUFFER, posBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, positions, gl.STATIC_DRAW);
    gl.enableVertexAttribArray(aPosition);
    gl.vertexAttribPointer(aPosition, 3, gl.FLOAT, false, 0, 0);
    gl.bindBuffer(gl.ARRAY_BUFFER, normalBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, normals, gl.STATIC_DRAW);
    gl.enableVertexAttribArray(aNormal);
    gl.vertexAttribPointer(aNormal, 3, gl.FLOAT, false, 0, 0);
    gl.drawArrays(gl.TRIANGLES, 0, positions.length / 3);
  }

  canvas.addEventListener("pointerdown", (event) => {
    dragging = true;
    lastX = event.clientX;
    lastY = event.clientY;
    canvas.setPointerCapture(event.pointerId);
  });
  canvas.addEventListener("pointermove", (event) => {
    if (!dragging) return;
    rotY += (event.clientX - lastX) * 0.012;
    rotX += (event.clientY - lastY) * 0.012;
    lastX = event.clientX;
    lastY = event.clientY;
    render();
  });
  canvas.addEventListener("pointerup", () => {
    dragging = false;
  });
  canvas.addEventListener("pointercancel", () => {
    dragging = false;
  });
  canvas.addEventListener("wheel", (event) => {
    event.preventDefault();
    zoom = Math.max(0.55, Math.min(2.4, zoom + (event.deltaY < 0 ? 0.08 : -0.08)));
    render();
  }, { passive: false });
  window.addEventListener("resize", render);
  setViewerHint(canvas, "drag to rotate / wheel to zoom");
  render();
}

async function loadStlViewer(canvas) {
  try {
    setViewerHint(canvas, "loading STL viewer...");
    const response = await fetch(canvas.dataset.stlUrl);
    const buffer = await response.arrayBuffer();
    const vertices = parseStlVertices(buffer);
    if (vertices.length < 9) {
      throw new Error("STL has no triangles");
    }
    initWebglStlViewer(canvas, vertices);
  } catch (err) {
    setViewerHint(canvas, `viewer failed: ${err}`);
  }
}

function initStlViewers() {
  document.querySelectorAll(".stl-viewer[data-stl-url]:not([data-stl-loaded])").forEach((canvas) => {
    canvas.dataset.stlLoaded = "1";
    loadStlViewer(canvas);
  });
}


function liveAgentById(agentId) {
  return LIVE_AGENTS.find((agent) => agent.id === agentId) || LIVE_AGENTS[1];
}

function liveAgentLabel(agentId) {
  return liveAgentById(agentId).label;
}

function evolutionTargetForAgent(agentId) {
  const clean = String(agentId || liveSelectedAgent || "orchestrator").toLowerCase();
  const promptTargets = new Set(["design", "specimen", "vision", "manipulation", "equipment", "analysis", "knowledge", "bo", "guardian"]);
  if (promptTargets.has(clean)) return { target_type: "prompt", target_id: clean };
  if (clean === "objective" || clean === "orchestrator") return { target_type: "graph", target_id: "atr_closed_loop" };
  return { target_type: "prompt", target_id: clean || "design" };
}

function evolutionObjectiveForAgent(agentId) {
  const state = liveLastSession.state || {};
  const event = selectedTimelineEvent();
  const payload = eventPayload(event);
  const trace = event ? ` trace_id=${event.trace_id || payload.trace_id || "-"}` : "";
  const agentLabel = liveAgentLabel(agentId);
  return `Improve ${agentLabel} behavior for the next ATR closed-loop run using selected Live GUI report, backend trace, and runtime events.${trace} Preserve hardware safety gates and require human approval before activation.`;
}

function evolutionLabUrl(agentId = liveSelectedAgent) {
  const state = liveLastSession.state || {};
  const target = evolutionTargetForAgent(agentId);
  const params = new URLSearchParams({
    target_type: target.target_type,
    target_id: target.target_id,
    agent_id: agentId || liveSelectedAgent,
    objective: evolutionObjectiveForAgent(agentId || liveSelectedAgent),
    source: "live_gui",
  });
  if (state.run_id) params.set("run_id", state.run_id);
  if (liveSelectedEventKey) params.set("event_key", liveSelectedEventKey);
  return `/evolution-lab?${params.toString()}`;
}

function openEvolutionLab(agentId = liveSelectedAgent) {
  const url = evolutionLabUrl(agentId);
  window.open(url, "_blank", "noopener");
  setChatStatus("EVOLUTION", "idle");
}

function agentIdFromStage(stage) {
  const clean = String(stage || "").toLowerCase();
  if (!clean || clean === "idle") return "orchestrator";
  const direct = LIVE_AGENTS.find((agent) => agent.stage === clean || agent.id === clean);
  return direct ? direct.id : clean === "complete" || clean === "error" ? "guardian" : "orchestrator";
}

function agentIdFromRole(role) {
  const clean = String(role || "").toLowerCase();
  const roleMap = {
    orchestrator: "orchestrator",
    design_ai: "design",
    specimen_ai: "specimen",
    printer_ai: "specimen",
    vision_ai: "vision",
    manipulation_ai: "manipulation",
    equipment_ai: "equipment",
    analysis_ai: "analysis",
    knowledge_ai: "knowledge",
    bo_ai: "bo",
    guardian: "guardian",
  };
  return roleMap[clean] || "orchestrator";
}

function agentIdFromFreeText(value) {
  const text = String(value || "").toLowerCase();
  const matchers = [
    ["specimen", /specimen|printer|prusa|3dp|making/],
    ["manipulation", /manipulation|lerobot|robot|rollout/],
    ["equipment", /equipment|utm|pyautogui|windows/],
    ["analysis", /analysis|cae|fem|utm|contour/],
    ["knowledge", /knowledge|memory|report/],
    ["guardian", /guardian|approval|safety|gate/],
    ["design", /design|tpms|gyroid|lattice/],
    ["vision", /vision|camera|capture/],
    ["bo", /\bbo\b|bayesian|acquisition/],
  ];
  const hit = matchers.find(([, pattern]) => pattern.test(text));
  return hit ? hit[0] : "orchestrator";
}

function agentIdFromMessage(msg) {
  if (!msg || typeof msg !== "object") return "orchestrator";
  if (msg.role && msg.role !== "system") return agentIdFromRole(msg.role);
  const content = String(msg.content || "");
  const handoff = content.match(/to=([A-Za-z0-9_]+)/i) || content.match(/agent=([A-Za-z0-9_]+)/i);
  return handoff ? agentIdFromFreeText(handoff[1]) : agentIdFromFreeText(content);
}

function agentIdFromEvent(event) {
  const payload = event && typeof event.payload === "object" ? event.payload : {};
  const candidates = [
    payload.agent_id,
    payload.agent,
    payload.selected_agent,
    payload.selected_agent_id,
    event.agent_id,
    event.agent,
    payload.module_id,
    event.module_id,
    payload.node_id,
    event.node_id,
    payload.stage,
    event.timestamp_stage,
    payload.device,
    payload.tool,
    payload.failure_code,
  ];
  for (const candidate of candidates) {
    const value = String(candidate || "");
    if (!value) continue;
    const direct = agentIdFromStage(value);
    if ((direct !== "orchestrator" || value.toLowerCase() === "orchestrator") && knownLiveAgent(direct)) return direct;
    const inferred = agentIdFromFreeText(value);
    if (inferred !== "orchestrator" && knownLiveAgent(inferred)) return inferred;
  }
  const haystack = `${event.event_type || event.type || ""} ${event.message || ""} ${event.status || ""} ${JSON.stringify(payload)}`;
  const inferred = agentIdFromFreeText(haystack);
  return knownLiveAgent(inferred) ? inferred : "orchestrator";
}

function selectedMessages() {
  return planningMessagesCache.filter((msg) => agentIdFromMessage(msg) === liveSelectedAgent);
}

function selectedEvents() {
  return liveEventSources().filter((event) => agentIdFromEvent(event) === liveSelectedAgent);
}

function formatTime(value) {
  const text = String(value || "");
  if (!text) return "-";
  const date = new Date(text);
  if (Number.isNaN(date.getTime())) return text;
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

function compactText(value, limit = 460) {
  const text = normalizeDisplayText(value).trim();
  return text.length > limit ? `${text.slice(0, limit - 1)}…` : text;
}

function compactRunId(value) {
  const text = String(value || "").trim();
  if (!text) return "-";
  if (text.length <= 18) return text;
  return `${text.slice(0, 4)}…${text.slice(-7)}`;
}

function liveHumanizeStatus(value, fallback = "-") {
  const text = normalizeDisplayText(value).trim();
  if (!text) return fallback;
  return text
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .replace(/\b([a-z])/g, (match) => match.toUpperCase());
}

function liveMissionTopbarLabel(state = {}) {
  const raw = state.mission_name || state.mission || state.active_goal || state.goal || queryGoal || "";
  const text = normalizeDisplayText(raw).replace(/\.$/, "").trim();
  return text || "Mission ready";
}

function liveRunTopbarLabel(runId, mode, running) {
  const modeLabel = liveHumanizeStatus(mode, "Live");
  if (!runId || runId === "-") return running ? `${modeLabel} running` : `${modeLabel} ready`;
  return `${modeLabel} ${running ? "running" : "idle"}`;
}

function liveAgentTopbarLabel(agentId) {
  const clean = String(agentId || "").toLowerCase();
  const labels = {
    orchestrator: "Orchestrator",
    design: "Design",
    specimen: "Specimen",
    vision: "Vision",
    manipulation: "Manipulation",
    equipment: "Equipment",
    analysis: "Analysis",
    knowledge: "Knowledge",
    bo: "BO",
    guardian: "Guardian",
  };
  return labels[clean] || liveAgentLabel(agentId);
}

function liveAgentShort(agentId) {
  const agent = LIVE_AGENTS.find((item) => item.id === agentId || item.stage === agentId);
  return agent ? agent.short : compactText(agentId || "-", 8);
}

function formatPlanningCycleLabel(state = {}, running = false) {
  return window.ATRRuntimeCycle.format(state, running, { prefix: "Cycle " });
}

function setCompactTextWithTitle(element, text, title) {
  if (!element) return;
  element.textContent = text;
  element.title = title || text;
}

function updateLiveMissionMarquee(retryCount = 0) {
  if (!planningStageLabel) return;
  const windowEl = planningStageLabel.closest(".planning-mission-marquee-window");
  const cell = planningStageLabel.closest(".mission-status-primary");
  if (!windowEl || !cell) return;
  const availableWidth = Math.max(0, Math.floor(windowEl.clientWidth || 0));
  const fullWidth = Math.ceil(planningStageLabel.scrollWidth || 0);
  if (availableWidth <= 0 && retryCount < 8) {
    window.setTimeout(() => updateLiveMissionMarquee(retryCount + 1), 80);
    return;
  }
  const overflow = fullWidth - availableWidth;
  const resetMarquee = () => {
    if (liveMissionMarqueeAnimation) {
      liveMissionMarqueeAnimation.cancel();
      liveMissionMarqueeAnimation = null;
    }
    liveMissionMarqueeSignature = null;
    planningStageLabel.classList.remove("is-marquee");
    planningStageLabel.classList.remove("is-css-marquee");
    cell.classList.remove("mission-marquee-active");
    planningStageLabel.style.removeProperty("--mission-marquee-distance");
    planningStageLabel.style.removeProperty("--mission-marquee-duration");
  };
  if (availableWidth <= 0 || overflow <= 8) {
    resetMarquee();
    return;
  }
  const distance = overflow + Math.min(48, Math.max(24, availableWidth * 0.18));
  const startPauseSeconds = 3;
  const endPauseSeconds = 3;
  const travelSeconds = Math.min(22, Math.max(6, distance / 42));
  const duration = startPauseSeconds + travelSeconds + endPauseSeconds;
  const signature = {
    text: planningStageLabel.textContent || "",
    availableWidth,
    fullWidth,
    distance: Math.round(distance),
    duration: Number(duration.toFixed(1)),
  };
  const motionReduced = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const previousSignature = liveMissionMarqueeSignature;
  const canReuseCurrentMarquee = previousSignature
    && previousSignature.text === signature.text
    && Math.abs(previousSignature.availableWidth - signature.availableWidth) <= 12
    && Math.abs(previousSignature.fullWidth - signature.fullWidth) <= 12
    && Math.abs(previousSignature.distance - signature.distance) <= 18
    && planningStageLabel.classList.contains("is-marquee")
    && (liveMissionMarqueeAnimation || planningStageLabel.classList.contains("is-css-marquee") || motionReduced);
  if (canReuseCurrentMarquee) return;
  resetMarquee();
  liveMissionMarqueeSignature = signature;
  planningStageLabel.style.setProperty("--mission-marquee-distance", `${Math.round(distance)}px`);
  planningStageLabel.style.setProperty("--mission-marquee-duration", `${duration.toFixed(1)}s`);
  planningStageLabel.classList.add("is-marquee");
  cell.classList.add("mission-marquee-active");
  if (motionReduced) return;
  if (typeof planningStageLabel.animate !== "function") {
    planningStageLabel.classList.add("is-css-marquee");
    return;
  }
  const travelEndOffset = (startPauseSeconds + travelSeconds) / duration;
  liveMissionMarqueeAnimation = planningStageLabel.animate(
    [
      { transform: "translateX(0)", offset: 0 },
      { transform: "translateX(0)", offset: startPauseSeconds / duration },
      { transform: `translateX(-${Math.round(distance)}px)`, offset: travelEndOffset },
      { transform: `translateX(-${Math.round(distance)}px)`, offset: 1 },
    ],
    {
      duration: duration * 1000,
      easing: "linear",
      iterations: Infinity,
    },
  );
}

function scheduleLiveMissionMarquee() {
  if (liveMissionMarqueeFrame) liveCancelFrame(liveMissionMarqueeFrame);
  liveMissionMarqueeFrame = liveRequestFrame(() => {
    liveMissionMarqueeFrame = null;
    updateLiveMissionMarquee(0);
  });
}

function liveTokenCount(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? Math.round(number) : 0;
}

function liveTokenUsageFromObject(value) {
  if (!value || typeof value !== "object") return { prompt: 0, completion: 0, total: 0 };
  const usage = value.token_usage && typeof value.token_usage === "object" ? value.token_usage : value.usage && typeof value.usage === "object" ? value.usage : value;
  const prompt = liveTokenCount(usage.prompt_tokens || usage.input_tokens || usage.prompt_eval_count);
  const completion = liveTokenCount(usage.completion_tokens || usage.output_tokens || usage.eval_count);
  const total = liveTokenCount(usage.total_tokens) || prompt + completion;
  return { prompt, completion, total };
}

function addLiveTokenUsage(acc, usage) {
  if (!usage || !usage.total) return acc;
  acc.prompt += usage.prompt || 0;
  acc.completion += usage.completion || 0;
  acc.total += usage.total || 0;
  acc.calls += 1;
  return acc;
}

function compactTokenCount(value) {
  const number = liveTokenCount(value);
  if (!number) return "-";
  if (number >= 1000000) return `${(number / 1000000).toFixed(number >= 10000000 ? 0 : 1)}M`;
  if (number >= 1000) return `${(number / 1000).toFixed(number >= 10000 ? 0 : 1)}k`;
  return String(number);
}

function collectLiveTokenUsage(session = liveLastSession) {
  const acc = { prompt: 0, completion: 0, total: 0, calls: 0 };
  const messages = Array.isArray(session && session.messages) ? session.messages : planningMessagesCache;
  messages.forEach((msg) => addLiveTokenUsage(acc, liveTokenUsageFromObject(msg)));
  return acc;
}

function updateLiveTokenChip(session = liveLastSession) {
  const usage = collectLiveTokenUsage(session);
  if (!usage.total) {
    setCompactTextWithTitle(liveTokenChip, "Tok -", "No token usage recorded for this Live GUI session yet.");
    return;
  }
  setCompactTextWithTitle(
    liveTokenChip,
    `Tok ${compactTokenCount(usage.total)}`,
    `LLM token usage: total=${usage.total}, prompt=${usage.prompt}, completion=${usage.completion}, calls=${usage.calls}`
  );
}

function messageCountsByAgent(messages) {
  const counts = Object.fromEntries(LIVE_AGENTS.map((agent) => [agent.id, 0]));
  for (const msg of messages || []) {
    const agentId = agentIdFromMessage(msg);
    counts[agentId] = (counts[agentId] || 0) + 1;
  }
  return counts;
}

function liveNotificationCountsByAgent(session = liveLastSession) {
  const counts = messageCountsByAgent((session && session.messages) || planningMessagesCache || []);
  const seen = new Set();
  const eventSources = currentRunEventSources();
  eventSources.forEach((event, index) => {
    if (!isAgentNotificationEvent(event)) return;
    const payload = eventPayload(event);
    const eventKey = String(event.event_id || event.id || payload.event_id || `${event.event_type || event.type || "event"}:${event.ts || event.timestamp || index}`);
    if (seen.has(eventKey)) return;
    seen.add(eventKey);
    const agentId = eventAgentId(event);
    counts[agentId] = (counts[agentId] || 0) + 1;
  });
  for (const approval of liveApprovals.pending || []) {
    const agentId = agentIdFromFreeText(`${approval.stage || ""} ${approval.title || ""} ${approval.reason || ""}`);
    counts[agentId] = (counts[agentId] || 0) + 1;
  }
  return counts;
}

function markLiveAgentRead(agentId = liveSelectedAgent, session = liveLastSession) {
  const safeAgent = knownLiveAgent(agentId) ? agentId : liveSelectedAgent;
  const counts = liveNotificationCountsByAgent(session);
  liveReadMarkers[safeAgent] = counts[safeAgent] || 0;
}

function nestedPrinterRuntimeObjects(event) {
  const payload = eventPayload(event);
  const result = payload.result && typeof payload.result === "object" ? payload.result : {};
  const monitor = payload.monitor_snapshot && typeof payload.monitor_snapshot === "object" ? payload.monitor_snapshot : {};
  const health = result.health && typeof result.health === "object" ? result.health : {};
  const monitorHealth = monitor.health && typeof monitor.health === "object" ? monitor.health : {};
  return [payload, result, monitor, health, monitorHealth].filter((item) => item && typeof item === "object");
}

function isTransientPrinterCommunicationEvent(event) {
  const values = [event, ...nestedPrinterRuntimeObjects(event)];
  const failureCodes = values
    .map((item) => String(item.failure_code || item.error_code || item.code || "").toUpperCase())
    .filter(Boolean);
  if (failureCodes.some((code) => code === "BAMBU_MQTT_REPORT_TIMEOUT" || code === "BAMBU_MQTT_REPORT_NOT_FRESH")) return true;
  const haystack = values
    .map((item) => `${item.status || ""} ${item.state || ""} ${item.message || ""} ${item.error || ""} ${item.detail || ""}`)
    .join(" ")
    .toLowerCase();
  return haystack.includes("preprint_communication_failed") || haystack.includes("communication_timeout");
}

function specimenPrinterRuntimeState() {
  const events = currentRunEventSources();
  const runningStates = new Set(["RUNNING", "PRINTING", "PREPARE", "PREPARING", "HEATING", "SLICING"]);
  const failedStates = new Set(["FAILED", "FAIL", "ERROR", "CANCELLED", "CANCELED", "ABORTED"]);
  const completeStates = new Set(["FINISH", "FINISHED", "IDLE", "READY", "COMPLETE", "COMPLETED"]);
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    const eventType = String(event.event_type || event.type || "");
    const payload = eventPayload(event);
    if (eventType === "planning_printer_completion_wait") {
      const wait = payload.printer_wait && typeof payload.printer_wait === "object" ? payload.printer_wait : {};
      const waitStatus = String(wait.status || event.status || "").toLowerCase();
      if (waitStatus === "started") return "running";
      if (waitStatus === "complete" || waitStatus === "completed") return "complete";
    }
    for (const source of nestedPrinterRuntimeObjects(event)) {
      const deviceScreen = source.device_screen && typeof source.device_screen === "object" ? source.device_screen : {};
      const progress = deviceScreen.progress_panel && typeof deviceScreen.progress_panel === "object" ? deviceScreen.progress_panel : {};
      const job = deviceScreen.job && typeof deviceScreen.job === "object" ? deviceScreen.job : {};
      const state = String(progress.state || job.state || source.state || source.status || event.status || "").toUpperCase();
      if (!state) continue;
      if (isTransientPrinterCommunicationEvent(event)) return "running";
      if (runningStates.has(state)) return "running";
      if (failedStates.has(state)) return "failed";
      if (completeStates.has(state)) return "complete";
    }
  }
  return "";
}

function eventStatusForAgent(agentId, state, running) {
  const events = currentRunEventSources();
  const agentEvents = events.filter((event) => agentIdFromEvent(event) === agentId);
  const activeAgent = agentIdFromStage(state.stage || "");
  const runtimeStatus = state.agent_status && typeof state.agent_status === "object"
    ? state.agent_status[`${agentId}_agent`]
    : null;
  if (
    !running
    && String(state.stage || "").toLowerCase() === "complete"
    && runtimeStatus
    && runtimeStatus.success === true
  ) return "done";
  const pendingInput = agentEvents.some(eventRequiresOperatorInput)
    || planningMessagesCache.some((msg) => agentIdFromMessage(msg) === agentId && Boolean(msg.pending_operator_input));
  if (pendingInput) return running && activeAgent === agentId ? "running" : "waiting";
  const printerRuntime = agentId === "specimen" ? specimenPrinterRuntimeState() : "";
  if (printerRuntime === "running") return "running";
  const hasError = agentEvents.some((event) => !isResolvedEmergencyLifecycleEvent(event) && !eventRequiresOperatorInput(event) && (
    !isTransientPrinterCommunicationEvent(event) && (
    String(event.level || event.severity || "").toLowerCase() === "error"
    || String(event.status || "").toLowerCase() === "failed"
    )
  ));
  if (hasError) return "error";
  const pendingApproval = (liveApprovals.pending || []).some((item) => agentIdFromFreeText(`${item.stage || ""} ${item.title || ""} ${item.reason || ""}`) === agentId);
  if (pendingApproval) return "waiting";
  if (running && activeAgent === agentId) return "running";
  const agentMessages = planningMessagesCache.filter((msg) => agentIdFromMessage(msg) === agentId);
  if (agentEvents.length || agentMessages.length) return "done";
  return "idle";
}

function liveAgentIconHtml(agent) {
  const fallback = escapeHtml(agent.short || agent.icon || "?");
  if (!agent.iconPath) return `<span class="binder-icon-fallback is-visible" aria-hidden="true" data-fallback="${fallback}"></span>`;
  return `
    <img src="${escapeHtml(agent.iconPath)}" alt="" aria-hidden="true" loading="lazy" onerror="this.classList.add('is-broken'); this.nextElementSibling?.classList.add('is-visible');">
    <span class="binder-icon-fallback" aria-hidden="true" data-fallback="${fallback}"></span>
  `;
}

function renderAgentBinder(session) {
  if (!liveAgentBinderList) return;
  if (liveSelectedAgent === "objective") liveSelectedAgent = "orchestrator";
  const snapshot = liveLastSnapshot || {};
  const state = session.state || snapshot.state || {};
  const running = liveRunningFlag(session, snapshot, state);
  const counts = liveNotificationCountsByAgent(session);
  if (liveChatTarget) {
    const current = validLiveChatTarget(liveChatTarget.value) ? liveChatTarget.value : "selected_agent";
    const specificOptions = LIVE_AGENTS
      .filter((agent) => agent.id !== "objective")
      .map((agent) => `<option value="${agent.id}">${escapeHtml(agent.label)}</option>`)
      .join("");
    liveChatTarget.innerHTML = `
      <option value="current_agent">Current Agent</option>
      <option value="selected_agent">Selected Agent</option>
      <optgroup label="Specific Agent">${specificOptions}</optgroup>
    `;
    liveChatTarget.value = validLiveChatTarget(current) ? current : "selected_agent";
  }
  const attention = liveAttentionCounts();
  const attentionTone = attention.errors ? "error" : attention.total ? "warning" : "idle";
  const agentTabs = [];
  LIVE_AGENTS.filter((agent) => agent.id !== "objective").forEach((agent) => {
    const status = eventStatusForAgent(agent.id, state, running);
    const count = counts[agent.id] || 0;
    const unread = Math.max(0, count - (liveReadMarkers[agent.id] || 0));
    const tabHtml = `
      <button class="binder-tab ${agent.id === liveSelectedAgent && liveReportPage !== "attention" ? "active" : ""} status-${status}" data-agent-id="${agent.id}" title="${escapeHtml(`${agent.label} · click report · double-click backend · Ctrl/Cmd-click pin`)}">
        <span class="binder-icon">${liveAgentIconHtml(agent)}</span>
        <span class="binder-agent-copy">
          <span class="binder-short">${escapeHtml(agent.short)}</span>
          <span class="binder-label">${escapeHtml(agent.label)}</span>
        </span>
        <span class="binder-status-chip">${escapeHtml(status)}</span>
        <span class="binder-state-dot" aria-label="${status}"></span>
        ${unread ? `<span class="binder-unread">${unread > 9 ? "9+" : unread}</span>` : ""}
      </button>
    `;
    agentTabs.push(tabHtml);
  });
  liveAgentBinderList.innerHTML = `
    <div class="binder-agent-group">
      <div class="binder-title binder-title-inline" title="Agent group">AGENT</div>
      ${agentTabs.join("")}
    </div>
    <div class="binder-attention-group">
      <div class="binder-title binder-title-att" title="Operator Attention">ATT</div>
      <button class="binder-tab binder-attention-tab ${liveCurrentView === "report" && liveReportPage === "attention" ? "active" : ""} status-${attentionTone}" data-attention-action="open" title="Operator Attention · approvals ${attention.approvals}, questions ${attention.questions}, faults ${attention.faults}" aria-label="Operator Attention">
        <span class="binder-icon binder-attention-icon" aria-hidden="true">!</span>
        <span class="binder-agent-copy">
          <span class="binder-short">${attention.errors ? "ERR" : attention.total ? "ATT" : "OK"}</span>
          <span class="binder-label">Operator Attention</span>
        </span>
        <span class="binder-status-chip">${escapeHtml(attentionTone)}</span>
        <span class="binder-state-dot" aria-label="${attentionTone}"></span>
        ${attention.total ? `<span class="binder-unread">${attention.total > 9 ? "9+" : attention.total}</span>` : ""}
      </button>
    </div>
  `;
}

function liveCenterRenderKey(session = liveLastSession) {
  const snapshot = liveLastSnapshot || {};
  const state = session?.state || snapshot.state || {};
  const metadata = state.run_metadata && typeof state.run_metadata === "object" ? state.run_metadata : {};
  const boVisualization = metadata.bo_visualization && typeof metadata.bo_visualization === "object" ? metadata.bo_visualization : {};
  const runId = state.run_id || liveCurrentRunId() || "none";
  const stage = state.stage || "idle";
  const messageCount = Array.isArray(session?.messages) ? session.messages.length : planningMessagesCache.length;
  const approvalCount = (liveApprovals.pending || []).length + (liveApprovals.resolved || []).length;
  const guardianStatus = liveGuardianStatusPayload({ state });
  const guardianSummary = guardianStatus && guardianStatus.summary ? guardianStatus.summary : {};
  const guardianKey = guardianStatus
    ? [guardianStatus.status || "", guardianSummary.risk_score || 0, guardianSummary.gate_count || 0, guardianSummary.incident_count || 0, guardianSummary.blocked_action_count || 0, guardianSummary.pending_approval_count || 0].join(":")
    : "no-guardian-status";
  const graphLayoutKey = liveCurrentView === "graph" ? `${liveGraphLayoutMode()}:${liveGraphPanelWidthKey()}` : "";
  return [
    runId,
    stage,
    Number(state.loop_count || 0),
    Number(boVisualization.step || 0),
    String(boVisualization.generated_at || ""),
    liveSelectedAgent,
    liveReportPage,
    liveSelectedEventKey,
    liveSelectedGraphNodeId,
    liveSelectedReportSectionTitle,
    liveRunEvents.length,
    liveRecentEvents.length,
    liveRunArtifacts.length,
    messageCount,
    approvalCount,
    guardianKey,
    graphLayoutKey,
  ].join("|");
}

function invalidateLiveCenterRender(view = liveCurrentView || "report") {
  if (view && LIVE_VIEW_IDS.has(view)) liveCenterRenderKeys.delete(view);
}

function liveGraphLayoutMode() {
  const shell = document.querySelector(".planning-runtime-shell");
  const shellWidth = shell ? Math.round(shell.clientWidth || shell.getBoundingClientRect().width || 0) : Math.round(window.innerWidth || 0);
  const isStacked = shellWidth <= 760 || Boolean(window.matchMedia && window.matchMedia("(max-width: 760px)").matches);
  const isReportFocus = Boolean(shell && shell.classList.contains("live-agent-report-focus"));
  if (isStacked) return isReportFocus ? "stack-expanded" : "stack-split";
  return isReportFocus ? "expanded" : "split";
}

function liveGraphPanelWidthKey() {
  const panel = liveGraphPanel || document.getElementById("live-graph-panel");
  if (!panel) return 0;
  return Math.round(panel.clientWidth || panel.getBoundingClientRect().width || 0);
}

function renderActiveLiveCenterPanel(session = liveLastSession, options = {}) {
  if (!session) return;
  const key = liveCenterRenderKey(session);
  if (!options.force && liveCenterRenderKeys.get(liveCurrentView) === key) {
    if (liveCurrentView === "report") scheduleOrcEchartsRender();
    return;
  }
  if (liveCurrentView === "report") renderReportPanel(session);
  else if (liveCurrentView === "backend") renderBackendPanel(session);
  else if (liveCurrentView === "graph") renderGraphMiniPanel(session);
  else if (liveCurrentView === "artifacts") renderArtifactPanel();
  else if (liveCurrentView === "timeline") renderTimelinePanels();
  liveCenterRenderKeys.set(liveCurrentView, key);
}

function setLiveView(view, options = {}) {
  const previousView = liveCurrentView;
  liveCurrentView = LIVE_VIEW_IDS.has(view) ? view : "report";
  if (liveCurrentView === "graph" && previousView !== "graph") {
    syncLiveGraphSelectionFromAgent(liveSelectedAgent);
    liveGraphFocusPending = true;
  }
  const panelByView = {
    report: "live-report-panel",
    backend: "live-backend-panel",
    graph: "live-graph-panel",
    artifacts: "live-artifact-panel",
    timeline: "live-timeline-detail-panel",
  };
  document.querySelectorAll(".live-center-view").forEach((panel) => panel.classList.toggle("active", panel.id === panelByView[liveCurrentView]));
  liveViewTabs.forEach((button) => button.classList.toggle("active", button.dataset.liveView === liveCurrentView));
  renderLiveReportToolbar();
  applyLiveAgentLayoutMode();
  renderLiveChatContextStrip();
  persistLiveUiState();
  if (options.render !== false) renderActiveLiveCenterPanel(liveLastSession);
  else if (liveCurrentView === "report") scheduleOrcEchartsRender();
}


function reportEventLabel(event) {
  return `${formatTime(event.ts || event.timestamp)} · ${event.event_type || event.type || "event"}`;
}

function reportEventText(event, limit = 180) {
  const payload = eventPayload(event);
  const tail = event.message || event.status || payload.message || payload.status || "";
  return compactText(`${reportEventLabel(event)}${tail ? ` · ${tail}` : ""}`, limit);
}

function renderReportList(items, emptyText = "No evidence.", limit = 8) {
  const filtered = (items || []).filter(Boolean);
  const clean = Number.isFinite(limit) && limit > 0 ? filtered.slice(0, limit) : filtered;
  if (!clean.length) return `<p class="hint">${escapeHtml(emptyText)}</p>`;
  const rows = clean.map((item) => {
    const full = renderRuntimeValue(item);
    return `    <li title="${escapeHtml(full)}">${escapeHtml(renderDashboardValue(item, 132))}</li>`;
  }).join("\n");
  return `<ul class="live-report-list">\n${rows}\n  </ul>`;
}


function normalizeGuardianStatusPayload(payload) {
  return payload && typeof payload === "object" && payload.schema === "guardian_status_report.v1" ? payload : null;
}

function liveGuardianStatusPayload(report = null) {
  const snapshot = liveLastSnapshot || {};
  const state = (report && report.state) || (liveLastSession && liveLastSession.state) || snapshot.state || {};
  return normalizeGuardianStatusPayload(liveGuardianStatus)
    || normalizeGuardianStatusPayload(snapshot.guardian_status)
    || normalizeGuardianStatusPayload(state.guardian_status)
    || normalizeGuardianStatusPayload(report && report.guardian_status)
    || null;
}

function guardianRiskLevel(score) {
  const value = Number(score) || 0;
  if (value >= 0.9) return "critical";
  if (value >= 0.75) return "blocked";
  if (value >= 0.55) return "approval";
  if (value >= 0.35) return "warning";
  return "allow";
}

function renderGuardianRiskMap(status) {
  const risks = Array.isArray(status && status.graph_wide_risk_map) ? status.graph_wide_risk_map : [];
  if (!risks.length) return `<p class="hint">No graph-wide Guardian risk map is available yet.</p>`;
  return `
    <div class="live-guardian-risk-grid">
      ${risks.map((item) => {
        const score = Math.max(0, Math.min(1, Number(item.score) || 0));
        const percent = Math.round(score * 100);
        const level = guardianRiskLevel(score);
        return `
          <article class="live-guardian-risk-card risk-${escapeHtml(level)}">
            <div class="live-guardian-risk-head"><strong>${escapeHtml(item.risk_class || "risk")}</strong><span>${percent}%</span></div>
            <div class="live-guardian-risk-meter" aria-label="${escapeHtml(item.risk_class || "risk")} risk ${percent}%"><span style="width:${percent}%"></span></div>
            <p>${escapeHtml(item.stage || "-")} · ${escapeHtml(item.phase || "-")} · ${escapeHtml(item.decision || "allow")}</p>
            <small>${escapeHtml(item.reason_code || "OK")}</small>
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function renderGuardianApprovalQueue(status) {
  const queue = status && status.approval_queue && typeof status.approval_queue === "object" ? status.approval_queue : {};
  const pending = Array.isArray(queue.pending) ? queue.pending : [];
  const resolved = Array.isArray(queue.resolved) ? queue.resolved : [];
  const runId = status.run_id || liveCurrentRunId();
  const pendingMarkup = pending.slice(-8).reverse().map((item) => `
    <article class="live-guardian-approval-card">
      <strong>${escapeHtml(item.title || item.stage || "Approval required")}</strong>
      <p>${escapeHtml(item.reason || item.reason_code || item.status || "Operator review required.")}</p>
      <div class="button-row">
        <button class="btn primary live-approval-action" data-run-id="${escapeHtml(runId)}" data-approval-id="${escapeHtml(item.approval_id || "")}" data-decision="approved" ${item.approval_id ? "" : "disabled"}>Approve</button>
        <button class="btn live-approval-action" ${item.approval_id ? "" : "disabled"} data-run-id="${escapeHtml(runId)}" data-approval-id="${escapeHtml(item.approval_id || "")}" data-decision="cancelled">Revise</button>
        <button class="btn warning live-approval-action" data-run-id="${escapeHtml(runId)}" data-approval-id="${escapeHtml(item.approval_id || "")}" data-decision="rejected" ${item.approval_id ? "" : "disabled"}>Reject</button>
      </div>
    </article>
  `).join("");
  const resolvedItems = resolved.slice(-6).reverse().map((item) => `${item.approval_id || "approval"} · ${item.status || item.decision || "resolved"}`);
  return `
    ${pendingMarkup || `<p class="hint">No pending Guardian approval interrupts.</p>`}
    <h5>Resolved Approval History</h5>
    ${renderReportList(resolvedItems, "No resolved approvals recorded.", 6)}
  `;
}

function renderGuardianBlockedActions(status) {
  const blocked = status && status.blocked_actions && typeof status.blocked_actions === "object" ? status.blocked_actions : {};
  const gates = Array.isArray(blocked.gates) ? blocked.gates : [];
  const tools = Array.isArray(blocked.tool_calls) ? blocked.tool_calls : [];
  const hardware = Array.isArray(blocked.hardware_alerts) ? blocked.hardware_alerts : [];
  const gateItems = gates.slice(-10).reverse().map((item) => `${item.stage || "stage"}.${item.phase || "gate"} · ${item.decision || "blocked"} · ${item.reason_code || "-"} · risk=${renderRuntimeValue(item.risk_score)}`);
  const toolItems = tools.slice(-10).reverse().map((item) => `${item.stage || "stage"} · ${item.tool || "tool"} · ${item.status || "failed"} · ${item.failure_code || item.guardian_reason_code || "-"}`);
  const hardwareItems = hardware.slice(-10).reverse().map((item) => `${item.stage || "stage"} · ${item.device_class || "device"}/${item.component || "component"} · ${item.severity || ""} · ${item.failure_code || "-"}`);
  return `
    <h5>Blocked Gate Decisions</h5>
    ${renderReportList(gateItems, "No blocked Guardian gate decisions.", 10)}
    <h5>Blocked Tool Calls</h5>
    ${renderReportList(toolItems, "No blocked tool-call records.", 10)}
    <h5>Hardware Alerts</h5>
    ${renderReportList(hardwareItems, "No blocking hardware alerts.", 10)}
  `;
}

function renderGuardianIncidentLedger(status) {
  const ledger = status && status.incident_ledger && typeof status.incident_ledger === "object" ? status.incident_ledger : {};
  const records = Array.isArray(ledger.records) ? ledger.records : [];
  if (!records.length) return `<p class="hint">No incident or near-miss records have been written for this run.</p>`;
  return records.slice(-10).reverse().map((item) => {
    const incidentId = item.incident_id || item.id || "incident";
    return `
      <article class="live-guardian-incident-card">
        <div><strong>${escapeHtml(incidentId)}</strong><span>${escapeHtml(item.severity || "near_miss")}</span></div>
        <p>${escapeHtml(item.message || item.summary || item.reason_code || "Guardian incident recorded.")}</p>
        <small>${escapeHtml(item.stage || "-")} · ${escapeHtml(item.risk_class || item.component || "-")} · ${escapeHtml(item.corrective_action || item.recommended_action || "No corrective action recorded.")}</small>
        <button class="btn live-guardian-note-action" type="button" data-incident-id="${escapeHtml(incidentId)}" data-reason-code="${escapeHtml(item.reason_code || item.failure_code || "")}">Add Note</button>
      </article>
    `;
  }).join("");
}

function renderGuardianSafetyBudget(status) {
  const budget = status && status.safety_budget && typeof status.safety_budget === "object" ? status.safety_budget : {};
  const items = Array.isArray(budget.items) ? budget.items : [];
  const rows = items.map((item) => {
    const used = renderRuntimeValue(item.used);
    const limit = renderRuntimeValue(item.limit);
    const unit = item.unit || "";
    const pct = Math.round((Number(item.used_ratio) || 0) * 100);
    return `${item.resource || "budget"} · ${used}/${limit} ${unit} · ${pct}% · ${item.status || "within_budget"}`;
  });
  return `
    ${runtimeRows([
      ["schema", budget.schema || "guardian_safety_budget.v1"],
      ["status", budget.status || "within_budget"],
      ["source", budget.source || "runtime"],
    ])}
    ${renderReportList(rows, "No safety budget items have been computed yet.", 10)}
  `;
}

function renderGuardianLiveHeartbeat(status) {
  const deviceData = status && status.device_data_integrity && typeof status.device_data_integrity === "object" ? status.device_data_integrity : {};
  const heartbeats = Array.isArray(deviceData.live_device_heartbeat) ? deviceData.live_device_heartbeat : [];
  const rows = heartbeats.map((item) => `${item.device_id || "device"} · ${item.heartbeat_status || "review"} · ${item.bridge_state || "unknown"} · ${item.last_command || "runtime snapshot"}`);
  return renderReportList(rows, "No device heartbeat rows are available yet.", 12);
}

function renderGuardianSafeStopVerification(status) {
  const safeStop = status && status.safe_stop_verification && typeof status.safe_stop_verification === "object" ? status.safe_stop_verification : {};
  const latestGate = safeStop.latest_gate && typeof safeStop.latest_gate === "object" ? safeStop.latest_gate : {};
  return runtimeRows([
    ["schema", safeStop.schema || "guardian_safe_stop_verification.v1"],
    ["requested", safeStop.requested === undefined ? false : safeStop.requested],
    ["verified", safeStop.verified === undefined ? false : safeStop.verified],
    ["status", safeStop.status || "not_requested"],
    ["verification_basis", safeStop.verification_basis || "none"],
    ["latest_gate", latestGate.gate_id || "-"],
  ]);
}

function renderGuardianEvidenceCompleteness(status) {
  const evidence = status && status.evidence_completeness && typeof status.evidence_completeness === "object" ? status.evidence_completeness : {};
  return runtimeRows([
    ["schema", evidence.schema || "guardian_evidence_completeness.v1"],
    ["status", evidence.status || "missing"],
    ["score", evidence.score ?? "-"],
    ["artifact_ref_count", evidence.artifact_ref_count ?? 0],
    ["provenance_ref_count", evidence.provenance_ref_count ?? 0],
    ["checks", evidence.checks || {}],
  ]);
}

function renderGuardianSelfEvolutionGate(status) {
  const gate = status && status.self_evolution_gate && typeof status.self_evolution_gate === "object" ? status.self_evolution_gate : {};
  const pending = Array.isArray(gate.pending_variants) ? gate.pending_variants : [];
  const active = Array.isArray(gate.active_variants) ? gate.active_variants : [];
  const pendingItems = pending.slice(-8).reverse().map((item) => `${item.variant_id || "variant"} · ${item.target_type || "target"}:${item.target_id || "-"} · ${item.status || "pending"}`);
  const activeItems = active.slice(-8).reverse().map((item) => `${item.variant_id || "variant"} · ${item.target_type || "target"}:${item.target_id || "-"} · ${item.status || "active"}`);
  return `
    ${runtimeRows([
      ["schema", gate.schema || "guardian_self_evolution_gate.v1"],
      ["status", gate.status || "idle"],
      ["variant_count", gate.variant_count ?? 0],
      ["error", gate.error || "-"],
    ])}
    <h5>Pending Variants</h5>
    ${renderReportList(pendingItems, "No self-evolution variants pending Guardian activation gate.", 8)}
    <h5>Active / Next-Run Variants</h5>
    ${renderReportList(activeItems, "No active self-evolution variants recorded.", 8)}
  `;
}

function renderGuardianReportDetails(report) {
  const status = liveGuardianStatusPayload(report);
  if (!status) return `<p class="hint">Guardian status report is not available yet. Refresh the active run state after a run starts.</p>`;
  const summary = status.summary && typeof status.summary === "object" ? status.summary : {};
  const deviceData = status.device_data_integrity && typeof status.device_data_integrity === "object" ? status.device_data_integrity : {};
  const policy = status.policy_version_panel && typeof status.policy_version_panel === "object" ? status.policy_version_panel : {};
  const handoff = status.handoff_packet && typeof status.handoff_packet === "object" ? status.handoff_packet : {};
  const latestDecision = handoff.latest_guardian_decision && typeof handoff.latest_guardian_decision === "object" ? handoff.latest_guardian_decision : {};
  const latestContract = handoff.latest_guardian_contract && typeof handoff.latest_guardian_contract === "object" ? handoff.latest_guardian_contract : {};
  const corrective = Array.isArray(handoff.corrective_actions) ? handoff.corrective_actions : [];
  const correctiveItems = corrective.slice(-8).reverse().map((item) => `${item.action_id || item.action || "corrective_action"} · ${item.status || "open"} · ${item.description || item.message || item.owner || "-"}`);
  return `
    <div class="live-agent-specific-guardian-details">
      <h5>Graph-Wide Risk Map</h5>
      ${renderGuardianRiskMap(status)}
      <h5>Guardian Status Summary</h5>
      ${runtimeRows([
        ["schema", status.schema || "guardian_status_report.v1"],
        ["run_id", status.run_id || "-"],
        ["stage", status.stage || "-"],
        ["status", status.status || "-"],
        ["risk_score", summary.risk_score ?? "-"],
        ["dominant_risks", summary.dominant_risks || []],
        ["gate_count", summary.gate_count ?? "-"],
        ["incident_count", summary.incident_count ?? "-"],
        ["blocked_action_count", summary.blocked_action_count ?? "-"],
        ["pending_approval_count", summary.pending_approval_count ?? "-"],
        ["safety_budget_status", summary.safety_budget_status || "-"],
        ["safe_stop_status", summary.safe_stop_status || "-"],
        ["evidence_completeness_status", summary.evidence_completeness_status || "-"],
        ["self_evolution_gate_status", summary.self_evolution_gate_status || "-"],
        ["latest_decision", latestDecision.decision || "-"],
        ["latest_reason", latestDecision.reason_code || latestContract.failure_code || "-"],
        ["ok_for_next_stage", latestContract.ok_for_next_stage === undefined ? "-" : latestContract.ok_for_next_stage],
        ["ok_for_bo", latestContract.ok_for_bo === undefined ? "-" : latestContract.ok_for_bo],
      ])}
      <h5>Safety Budget</h5>
      ${renderGuardianSafetyBudget(status)}
      <h5>Live Device Heartbeat</h5>
      ${renderGuardianLiveHeartbeat(status)}
      <h5>Safe-Stop Verification</h5>
      ${renderGuardianSafeStopVerification(status)}
      <h5>Evidence Completeness</h5>
      ${renderGuardianEvidenceCompleteness(status)}
      <h5>Self-Evolution Gate</h5>
      ${renderGuardianSelfEvolutionGate(status)}
      <h5>Gate Timeline</h5>
      ${renderReportList((Array.isArray(status.gate_timeline) ? status.gate_timeline : []).slice(-14).reverse().map((item) => `${item.stage || "stage"}.${item.phase || "gate"}${item.tool ? `/${item.tool}` : ""} · ${item.decision || "allow"} · ${item.reason_code || "OK"} · risk=${renderRuntimeValue(item.risk_score)}`), "No Guardian gate timeline recorded.", 14)}
      <h5>Blocked Actions</h5>
      ${renderGuardianBlockedActions(status)}
      <h5>Approval Queue</h5>
      ${renderGuardianApprovalQueue(status)}
      <h5>Incident / Near-Miss Ledger</h5>
      ${renderGuardianIncidentLedger(status)}
      <h5>Policy / Version Panel</h5>
      ${runtimeRows([
        ["guardian_gate_schema", policy.guardian_gate_schema || "-"],
        ["contract_schema", policy.contract_schema || "-"],
        ["decision_schema", policy.decision_schema || "-"],
        ["incident_schema", policy.incident_schema || "-"],
        ["tool_call_schema", policy.tool_call_schema || "-"],
        ["source_doc", policy.source_doc || "-"],
      ])}
      <h5>Device / Data Integrity</h5>
      ${runtimeRows([
        ["device_health", deviceData.device_health || {}],
        ["live_device_heartbeat", deviceData.live_device_heartbeat || []],
        ["hardware_alert_count", deviceData.hardware_alert_count ?? "-"],
        ["tool_call_counts", deviceData.tool_call_counts || {}],
        ["data_related_incident_count", deviceData.data_related_incident_count ?? "-"],
      ])}
      <h5>Corrective Actions</h5>
      ${renderReportList(correctiveItems, "No corrective actions recorded.", 8)}
    </div>
  `;
}

function reportSectionKey(title) {
  return String(title || "section")
    .toLowerCase()
    .replace(/[^a-z0-9가-힣]+/g, "-")
    .replace(/^-+|-+$/g, "") || "section";
}

function selectedReportSectionText(limit = 1200) {
  const title = String(liveSelectedReportSectionTitle || "");
  if (!title || !liveReportPanel) return "";
  const sections = Array.from(liveReportPanel.querySelectorAll(".live-report-section[data-report-section-title]"));
  const section = sections.find((item) => item.dataset.reportSectionTitle === title);
  return compactText((section && section.textContent) || "", limit);
}

function selectedReportSectionLabel() {
  return liveSelectedReportSectionTitle || "Overview / Summary";
}

function selectedReportSectionPayload(limit = 1200) {
  const sectionTitle = selectedReportSectionLabel();
  return {
    selected_report_section: sectionTitle,
    selected_report_section_key: reportSectionKey(sectionTitle),
    selected_report_section_text: selectedReportSectionText(limit),
  };
}

function safeReportFilenamePart(value) {
  return String(value || "section")
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "") || "section";
}

function updateSelectedReportSectionDom() {
  if (!liveReportPanel) return;
  liveReportPanel.querySelectorAll(".live-report-section[data-report-section-title]").forEach((section) => {
    const selected = section.dataset.reportSectionTitle === liveSelectedReportSectionTitle;
    section.classList.toggle("selected", selected);
    section.setAttribute("aria-selected", selected ? "true" : "false");
  });
}

function selectLiveReportSection(title, options = {}) {
  const clean = String(title || "").trim();
  if (!clean) return;
  liveSelectedReportSectionTitle = clean;
  updateSelectedReportSectionDom();
  renderLiveChatContextStrip();
  persistLiveUiState();
  if (options.status !== false) setChatStatus(`SECTION: ${compactText(clean, 22)}`, "idle");
}

function renderReportSection(title, body, options = {}) {
  const content = String(body || `<p class="hint">No evidence.</p>`);
  const wideClass = options.wide ? " runtime-card-wide" : "";
  const sectionTitle = String(title || "Section");
  const selected = sectionTitle === liveSelectedReportSectionTitle;
  const sectionKey = reportSectionKey(sectionTitle);
  return `
    <section class="runtime-card-section live-report-section${wideClass}${selected ? " selected" : ""}" data-report-section-title="${escapeHtml(sectionTitle)}" data-report-section-key="${escapeHtml(sectionKey)}" tabindex="0" role="button" aria-selected="${selected ? "true" : "false"}" aria-label="Select report section: ${escapeHtml(sectionTitle)}">
      <h4>${escapeHtml(title)}</h4>
      <div class="live-report-section-body">
${content}
      </div>
    </section>
  `;
}

function selectedReportModel(session) {
  const snapshot = liveLastSnapshot || {};
  const state = session.state || snapshot.state || {};
  const spec = state.current_experiment_spec || {};
  const messages = selectedMessages();
  const events = selectedEvents();
  const payloadEvents = events.map((event) => ({ event, payload: eventPayload(event) }));
  const latestMessage = messages[messages.length - 1] || null;
  const toolItems = [];
  for (const { event, payload } of payloadEvents) {
    const toolValue = backendField(payload, ["tool_calls", "tools", "tool", "tool_name", "tool_result", "tool_results"]);
    if (toolValue) toolItems.push(`${reportEventLabel(event)} · ${renderRuntimeValue(toolValue)}`);
  }
  const artifactItems = [];
  for (const msg of messages) {
    const artifacts = msg.artifacts || msg.fem_artifacts || msg.bo_result || msg.specimen || null;
    if (artifacts) artifactItems.push(`${roleLabel(msg.role)} · ${renderRuntimeValue(artifacts)}`);
  }
  for (const { event, payload } of payloadEvents) {
    const artifactValue = backendField(payload, ["artifacts", "artifact", "artifact_paths", "artifact_ids", "stl_path", "gcode_path", "report_url"]);
    if (artifactValue) artifactItems.push(`${reportEventLabel(event)} · ${renderRuntimeValue(artifactValue)}`);
  }
  const warnings = events
    .filter((event) => ["warning", "error"].includes(eventTimelineKind(event)))
    .map((event) => reportEventText(event));
  const handoffs = events
    .filter((event) => {
      const text = `${event.event_type || event.type || ""} ${event.message || ""}`.toLowerCase();
      return text.includes("handoff") || text.includes("stage_changed") || text.includes("next_stage");
    })
    .map((event) => reportEventText(event));
  const validationItems = payloadEvents
    .map(({ event, payload }) => {
      const value = backendField(payload, ["validation", "quality_check", "gate", "gate_results", "errors", "warnings", "ok", "status"]);
      return value === null || value === undefined ? "" : `${reportEventLabel(event)} · ${renderRuntimeValue(value)}`;
    })
    .filter(Boolean);
  const processItems = events.slice(-8).map((event) => reportEventText(event));
  const decisionItems = messages.slice(-6).map((msg) => `${formatTime(msg.timestamp)} · ${roleLabel(msg.role)} · ${compactText(msg.content || "", 220)}`);
  const nextAction = handoffs[handoffs.length - 1]
    || (state.stage ? `Continue from current stage '${state.stage}' after checking required approvals and failed gates.` : "Wait for the next orchestrator instruction or operator command.");
  return {
    state,
    spec,
    messages,
    events,
    latestMessage,
    toolItems,
    artifactItems,
    warnings,
    handoffs,
    validationItems,
    processItems,
    decisionItems,
    nextAction,
  };
}


function latestReportPayload(report, keys) {
  const sources = [];
  const state = report && report.state ? report.state : {};
  const metadata = state && typeof state.run_metadata === "object" && state.run_metadata ? state.run_metadata : {};
  if (metadata) {
    sources.push(metadata);
    if (metadata.last_stage_payload) sources.push(metadata.last_stage_payload);
    if (metadata.last_stage_payload && metadata.last_stage_payload.data) sources.push(metadata.last_stage_payload.data);
    for (const value of Object.values(metadata)) {
      if (value && typeof value === "object" && !Array.isArray(value)) sources.push(value);
    }
  }
  for (const msg of report.messages || []) sources.push(msg);
  for (const event of report.events || []) sources.push(eventPayload(event));
  for (let index = sources.length - 1; index >= 0; index -= 1) {
    const value = backendField(sources[index], keys);
    if (value !== null && value !== undefined && value !== "") return value;
  }
  return null;
}

