function applyPlanningSession(session) {
  const authoritativeSession = session || {};
  const runTransitionReset = resetLiveRunScopedStateForAuthoritativeSession(authoritativeSession);
  liveLastSession = runTransitionReset
    ? {
        ...authoritativeSession,
        messages: [],
        message_total: 0,
        has_more_messages: false,
        next_before: null,
      }
    : authoritativeSession;
  if (liveLastSession.planning_session_id) {
    persistPlanningSessionId(liveLastSession.planning_session_id);
  }
  const snapshot = liveLastSnapshot || {};
  const state = liveLastSession.state || snapshot.state || {};
  const metadata = state.run_metadata || {};
  syncLiveBoVisualizationFromState(state);
  planningPendingSpecimenInput = metadata.pending_specimen_input || null;
  const running = liveRunningFlag(liveLastSession, snapshot, state);
  setLiveBackendPlanningBusy(Boolean(liveLastSession.is_planning_busy));
  setPlanningDot(running);
  const stageLabel = String(state.stage || "idle");
  const runId = String(state.run_id || "-");
  const modeLabel = String(state.mode || "-");
  const missionLabel = `S:${stageLabel}`;
  // Legacy package contract marker: setCompactTextWithTitle(planningStageLabel, `S:${stageLabel}`, ...).
  setCompactTextWithTitle(planningStageLabel, missionLabel, `Mission: ${state.active_goal || state.goal || queryGoal || "-"}; Stage: ${stageLabel}`);
  scheduleLiveMissionMarquee();
  const cycleLabel = formatPlanningCycleLabel(state, running);
  setCompactTextWithTitle(planningCycleLabel, cycleLabel, `Cycle: ${cycleLabel}`);
  setCompactTextWithTitle(
    planningRunDetail,
    liveRunTopbarLabel(runId, modeLabel, running),
    `run=${runId} mode=${modeLabel} running=${running}`
  );
  renderSpecSummary(state);
  const activeSessionId = liveLastSession.planning_session_id || planningSessionId || "";
  if (planningHistorySessionId && activeSessionId && planningHistorySessionId !== activeSessionId) {
    resetPlanningMessageDisplayState();
  }
  planningHistorySessionId = activeSessionId;
  planningHistoryHasMore = Boolean(liveLastSession.has_more_messages);
  planningHistoryTotal = Number(liveLastSession.message_total || 0);
  const incomingMessages = Array.isArray(liveLastSession.messages) ? liveLastSession.messages : [];
  if (planningHistoryTotal && planningMessagesCache.length > planningHistoryTotal) {
    resetPlanningMessageDisplayState();
  }
  renderPlanningMessages(mergePlanningMessages(planningMessagesCache, incomingMessages));
  renderLiveRuntime(liveLastSession);
  persistLivePlanningCache(liveLastSession);
}

async function refreshLiveGraphPayload() {
  try {
    const graphRes = await fetch("/api/graphs/atr_closed_loop");
    if (graphRes.ok) {
      liveGraphPayload = await graphRes.json();
    }
  } catch (err) {
    // Keep the last known graph if a transient refresh fails.
  }
  return liveGraphPayload;
}

function liveSpecimenAgentWorking(session = liveLastSession) {
  const snapshot = liveLastSnapshot || {};
  const state = (session && session.state) || snapshot.state || {};
  const running = liveRunningFlag(session || {}, snapshot, state);
  const activeAgent = agentIdFromStage(state.stage || "");
  if (running && activeAgent === "specimen") return true;
  const activePattern = /started|running|working|active|printing|print|upload|slice|slicer|gcode|autoejection|ejection/i;
  return currentRunEventSources().slice(-40).some((event) => {
    if (!event || event.event_type === "workspace_monitor_snapshot") return false;
    if (agentIdFromEvent(event) !== "specimen") return false;
    const payload = eventPayload(event);
    const text = [
      event.status,
      event.event_type,
      event.type,
      event.message,
      payload.tool,
      payload.status,
      payload.workflow,
    ].map((value) => String(value || "")).join(" ");
    return activePattern.test(text);
  });
}

async function refreshLivePrinterMonitorStatus(session = liveLastSession, options = {}) {
  if (!options.force && !liveSpecimenAgentWorking(session)) return null;
  if (livePrinterMonitorInFlight) return livePrinterMonitorInFlight;
  livePrinterMonitorInFlight = (async () => {
    try {
      return await fetchJsonOrThrow("/api/printer/status?mode=live&emit=1");
    } catch (err) {
      return null;
    } finally {
      livePrinterMonitorInFlight = null;
    }
  })();
  return livePrinterMonitorInFlight;
}

async function refreshLivePrinterVideoStatus() {
  if (livePrinterVideoStatusInFlight) return livePrinterVideoStatusInFlight;
  livePrinterVideoStatusInFlight = (async () => {
    try {
      return await fetchJsonOrThrow("/api/printer/video-status");
    } catch (err) {
      return {
        ok: false,
        tool: "printer.bambu.video_status",
        status: "video_status_failed",
        error: err && err.message ? err.message : String(err || "video status failed"),
      };
    } finally {
      livePrinterVideoStatusInFlight = null;
    }
  })();
  return livePrinterVideoStatusInFlight;
}

async function refreshPlanningAuxiliaryState(session) {
  if (liveAuxRefreshInFlight) return liveAuxRefreshInFlight;
  liveAuxRefreshInFlight = (async () => {
    try {
      const [guardianResult, eventsResult, printerStatusResult, relationSummaryResult] = await Promise.allSettled([
        fetch("/api/guardian/status"),
        fetch("/api/events/recent"),
        refreshLivePrinterMonitorStatus(session),
        fetch("/api/knowledge/relations/summary"),
        refreshLiveObjectiveState(session),
      ]);
      let guardianPayload = null;
      if (guardianResult.status === "fulfilled" && guardianResult.value.ok) {
        guardianPayload = await guardianResult.value.json();
        liveGuardianStatus = normalizeGuardianStatusPayload(guardianPayload) || liveGuardianStatus;
      }
      if (eventsResult.status === "fulfilled" && eventsResult.value.ok) {
        const recentPayload = await eventsResult.value.json();
        liveRecentEvents = Array.isArray(recentPayload.events) ? recentPayload.events : [];
      }
      if (relationSummaryResult.status === "fulfilled" && relationSummaryResult.value.ok) {
        const relationPayload = await relationSummaryResult.value.json();
        if (relationPayload && relationPayload.relation_reconciliation) {
          liveKnowledgeRelationSummary = {
            ...liveKnowledgeRelationSummary,
            ...relationPayload.relation_reconciliation,
          };
        }
      }
      if (printerStatusResult.status === "fulfilled" && printerStatusResult.value) {
        const status = printerStatusResult.value;
        const runId = liveCurrentRunId();
        liveRecentEvents.push({
          run_id: runId,
          event_id: `live-printer-monitor-${Date.now()}`,
          event_type: "workspace_monitor_snapshot",
          type: "tool.completed",
          level: status.ok ? "INFO" : "WARNING",
          severity: status.ok ? "info" : "warning",
          node_id: "specimen",
          module_id: "specimen",
          agent: "specimen_agent",
          status: status.status || (status.ok ? "ready" : "blocked"),
          message: `printer workspace printer.status ${status.status || ""}`.trim(),
          ts: new Date().toISOString(),
          timestamp: new Date().toISOString(),
          payload: {
            run_id: runId,
            workspace: "printer",
            tool: "printer.status",
            workflow: "printer_status_monitor",
            monitor_snapshot: {
              ok: status.ok,
              tool: status.tool || "printer.status",
              status: status.status,
              mode: status.mode,
              provider: status.provider,
              selected_printer: status.selected_printer,
              device_screen: status.device_screen,
              preprint_gate: status.preprint_gate,
              operator_actions: status.operator_actions,
              live_gates: status.live_gates,
              auto_ejection: status.auto_ejection,
            },
          },
        });
        liveRecentEvents = dedupeRuntimeEvents(liveRecentEvents).slice(-160);
      }
      liveLastSnapshot = {
        state: (session && session.state) || (liveLastSession && liveLastSession.state) || {},
        runtime: (session && session.runtime) || (liveLastSession && liveLastSession.runtime) || {},
        guardian_status: guardianPayload || liveGuardianStatus,
      };
      refreshLiveUtmRuntimeStatus({ render: true });
      await refreshLiveGraphPayload();
      await refreshLiveRunDetails(session || liveLastSession || {});
      renderLiveRuntime(liveLastSession);
      persistLivePlanningCache(liveLastSession);
    } catch (err) {
      markLiveSyncError(err);
    } finally {
      liveAuxRefreshInFlight = null;
    }
  })();
  return liveAuxRefreshInFlight;
}

async function refreshPlanningState(options = {}) {
  if (liveRefreshInFlight && !options.force) return liveRefreshInFlight;
  const background = Boolean(options.background);
  if (background && shouldFreezeCompletedTestRun(liveLastSession)) return liveLastSession;
  markLiveSyncRefreshStart();
  liveRefreshInFlight = (async () => {
    try {
      const sessionId = encodeURIComponent(ensurePlanningSessionId());
      const sessionRes = await fetch(`/api/planning/session?session_id=${sessionId}`);
      if (!sessionRes.ok) throw new Error(`session HTTP ${sessionRes.status}`);
      const session = await sessionRes.json();
      liveLastSnapshot = {
        state: session.state || {},
        runtime: session.runtime || {},
        guardian_status: liveGuardianStatus,
      };
      if (!session.state && liveLastSnapshot.state) session.state = liveLastSnapshot.state;
      if (!session.runtime && liveLastSnapshot.runtime) session.runtime = liveLastSnapshot.runtime;
      applyPlanningSession(session);
      markLiveSyncComplete();
      if (!shouldFreezeCompletedTestRun(session)) refreshPlanningAuxiliaryState(session);
      return session;
    } catch (err) {
      markLiveSyncError(err);
      if (!background) throw err;
      return liveLastSession;
    } finally {
      liveRefreshInFlight = null;
    }
  })();
  return liveRefreshInFlight;
}

function schedulePlanningRefresh() {
  if (planningRefreshTimer) return;
  planningRefreshTimer = window.setTimeout(async () => {
    planningRefreshTimer = null;
    try {
      await refreshPlanningState({ background: true });
    } catch (err) {
      setChatStatus("SYNC ERROR", "warning");
    }
  }, 300);
}

async function sendPlanningMessage(message) {
  const clean = String(message || "").trim();
  if (!clean) return;
  if (planningMessageSubmitInFlight) {
    setChatStatus("SENDING", "running");
    return;
  }
  const queueOnly = Boolean(liveBackendPlanningBusy || planningThinkingCount > 0 || liveQuickActionBusy);
  planningMessageSubmitInFlight = true;
  updatePlanningControls();
  if (planningMessageInput) planningMessageInput.value = "";

  const baseMessages = [...planningMessagesCache];
  const pendingRole = queueOnly ? "orchestrator" : (planningPendingSpecimenInput ? "printer_ai" : "orchestrator");
  const pendingModel = queueOnly ? "orchestrator_supervisor" : (planningPendingSpecimenInput ? "specimen_agent" : "orchestrator_plan");
  setChatStatus(queueOnly ? "QUEUING" : "REASONING", "running");
  pushPlanningThinking();
  renderPlanningMessages([
    ...baseMessages,
    {
      role: "operator",
      content: clean,
    },
    {
      role: pendingRole,
      content: "",
      pendingReasoning: true,
      model: pendingModel,
    },
  ]);

  try {
    const res = await fetch("/api/planning/message", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(collectPlanningPayload(clean, { runtimeFollowupQueueOnly: queueOnly })),
    });
    const data = await res.json();
    applyPlanningSession(data.session || {});
    setChatStatus(data.ok ? "READY" : "ERROR", data.ok ? "idle" : "warning");
  } catch (err) {
    try {
      await refreshPlanningState();
      setChatStatus("READY", "idle");
    } catch (refreshErr) {
      setChatStatus("ERROR", "warning");
      renderPlanningMessages([
        ...baseMessages,
        {
          role: "operator",
          content: clean,
        },
        {
          role: "system",
          content: `Live GUI request failed: ${err}`,
        },
      ]);
    }
  } finally {
    planningMessageSubmitInFlight = false;
    popPlanningThinking();
  }
}

function collectPlanningContextPayload() {
  return {
    goal: planningGoalInput ? planningGoalInput.value : queryGoal,
    backend: queryBackend,
    session_id: ensurePlanningSessionId(),
    constraints: collectOptionalConstraints(),
  };
}

async function bootstrapLiveOrchestrator() {
  const params = new URLSearchParams(window.location.search);
  const shouldAutoStart = params.get("auto") === "1" || params.get("fresh") === "1";
  if (planningBootstrapStarted || !shouldAutoStart) return;
  planningBootstrapStarted = true;

  const baseMessages = [...planningMessagesCache];
  setChatStatus("REASONING", "running");
  pushPlanningThinking();
  renderPlanningMessages([
    ...baseMessages,
    {
      role: "orchestrator",
      content: "",
      pendingReasoning: true,
      model: "orchestrator_plan",
    },
  ]);

  try {
    const res = await fetch("/api/planning/bootstrap", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(collectPlanningContextPayload()),
    });
    const data = await res.json();
    applyPlanningSession(data.session || {});
    setChatStatus(data.ok ? "READY" : "ERROR", data.ok ? "idle" : "warning");
  } catch (err) {
    setChatStatus("ERROR", "warning");
    renderPlanningMessages([
      ...baseMessages,
      {
        role: "system",
        content: `Live GUI bootstrap failed: ${err}`,
      },
    ]);
  } finally {
    popPlanningThinking();
  }
}

function shouldRefreshPlanningForRuntimeEvent(eventType, data = {}) {
  const type = String(eventType || data.event_type || data.type || "").toLowerCase();
  if (!type || type === "stream.heartbeat") return false;
  if (type.startsWith("operator.")) return false;
  if (type.startsWith("planning_") || type.startsWith("planning.")) return true;
  if (type.startsWith("module_step_") || type.startsWith("module_graph_")) return true;
  if (["stage_transition", "agent_started", "agent_result", "workflow_complete", "artifact.created"].includes(type)) return true;
  if (type.includes("handoff") || type.includes("guardian") || type.includes("incident") || type.includes("approval")) return true;
  if (type.includes("agent") || type.includes("device") || type.includes("run") || type.includes("evolution")) return true;
  const payload = data && typeof data.payload === "object" ? data.payload : {};
  return Boolean(payload.stage || payload.agent || payload.node_id || payload.module_id || payload.status);
}

function updateLiveBoVisualizationCards(visualization, expectedRunId = liveCurrentRunId()) {
  const renderer = window.BOVisualization;
  const cachedVisualization = currentRunBoVisualization(liveBoVisualization, expectedRunId);
  const incomingVisualization = currentRunBoVisualization(visualization, expectedRunId);
  const currentVisualization = preferredLiveBoVisualization(
    incomingVisualization,
    cachedVisualization,
    expectedRunId
  );
  if (!currentVisualization) {
    const incomingRunId = String(visualization?.run_id || "");
    if (cachedVisualization && (!incomingRunId || incomingRunId === String(expectedRunId || ""))) return false;
    clearLiveBoVisualization();
    return false;
  }
  if (!incomingVisualization && cachedVisualization) {
    const incomingStep = Number(visualization?.step || 0);
    const cachedStep = Number(cachedVisualization.step || 0);
    if (incomingStep >= cachedStep) scheduleLiveBoVisualizationHydration();
    return false;
  }
  if (
    incomingVisualization
    && cachedVisualization
    && currentVisualization === cachedVisualization
    && Number(incomingVisualization.step || 0) > Number(cachedVisualization.step || 0)
  ) {
    scheduleLiveBoVisualizationHydration();
  }
  liveBoVisualization = currentVisualization;
  invalidateLiveCenterRender("report");
  if (liveSelectedAgent !== "bo" || liveCurrentView !== "report") return true;
  const equation = liveReportPanel?.querySelector("[data-live-bo-equation]");
  const posterior = liveReportPanel?.querySelector("[data-live-bo-posterior]");
  if (equation) equation.innerHTML = renderer.renderEquationCard(currentVisualization);
  if (posterior) posterior.innerHTML = renderer.renderPlot(currentVisualization, {
    mode: "parameter_slice",
    parameter: currentVisualization.view?.selected_parameter || "",
  });
  return Boolean(equation || posterior);
}

async function hydrateLiveBoVisualization() {
  try {
    const response = await fetch("/api/bo/config", { cache: "no-store" });
    if (!response.ok) return false;
    const payload = await response.json();
    const runId = String(payload?.state?.run_id || payload?.run_id || liveCurrentRunId());
    if (!payload.recent_visualization || !Object.keys(payload.recent_visualization).length) {
      return Boolean(currentRunBoVisualization(liveBoVisualization, runId));
    }
    return updateLiveBoVisualizationCards(payload.recent_visualization, runId);
  } catch (_err) {
    return false;
  }
}

function connectPlanningEventStream() {
  if (!window.EventSource) {
    markLiveStreamState("unsupported");
    return;
  }
  markLiveStreamState("connecting");
  const source = new EventSource("/api/events/stream");
  source.onopen = () => {
    markLiveStreamState("live");
  };
  source.addEventListener("update", (event) => {
    try {
      const data = JSON.parse(event.data || "{}");
      const eventType = String(data.event_type || data.type || "");
      const eventTime = data.ts || data.timestamp || new Date().toISOString();
      markLiveStreamState("live", eventTime);
      if (eventType === "bo.visualization.updated") {
        updateLiveBoVisualizationCards(data.payload?.visualization);
        // SSE keeps large posterior arrays compact; fetch the complete state
        // and its server-rendered artifact URLs after the notification.
        hydrateLiveBoVisualization();
      }
      if (eventType) {
        liveRecentEvents.push(data);
        liveRecentEvents = liveRecentEvents.slice(-160);
      }
      const eventRunId = String(data.run_id || data.payload?.run_id || "");
      const sameCompletedRunEvent = shouldFreezeCompletedTestRun(liveLastSession)
        && (!eventRunId || eventRunId === liveCurrentRunId());
      if (sameCompletedRunEvent) return;
      if (shouldRefreshPlanningForRuntimeEvent(eventType, data)) {
        schedulePlanningRefresh();
      } else {
        renderLiveRuntime(liveLastSession);
      }
    } catch (err) {
      markLiveStreamState("error");
      setChatStatus("ERROR", "warning");
    }
  });
  source.onerror = () => {
    markLiveStreamState("error");
    setChatStatus("STREAM", "warning");
  };
}


function closeBinderContextMenu() {
  if (!liveBinderContextMenu) return;
  liveBinderContextMenu.hidden = true;
  liveBinderContextMenu.innerHTML = "";
}

function openBinderContextMenu(agentId, x, y) {
  if (!liveBinderContextMenu || !knownLiveAgent(agentId)) return;
  const agentLabel = liveAgentLabel(agentId);
  const actions = [
    ["open_report", "R", "Open Report"],
    ["open_backend", "{}", "Open Backend"],
    ["show_tool_calls", "TC", "Show Tool Calls"],
    ["show_artifacts", "A", "Show Artifacts"],
    ["open_graph", "G", "Open Graph"],
    ["open_evolution", "EV", "Open Evolution"],
    ["mark_read", "OK", "Mark Read"],
    ["run_node_test", "T", "Run Node Test"],
    ["rerun_from_here", "RR", "Re-run From Here"],
  ];
  liveBinderContextMenu.innerHTML = `
    <div class="live-context-title">${escapeHtml(agentLabel)}</div>
    ${actions.map(([action, icon, label]) => `
      <button class="btn live-context-action" type="button" role="menuitem" data-context-action="${escapeHtml(action)}" data-agent-id="${escapeHtml(agentId)}" title="${escapeHtml(label)}" aria-label="${escapeHtml(`${agentLabel}: ${label}`)}">
        <span class="live-card-action-icon" aria-hidden="true">${escapeHtml(icon)}</span>
        <span class="live-card-action-label">${escapeHtml(label)}</span>
      </button>
    `).join("")}
  `;
  const menuWidth = 210;
  const menuHeight = 360;
  const left = Math.max(8, Math.min(Math.round(x || 0), Math.max(8, window.innerWidth - menuWidth - 8)));
  const top = Math.max(8, Math.min(Math.round(y || 0), Math.max(8, window.innerHeight - menuHeight - 8)));
  liveBinderContextMenu.style.left = `${left}px`;
  liveBinderContextMenu.style.top = `${top}px`;
  liveBinderContextMenu.hidden = false;
}

function graphNodeIdForAgent(agentId) {
  const graph = (liveGraphPayload && liveGraphPayload.graph) || liveGraphPayload || {};
  const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
  const node = nodes.find((item) => agentIdFromStage(item.stage || item.id) === agentId) || nodes.find((item) => item.id === agentId);
  return node ? node.id : "";
}


function syncLiveGraphSelectionFromAgent(agentId = liveSelectedAgent) {
  const nodeId = graphNodeIdForAgent(agentId);
  if (!nodeId) return "";
  liveSelectedGraphNodeId = nodeId;
  liveGraphSelectionCleared = false;
  return nodeId;
}

function requestLiveGraphFocusForAgent(agentId = liveSelectedAgent) {
  const nodeId = syncLiveGraphSelectionFromAgent(agentId);
  if (nodeId) liveGraphFocusPending = true;
  return nodeId;
}

function focusLiveGraphNode(nodeId = "", options = {}) {
  if (!liveGraphPanel || liveCurrentView !== "graph") return false;
  const canvas = liveGraphPanel.querySelector(".live-graph-mini-canvas");
  if (!canvas) return false;
  const nodes = Array.from(canvas.querySelectorAll(".live-graph-mini-node[data-graph-node-id]"));
  const node = nodes.find((item) => item.dataset.graphNodeId === nodeId) || canvas.querySelector(".live-graph-mini-node.node-selected") || canvas.querySelector(".live-graph-mini-node.node-active");
  if (!node) return false;
  const scale = Number.parseFloat(canvas.dataset.liveGraphScale || "1") || 1;
  const x = Number.parseFloat(node.style.left || "0") || 0;
  const y = Number.parseFloat(node.style.top || "0") || 0;
  const margin = 56;
  const nodeLeft = x * scale;
  const nodeTop = y * scale;
  const nodeRight = (x + LIVE_RUNTIME_MAP_NODE_WIDTH) * scale;
  const nodeBottom = (y + LIVE_RUNTIME_MAP_NODE_HEIGHT) * scale;
  const viewLeft = canvas.scrollLeft;
  const viewTop = canvas.scrollTop;
  const viewRight = viewLeft + canvas.clientWidth;
  const viewBottom = viewTop + canvas.clientHeight;
  const alreadyVisible = nodeLeft >= viewLeft + margin
    && nodeRight <= viewRight - margin
    && nodeTop >= viewTop + margin
    && nodeBottom <= viewBottom - margin;
  if (!options.force && alreadyVisible) return true;
  const targetLeft = Math.max(0, (x + LIVE_RUNTIME_MAP_NODE_WIDTH / 2) * scale - canvas.clientWidth / 2);
  const targetTop = Math.max(0, (y + LIVE_RUNTIME_MAP_NODE_HEIGHT / 2) * scale - canvas.clientHeight / 2);
  if (Math.abs(canvas.scrollLeft - targetLeft) < 8 && Math.abs(canvas.scrollTop - targetTop) < 8) return true;
  canvas.scrollTo({
    left: targetLeft,
    top: targetTop,
    behavior: options.instant ? "auto" : "smooth",
  });
  return true;
}

function recordLiveContextAction(action, agentId, payload = {}) {
  return recordLiveOperatorEvent(
    action,
    `${liveAgentLabel(agentId || liveSelectedAgent)} context action: ${action}`,
    { ...payload, context_action: action, context_agent: agentId || liveSelectedAgent },
    "operator.context"
  );
}

function handleContextAction(action, agentId) {
  liveSelectedAgent = agentId || liveSelectedAgent;
  liveReportPage = "agent";
  requestLiveGraphFocusForAgent(liveSelectedAgent);
  setLiveChatTargetMode(liveChatTargetForAgent(liveSelectedAgent));
  closeBinderContextMenu();
  recordLiveContextAction(action, liveSelectedAgent).catch(() => {});
  if (action === "open_report") {
    setLiveView("report");
    renderLiveRuntime(liveLastSession);
    return;
  }
  if (action === "open_backend" || action === "show_tool_calls") {
    setLiveView("backend");
    renderLiveRuntime(liveLastSession);
    return;
  }
  if (action === "show_artifacts") {
    setLiveView("artifacts");
    renderLiveRuntime(liveLastSession);
    return;
  }
  if (action === "open_graph") {
    liveSelectedGraphNodeId = graphNodeIdForAgent(liveSelectedAgent) || liveSelectedGraphNodeId;
    setLiveView("graph");
    renderLiveRuntime(liveLastSession);
    return;
  }
  if (action === "open_evolution") {
    openEvolutionLab(liveSelectedAgent);
    return;
  }
  if (action === "mark_read") {
    markLiveAgentRead(liveSelectedAgent, liveLastSession);
    renderLiveRuntime(liveLastSession);
    return;
  }
  if (action === "run_node_test" || action === "rerun_from_here") {
    blockLiveExecutionForPendingApproval(action, `${liveAgentLabel(liveSelectedAgent)} context node test`, { source_action: `context.${action}`, target_agent: liveSelectedAgent, target_node_id: graphNodeIdForAgent(liveSelectedAgent) || liveSelectedAgent })
      .then((blocked) => {
        if (blocked) return;
        recordLiveIntentEvent("node_rerun_requested", action, `${liveAgentLabel(liveSelectedAgent)} node test requested from binder context.`, { source_action: `context.${action}`, target_agent: liveSelectedAgent, target_node_id: graphNodeIdForAgent(liveSelectedAgent) || liveSelectedAgent }).catch(() => {});
        runSelectedNodeTest(liveLastSession.state || {}).catch((err) => setChatStatus(`NODE TEST ERROR: ${err}`, "warning"));
      })
      .catch((err) => setChatStatus(`NODE TEST ERROR: ${err}`, "warning"));
  }
}


