document.addEventListener("keydown", (event) => {
  if (liveDesignCaptureViewerOpen) {
    if (event.key === "Escape") {
      event.preventDefault();
      closeDesignCaptureViewer();
      return;
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      moveDesignCaptureViewer(-1);
      return;
    }
    if (event.key === "ArrowRight") {
      event.preventDefault();
      moveDesignCaptureViewer(1);
      return;
    }
  }
  const section = event.target.closest && event.target.closest(".live-report-section[data-report-section-title]");
  if (section && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    selectLiveReportSection(section.dataset.reportSectionTitle || "");
    return;
  }
  const deviceCard = event.target.closest && event.target.closest(".live-device-card[data-device-event-key]");
  if (deviceCard && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    focusDeviceEventFromCard(deviceCard).catch((err) => setChatStatus(`DEVICE TRACE ERROR: ${err}`, "warning"));
    return;
  }
  const bridgeAction = event.target.closest && event.target.closest("[data-bridge-action]");
  if (bridgeAction && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    runBridgeContractAction(bridgeAction).catch((err) => setChatStatus(`BRIDGE ACTION ERROR: ${err}`, "warning"));
    return;
  }
  const visionRuntimeAction = event.target.closest && event.target.closest("[data-vision-runtime-action]");
  if (visionRuntimeAction && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    runLiveUtmRuntimeAction(visionRuntimeAction.dataset.visionRuntimeAction || "", visionRuntimeAction).catch(() => {});
    return;
  }
  const equipmentLiveAction = event.target.closest && event.target.closest("[data-equipment-live-action]");
  if (equipmentLiveAction && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    runEquipmentLiveAction(equipmentLiveAction.dataset.equipmentLiveAction || "", equipmentLiveAction).catch(() => {});
    return;
  }
  const descriptorAction = event.target.closest && event.target.closest("[data-descriptor-api-action]");
  if (descriptorAction && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    runDescriptorAction(descriptorAction).catch((err) => setChatStatus(`DESCRIPTOR ACTION ERROR: ${err}`, "warning"));
    return;
  }
  const descriptorHandoff = event.target.closest && event.target.closest("[data-descriptor-workspace-handoff]");
  if (descriptorHandoff && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    openDescriptorWorkspaceHandoff(descriptorHandoff).catch((err) => setChatStatus(`DESCRIPTOR HANDOFF ERROR: ${err}`, "warning"));
    return;
  }
  runLiveKeyboardShortcut(event);
});

